INSERT INTO "scholarships" (id, title, provider, link, description, countries, regions, eligible_levels, eligible_regions, eligible_cities, residency_required, eligible_school_types, eligible_courses_psced, eligible_courses_specific, citizenship_required, max_income_threshold, min_gwa_normalized, min_age, max_age, provider_type, scholarship_type, priority_groups, preferred_extracurriculars, preferred_awards, benefit_tuition, benefit_allowance_monthly, benefit_books, benefit_miscellaneous, benefit_total_value, required_documents, has_qualifying_exam, has_interview, has_essay_requirement, has_return_service, application_deadline, application_open_date, academic_year_target, is_active, level, needs_tags, source, last_open_date, last_close_date, cycle_type, last_verified_at, verification_source, confidence_score, data_status, link_status, link_last_checked_at, link_failure_count, sponsor_id, dedupe_key, members_only, image_url, image_alt, application_status, data_completeness_score, eligible_schools, eligible_school_systems, eligible_school_categories, eligible_year_levels, eligible_enrollment_status, deadline_precision, deadline_note, deadline_source_url, verified_by, next_review_date, opportunity_type, type_attributes, organization_id, editorial_state) VALUES (25, 'Pasig City Regular Academic Scholarship', 'Pasig City Government', 'https://scholars.pasigcity.gov.ph', 'The Pasig City Regular Academic Scholarship is designed for residents of Pasig City who demonstrate high academic performance and are enrolled in recognized higher education institutions. This program provides comprehensive tuition assistance and stipends to support college education for local youths. Applicants must maintain a minimum GWA of 85% or equivalent, with no grade lower than 85% in any subject. Eligibility requires presenting a valid Pasig City LGU ID or Barangay Certificate of Residency proving at least 3 years of residency, and registered voter status for parents or applicants of legal age. Application steps involve registering online via the official Pasig Scholarship portal, uploading scanned requirements, and attending an orientation once approved. Highly recurring cycle opening every first semester of the academic year. Financial need is factored via an annual family income cap of 300,000 PHP.', '', '', '[''College'']', '[''NCR'']', '[''Pasig'']', TRUE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All accredited undergraduate degrees'']', 'Filipino', 300000, 85.0, 16, 30, 'LGU', 'Merit-and-Need', '[''4Ps/Listahanan'']', '[]', '[]', TRUE, 1500, TRUE, NULL, 25000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''GOOD_MORAL'', ''TOR'']', TRUE, TRUE, FALSE, FALSE, '2026-08-15', '2026-07-01', '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-07-05', '2025-08-20', 'annual', '2026-07-26 00:00:00', 'manual', 0.0, 'needs_review', 'broken', '2026-08-02 21:45:46.477730', 34, NULL, '4ebc5ddc93c0dd225233b1e4eba12994c93637144e1032b7c2be308aaab3a1d2', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/25/90b85cb1.webp', 'Pasig City Regular Academic Scholarship', 'needs_verification', 0, '[]', '[]', '[]', '[]', '[]', 'exact', NULL, NULL, NULL, NULL, 'scholarship', NULL, 36, 'needs_review');
