'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''SUC and LCU courses'']', 'Filipino', 250000, 80.0, NULL, NULL, 'LGU', 'Merit-and-Need', '[''LCU Students'', ''SUC'']', '[]', '[]', FALSE, 1500, TRUE, NULL, 19000, '[''BARANGAY_CERT'', ''TOR'']', FALSE, FALSE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2026-01-05', '2026-07-31', 'semester', NULL, 'csv_import', 0.72, 'needs_review', 'ok', '2026-08-02 21:42:39.266006', 0, NULL, '0adb2b3169ffc681dc6273b7b29a2a3a27e1e82204a6119dfb93e07ffe950b7f', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/29/4cb75a79.webp', 'Taguig LANI LCU and SUC Assistance Scholarship', 'needs_verification', 72, '[]', '[]', '[]', '[]', '[]', 'exact', NULL, NULL, NULL, NULL, 'scholarship', NULL, 37, 'published');
