 TRUE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''Education'', ''Medical'', ''Business'']', '[''Board or Bar review courses'']', 'Filipino', 600000, NULL, NULL, NULL, 'LGU', 'Affiliation', '[''Board Exam Takers'']', '[]', '[]', FALSE, NULL, TRUE, NULL, 30000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''TOR'']', FALSE, FALSE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-04-05', '2026-05-30', 'rolling', '2026-07-26 00:00:00', 'manual', 0.0, 'active', 'ok', '2026-08-02 21:44:43.242785', 0, NULL, '600bce1fa29d430f01e1d8330f4d52f9cae5828547f4a63221d68069d109d53c', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/30/4cb75a79.webp', 'Taguig Lifeline Bar and Board Review Assistance', 'open', 0, '[]', '[]', '[]', '[]', '[]', 'exact', NULL, NULL, NULL, NULL, 'scholarship', NULL, 37, 'published');
