ng'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Arts'']', '[''All undergraduate offerings'']', 'Filipino', NULL, 90.0, NULL, NULL, 'Institutional', 'Merit-based', '[''Elite DCAT Performers'']', '[]', '[]', TRUE, 8000, TRUE, NULL, 250000, '[''TOR'', ''GOOD_MORAL'']', TRUE, TRUE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-15', '2026-06-30', 'annual', '2026-07-26 00:00:00', 'manual', 0.0, 'active', 'ok', '2026-08-02 21:45:56.658560', 0, NULL, 'c3690ff97488f59d4ea154aa74166907ae6122f7c8c5935e734caf0f0fcde661', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/43/a46beb35.webp', 'DLSU Star Scholars Program', 'open', 0, '[''de-la-salle-university'']', '[]', '[]', '[]', '[]', 'exact', NULL, NULL, NULL, NULL, 'scholarship', NULL, 47, 'published');
