ivic service within the student''s home municipality.', '', '', '[''College'']', '[''Region VII - Central Visayas'']', '[]', TRUE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All accredited degrees in Cebu'']', 'Filipino', 200000, 85.0, NULL, NULL, 'LGU', 'Need', '[''Provincial Rural Youth'']', '[]', '[]', FALSE, NULL, TRUE, NULL, 20000, '[''BARANGAY_CERT'', ''TOR'', ''ITR'']', FALSE, FALSE, FALSE, TRUE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-06-15', '2026-07-15', 'annual', NULL, 'csv_import', 0.72, 'needs_review', 'ok', '2026-08-02 21:44:27.363600', 0, NULL, '1fb13f248884a4004112a17a39ba636c594382227a13a3f1600798682b8bab18', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/49/f0c09197.webp', 'Cebu Province CP GIFTS Program', 'needs_verification', 72, '[]', '[]', '[]', '[]', '[]', 'exact', NULL, NULL, NULL, NULL, 'scholarship', NULL, 9, 'needs_review');
