[''NCR'']', '[''Parañaque'']', TRUE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All undergraduate paths'']', 'Filipino', 300000, 80.0, NULL, NULL, 'LGU', 'Merit-and-Need', '[''General College Residents'']', '[]', '[]', FALSE, NULL, TRUE, NULL, 12000, '[''BARANGAY_CERT'', ''TOR'', ''BIRTH_CERT'']', FALSE, FALSE, FALSE, FALSE, '2026-08-20', '2026-07-01', '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-07-10', '2025-08-25', 'semester', NULL, 'csv_import', 0.81, 'needs_review', 'broken', '2026-08-02 21:43:40.766518', 34, NULL, 'fcdb1cf1d7bb64d8740fcc00e91f5bf27c20fa4c33b35a31fbbcfe8f97ef16c4', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/50/704e7930.webp', 'Parañaque City Tertiary Education Financial Assistance Program', 'needs_verification', 81, '[]', '[]', '[]', '[]', '[]', 'exact', NULL, NULL, NULL, NULL, 'scholarship', NULL, 5, 'needs_review');
