INSERT INTO "scholarships" (id, title, provider, link, description, countries, regions, eligible_levels, eligible_regions, eligible_cities, residency_required, eligible_school_types, eligible_courses_psced, eligible_courses_specific, citizenship_required, max_income_threshold, min_gwa_normalized, min_age, max_age, provider_type, scholarship_type, priority_groups, preferred_extracurriculars, preferred_awards, benefit_tuition, benefit_allowance_monthly, benefit_books, benefit_miscellaneous, benefit_total_value, required_documents, has_qualifying_exam, has_interview, has_essay_requirement, has_return_service, application_deadline, application_open_date, academic_year_target, is_active, level, needs_tags, source, last_open_date, last_close_date, cycle_type, last_verified_at, verification_source, confidence_score, data_status, link_status, link_last_checked_at, link_failure_count, sponsor_id, dedupe_key, members_only, image_url, image_alt, application_status, data_completeness_score, eligible_schools, eligible_school_systems, eligible_school_categories, eligible_year_levels, eligible_enrollment_status, deadline_precision, deadline_note, deadline_source_url, verified_by, next_review_date, opportunity_type, type_attributes, organization_id, editorial_state) VALUES (92, 'Pasig City Sports Scholarship', 'Pasig City Government', 'https://scholars.pasigcity.gov.ph', 'The Pasig City Sports Scholarship caters to outstanding student-athletes who have represented Pasig City or their schools in regional, national, or international athletic competitions. It aims to support athletes in balancing academic progression with rigorous athletic training. Eligibility includes verified residency in Pasig City for 3 years, a minimum GWA of 80% to ensure academic compliance, and official endorsements from the Pasig Sports Development Office. Financial aid covers partial tuition and a monthly training stipend. Renewal requires active sports participation and maintaining passing marks. Portal registrations open annually in August.', '', '', '[''College'', ''Grade 11'', ''Grade 12'']', '[''NCR'']', '[''Pasig'']', TRUE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All courses'']', 'Filipino', 350000, 80.0, NULL, NULL, 'LGU', 'Affiliation', '[''Student Athletes'']', '[]', '[]', TRUE, 2000, TRUE, NULL, 30000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''FORM_137'']', FALSE, TRUE, FALSE, FALSE, '2026-09-10', '2026-08-01', '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-08-05', '2025-09-15', 'annual', NULL, 'csv_import', 0.42, 'needs_review', 'broken', '2026-08-02 21:45:26.462599', 8, NULL, '4dfa54a55ed7df2da5c4012ce61d7dcae6f37f63d68ef2c1a8efafa59d42779e', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/92/90b85cb1.webp', 'Pasig City Sports Scholarship', 'needs_verification', 42, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
