, '[''Pasig'']', TRUE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''ALS and TVET short courses'']', 'Filipino', 200000, 75.0, NULL, NULL, 'LGU', 'Need', '[''Out of School Youth'']', '[]', '[]', TRUE, 2500, TRUE, NULL, 35000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''4PS_CERT'']', FALSE, TRUE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-06-20', '2026-07-30', 'annual', NULL, 'csv_import', 0.36, 'needs_review', 'broken', '2026-08-02 21:45:23.070087', 8, NULL, '519de69b3565064078e0a20d20e42a8642579816e6fa387f66520c727c9574af', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/93/90b85cb1.webp', 'Pasig City Out-of-School Learners Scholarship', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
