', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All approved degree programs'']', 'Filipino', 450000, 85.0, NULL, NULL, 'LGU', 'Merit-and-Need', '[''Middle Income Learners'']', '[]', '[]', TRUE, 2000, TRUE, NULL, 50000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''TOR'', ''ITR'']', FALSE, TRUE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2026-01-05', '2026-07-31', 'semester', NULL, 'csv_import', 0.36, 'needs_review', 'ok', '2026-08-02 21:43:54.626290', 0, NULL, 'e535c7930736630797e85ac28798fc0b4c81cc9848800d8a5e26ceff7ffff3de', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/95/4cb75a79.webp', 'Taguig LANI Full Scholarship', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'published');
INSERT INTO "scholarships" (id, title, provider, link, description, countries, regions, eligible_levels, eligible_regions, eligible_cities, residency_required, eligible_school_types, eligible_courses_psced, eligible_courses_specific, citizenship_required, max_income_threshold, min_gwa_normalized, min_age, max_age, provider_type, scholarship_type, priority_groups, preferred_extracurriculars, preferred_awards, benefit_tuition, benefit_allowance_monthly, benefit_books, benefit_miscellaneous, benefit_total_value, required_documents, has_qualifying_exam, has_interview, has_essay_requirement, has_return_service, application_deadline, application_open_date, academic_year_target, is_active, level, needs_tags, source, last_open_date, last_close_date, cycle_type, last_verified_at, verification_source, confidence_score, data_status, link_status, link_last_checked_at, link_failure_count, sponsor_id, dedupe_key, members_only, image_url, image_alt, application_status, data_completeness_score, eligible_schools, eligible_school_systems, eligible_school_categories, eligible_year_levels, eligible_enrollment_status, deadline_precision, deadline_note, deadline_source_url, verified_by, next_review_date, opportunity_type, type_attributes, organization_id, editorial_state) VALUES (96, 'Taguig LANI Basic Scholarship', 'Taguig City Government', 'https://tcu.edu.ph/lani-scholarship', 'The LANI Basic Scholarship is a broad-access financial assistance grant for Taguig residents enrolled in non-priority programs across public or private institutions. It operates under a lower academic barrier, requiring only a passing GWA of 78% (3.0 or equivalent). It guarantees basic equity support, providing 10,000 PHP per semester to handle textbooks, uniform fees, and transportation costs. Verification of local voter registration is strictly checked during the mandatory manual verification phase.', '', '', '[''College'']', '[''NCR'']', '[''Taguig'']', TRUE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All undergraduate degrees'']', 'Filipino', 300000, 78.0, NULL, NULL, 'LGU', 'Need', '[''Low Income Families'']', '[]', '[]', FALSE, 1000, TRUE, NULL, 20000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''TOR'']', FALSE, FALSE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2026-01-05', '2026-07-31', 'semester', NULL, 'csv_import', 0.36, 'needs_review', 'ok', '2026-08-02 21:45:11.517402', 0, NULL, '63b057456d8492b7027fa552b3ea79dada264a71e4ea78a67a10f2755ae0f5cf', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/96/4cb75a79.webp', 'Taguig LANI Basic Scholarship', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'published');
