UE, '[''Public'', ''Private'']', '[''STEM'', ''Education'', ''Medical'', ''Business'']', '["Master''s and Doctoral Programs"]', 'Filipino', 750000, 85.0, NULL, NULL, 'LGU', 'Merit-based', '[''Public Servants and Teachers'']', '[]', '[]', TRUE, 2000, TRUE, NULL, 80000, '[''BARANGAY_CERT'', ''TOR'', ''ESSAY'']', FALSE, TRUE, TRUE, TRUE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-20', '2026-06-30', 'annual', NULL, 'csv_import', 0.36, 'needs_review', 'ok', '2026-08-02 21:46:15.714847', 0, NULL, 'eb2c45c5a0e5f83ba1b92d68247eacd8e03f1a0ae1652ff88f4d8beaea472b9c', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/97/4cb75a79.webp', 'Taguig LANI LEAD Graduate Scholarship', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
INSERT INTO "scholarships" (id, title, provider, link, description, countries, regions, eligible_levels, eligible_regions, eligible_cities, residency_required, eligible_school_types, eligible_courses_psced, eligible_courses_specific, citizenship_required, max_income_threshold, min_gwa_normalized, min_age, max_age, provider_type, scholarship_type, priority_groups, preferred_extracurriculars, preferred_awards, benefit_tuition, benefit_allowance_monthly, benefit_books, benefit_miscellaneous, benefit_total_value, required_documents, has_qualifying_exam, has_interview, has_essay_requirement, has_return_service, application_deadline, application_open_date, academic_year_target, is_active, level, needs_tags, source, last_open_date, last_close_date, cycle_type, last_verified_at, verification_source, confidence_score, data_status, link_status, link_last_checked_at, link_failure_count, sponsor_id, dedupe_key, members_only, image_url, image_alt, application_status, data_completeness_score, eligible_schools, eligible_school_systems, eligible_school_categories, eligible_year_levels, eligible_enrollment_status, deadline_precision, deadline_note, deadline_source_url, verified_by, next_review_date, opportunity_type, type_attributes, organization_id, editorial_state) VALUES (98, 'Makati City Premier and Specialized School Scholarship', 'Makati City Government', 'https://www.makati.gov.ph', 'The Makati City Government Scholarship Program offers elite financial backing to top-tier Makati residents who secure admission into designated Centers of Excellence or top private universities (such as DLSU, ADMU, UST, Mapua). Applicants must provide proof of at least 5 years of continuous city residency, valid Makati LGU ID/QCitizen equivalent, and rank in the top 10% of their graduating Senior High School class. It supplies up to 80,000 PHP annually for tuition and institutional fees. Recipients must sign a contract committing to a mandatory 2-year return service within the Makati LGU or city public school system upon graduation. GWA maintenance of 88% (1.75) is strictly audited per semester.', '', '', '[''College'']', '[''NCR'']', '[''Makati'']', TRUE, '[''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'']', '[''Elite institutional programs'']', 'Filipino', 500000, 88.0, NULL, NULL, 'LGU', 'Merit-based', '[''Top 10 Percent Graduates'']', '[]', '[]', TRUE, 4000, TRUE, NULL, 80000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''TOR'', ''GOOD_MORAL'']', TRUE, TRUE, FALSE, TRUE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-06-02', '2026-07-15', 'annual', NULL, 'csv_import', 0.36, 'needs_review', 'ok', '2026-08-02 21:45:24.918677', 0, NULL, 'c21a82a8eb4e02fec103ba215f19dfaf6413c1f241705832190881949c0a4b4d', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/98/5072587b.webp', 'Makati City Premier and Specialized School Scholarship', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
INSERT INTO "scholarships" (id, title, provider, link, description, countries, regions, eligible_levels, eligible_regions, eligible_cities, residency_required, eligible_school_types, eligible_courses_psced, eligible_courses_specific, citizenship_required, max_income_threshold, min_gwa_normalized, min_age, max_age, provider_type, scholarship_type, priority_groups, preferred_extracurriculars, preferred_awards, benefit_tuition, benefit_allowance_monthly, benefit_books, benefit_miscellaneous, benefit_total_value, required_documents, has_qualifying_exam, has_interview, has_essay_requirement, has_return_service, application_deadline, application_open_date, academic_year_target, is_active, level, needs_tags, source, last_open_date, last_close_date, cycle_type, last_verified_at, verification_source, confidence_score, data_status, link_status, link_last_checked_at, link_failure_count, sponsor_id, dedupe_key, members_only, image_url, image_alt, application_status, data_completeness_score, eligible_schools, eligible_school_systems, eligible_school_categories, eligible_year_levels, eligible_enrollment_status, deadline_precision, deadline_note, deadline_source_url, verified_by, next_review_date, opportunity_type, type_attributes, organization_id, editorial_state) VALUES (99, 'University of Makati Special Institutional Scholarship', 'University of Makati (UMak)', 'https://www.umak.edu.ph', 'UMak''s Special Institutional Scholarship provides targeted need-and-affiliation assistance for unique sectors inside the university community, including registered PWD students, certified children of active Makati LGU employees, barangay officials, and student-artists in the UMak cultural troupe. It provides complete fee exemptions and a monthly book allowance of 1,000 PHP. Candidates must hold a GWA of 75% (passing) with no dropped or incomplete modules. Formal verification requires presenting civil service certificates or PWD IDs.', '', '', '[''College'', ''TVET'']', '[''NCR'']', '[''Makati'']', TRUE, '[''Public'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Arts'']', '[''All UMak offerings'']', 'Filipino', 350000, 75.0, NULL, NULL, 'Institutional', 'Affiliation', '[''PWD'', ''LGU Dependents'']', '[]', '[]', TRUE, 1000, TRUE, NULL, 15000, '[''BARANGAY_CERT'', ''TOR'', ''BIRTH_CERT'']', FALSE, TRUE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-15', '2026-06-25', 'semester', NULL, 'csv_import', 0.36, 'needs_review', 'broken', '2026-08-02 21:46:22.840052', 8, NULL, 'a4ad7ff94457da1f223c91adf8c7d865b77e929a06f111520470376b2a92f47a', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/99/872aa05b.webp', 'University of Makati Special Institutional Scholarship', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
