ge'', ''TVET'']', '[''NCR'']', '[''Navotas'']', TRUE, '[''Public'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All available courses'']', 'Filipino', 180000, 78.0, NULL, NULL, 'LGU', 'Need', '[''Fisherfolk Children'']', '[]', '[]', TRUE, 1500, TRUE, NULL, 20000, '[''BARANGAY_CERT'', ''BIRTH_CERT'', ''TOR'']', FALSE, FALSE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-06-05', '2026-07-10', 'annual', NULL, 'csv_import', 0.36, 'needs_review', 'ok', '2026-08-02 21:45:14.448417', 0, NULL, 'b47953d510407e0932dafe57cbc8952e9d0961dbd589f2e10a51aeea1f318dd0', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/100/470130fc.webp', 'NavotaAs Fisherfolk Children Scholarship Track', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
