]', '[]', '[]', FALSE, '[''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Arts'']', '[''All undergraduate degree courses'']', 'Filipino', 700000, 85.0, NULL, NULL, 'Institutional', 'Need', '[''High Financial Need'']', '[]', '[]', TRUE, 3500, TRUE, NULL, 180000, '[''ITR'', ''BARANGAY_CERT'', ''TOR'', ''BIRTH_CERT'']', TRUE, TRUE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2026-01-10', '2026-07-15', 'semester', NULL, 'csv_import', 0.28, 'needs_review', 'ok', '2026-08-02 21:46:38.819858', 0, NULL, '5479c4ed0a244c88084c6a41ccb9628ae82e0fc8971020a255e9c1eee82a48ca', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/106/a46beb35.webp', 'DLSU St La Salle Financial Assistance Grant', 'needs_verification', 28, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
