]', '[''All undergraduate degrees'']', 'Filipino', 300000, 88.0, NULL, NULL, 'Institutional', 'Merit-and-Need', '[''Public High School Grads'']', '[]', '[]', TRUE, 4000, TRUE, NULL, 190000, '[''FORM_137'', ''BARANGAY_CERT'', ''BIRTH_CERT'']', TRUE, TRUE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-15', '2026-06-30', 'annual', NULL, 'csv_import', 0.28, 'needs_review', 'ok', '2026-08-02 21:42:41.196854', 0, NULL, '06741bb33292c907733633d508d1c29c4b319e3097ba4cd8aa0274afb945a930', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/107/a46beb35.webp', 'DLSU Vaugirard Scholarship Program', 'needs_verification', 28, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
