e'']', '[''NCR'']', '[]', FALSE, '[''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Arts'']', '[''All UST college programs'']', 'Filipino', 250000, 82.0, NULL, NULL, 'Institutional', 'Affiliation', '[''Student Assistants'']', '[]', '[]', TRUE, NULL, TRUE, NULL, 60000, '[''TOR'', ''BARANGAY_CERT'', ''GOOD_MORAL'', ''ITR'']', FALSE, TRUE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-20', '2026-06-30', 'semester', NULL, 'csv_import', 0.36, 'needs_review', 'ok', '2026-08-02 21:45:21.301330', 0, NULL, '51eb1cd10dc7547b7afc6145dd6f6d2944cb743bb6507a0af5bc509ee3e0cd7f', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/108/541156c9.webp', 'UST San Lorenzo Ruiz Student Assistance Scholarship', 'needs_verification', 36, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
