ess'', ''Arts'']', '[''All university programs'']', 'Filipino', NULL, 88.0, NULL, NULL, 'Institutional', 'Merit-based', '[''High School Honor Grads'']', '[]', '[]', TRUE, NULL, FALSE, NULL, 100000, '[''FORM_137'', ''GOOD_MORAL'']', TRUE, FALSE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-20', '2026-06-30', 'annual', NULL, 'csv_import', 0.3, 'needs_review', 'ok', '2026-08-02 21:43:57.081238', 0, NULL, 'b3656457333aa3d54f5f2082db570382d40ace04d0db83eb2cfaf502feaf0bf4', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/109/541156c9.webp', 'UST Santo Tomas Academic Scholarship', 'needs_verification', 30, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
