INSERT INTO "scholarships" (id, title, provider, link, description, countries, regions, eligible_levels, eligible_regions, eligible_cities, residency_required, eligible_school_types, eligible_courses_psced, eligible_courses_specific, citizenship_required, max_income_threshold, min_gwa_normalized, min_age, max_age, provider_type, scholarship_type, priority_groups, preferred_extracurriculars, preferred_awards, benefit_tuition, benefit_allowance_monthly, benefit_books, benefit_miscellaneous, benefit_total_value, required_documents, has_qualifying_exam, has_interview, has_essay_requirement, has_return_service, application_deadline, application_open_date, academic_year_target, is_active, level, needs_tags, source, last_open_date, last_close_date, cycle_type, last_verified_at, verification_source, confidence_score, data_status, link_status, link_last_checked_at, link_failure_count, sponsor_id, dedupe_key, members_only, image_url, image_alt, application_status, data_completeness_score, eligible_schools, eligible_school_systems, eligible_school_categories, eligible_year_levels, eligible_enrollment_status, deadline_precision, deadline_note, deadline_source_url, verified_by, next_review_date, opportunity_type, type_attributes, organization_id, editorial_state) VALUES (125, 'DOH Medical Scholarship and Return Service Program', 'Department of Health', 'https://doh.gov.ph', 'The DOH Medical Scholarship and Return Service (MSRS) Program is a major sector-specific government intervention operating under the ''Doktor Para sa Bayan'' Act (RA 11509) in partnership with CHED. It funds full medical education (Doctor of Medicine) for qualified Filipino students across certified state and partner private universities. It covers 100% of tuition, laboratory fees, provides a high monthly living allowance of 15,000 PHP, a specialized book/equipment allowance of 20,000 PHP per semester, and basic board exam review subsidies. Eligible applicants must hold a Bachelor''s degree with a solid GWA, pass the medical school entrance and NMAT, and prioritize low-income roots or origin from underserved rural towns. Return service requires serving as a public health officer in a government hospital or rural health unit (RHU) for 1 year for every year of scholarship.', '', '', '[''Graduate'']', '[]', '[]', FALSE, '[''Public'', ''Private'']', '[''Medical'']', '[''Doctor of Medicine (MD)'']', 'Filipino', 600000, 85.0, NULL, NULL, 'Government', 'Merit-and-Need', '[''Rural Public Health'']', '[]', '[]', TRUE, 15000, TRUE, NULL, 250000, '[''TOR'', ''BIRTH_CERT'', ''GOOD_MORAL'', ''ITR'', ''ESSAY'']', TRUE, TRUE, TRUE, TRUE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-15', '2025-07-05', 'annual', NULL, 'csv_import', 0.28, 'needs_review', 'broken', '2026-08-02 21:43:42.627992', 8, NULL, 'ad8af4e5d4e5af8416cecfc4c83ab2b9ab44b2bba9923ae242f0ec3560c904f2', FALSE, 'https://ykrinwegrgabjaltbbwz.supabase.co/storage/v1/object/public/scholarship-images/125/e98944a0.webp', 'DOH Medical Scholarship and Return Service Program', 'needs_verification', 28, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, NULL, 'needs_review');
INSERT INTO "scholarships" (id, title, provider, link, description, countries, regions, eligible_levels, eligible_regions, eligible_cities, residency_required, eligible_school_types, eligible_courses_psced, eligible_courses_specific, citizenship_required, max_income_threshold, min_gwa_normalized, min_age, max_age, provider_type, scholarship_type, priority_groups, preferred_extracurriculars, preferred_awards, benefit_tuition, benefit_allowance_monthly, benefit_books, benefit_miscellaneous, benefit_total_value, required_documents, has_qualifying_exam, has_interview, has_essay_requirement, has_return_service, application_deadline, application_open_date, academic_year_target, is_active, level, needs_tags, source, last_open_date, last_close_date, cycle_type, last_verified_at, verification_source, confidence_score, data_status, link_status, link_last_checked_at, link_failure_count, sponsor_id, dedupe_key, members_only, image_url, image_alt, application_status, data_completeness_score, eligible_schools, eligible_school_systems, eligible_school_categories, eligible_year_levels, eligible_enrollment_status, deadline_precision, deadline_note, deadline_source_url, verified_by, next_review_date, opportunity_type, type_attributes, organization_id, editorial_state) VALUES (127, 'OWWA Educational Livelihood Assistance Program College Track', 'Overseas Workers Welfare Administration', 'https://owwa.gov.ph', 'The OWWA Educational Livelihood Assistance Program (ELAP) College Track is an allocation reserved for the children or dependents of active or deceased Overseas Filipino Workers (OFWs) who faced sudden distress, repatriation, or death while serving abroad. Distinct from the EDSP/ODSP merit lines, ELAP operates primarily as a livelihood-linked equity framework. It guarantees an educational subsidy of 10,000 PHP per year for the designated student dependent enrolled in any undergraduate college or technical track. Academic evaluation relies on basic passing marks (75% GWA) with no explicit ranking requirements. Online processing must clear the OWWA Regional Welfare Offices.', '', '', '[''College'', ''TVET'']', '[]', '[]', FALSE, '[''Public'', ''Private'']', '[''STEM'', ''Engineering'', ''IT'', ''Education'', ''Medical'', ''Business'', ''Agriculture'', ''Arts'']', '[''All accredited lines'']', 'Filipino', 250000, 75.0, NULL, NULL, 'Government', 'Need', '[''Distressed OFW Dependents'']', '[]', '[]', FALSE, NULL, FALSE, NULL, NULL, '[''OFW_DOCS'', ''BARANGAY_CERT'', ''BIRTH_CERT'', ''TOR'']', FALSE, FALSE, FALSE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2025-05-05', '2026-07-15', 'annual', '2026-08-01 06:44:10.574673', 'csv_import', 0.19, 'expired', 'timeout', '2026-08-02 21:45:44.923751', 2, NULL, '9ccea555637900a7f73841c4a8f85c0c6dc859817a04e77a31e66fd0d20fc29d', FALSE, NULL, NULL, 'expected_reopen', 19, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, 18, 'published');
