no', NULL, 75.0, NULL, NULL, 'Private', 'Merit-and-Need', '[]', '[]', '[]', TRUE, NULL, FALSE, NULL, NULL, '[''TOR'', ''GOOD_MORAL'', ''ESSAY'']', FALSE, TRUE, TRUE, FALSE, NULL, NULL, '2026-2027', TRUE, NULL, '[]', 'gemini_research', '2026-04-28', '2026-06-30', 'annual', '2026-08-01 06:44:11.600657', 'csv_import', 0.15, 'expired', 'ok', '2026-08-02 21:44:31.786606', 0, NULL, '5cf484eb13401735370c1a99d50099875af66010f68c0bc36c471336040eb52a', FALSE, NULL, NULL, 'expected_reopen', 15, '[]', '[]', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'scholarship', NULL, 28, 'published');
