INSERT INTO "field_evidence" (id, scholarship_id, field_key, value_snapshot, source_url, source_type, evidence_snippet, confidence, retrieved_at, reviewer_id, superseded_at, created_at) VALUES (52, 13, 'description', 'ISKONNECT id 13 ''Metrobank Foundation Scholarship'' is generic. Official Metrobank Foundation site references MetroGold/MSP and education grants; ACCESS (Assistance for the Completion of College Education for Superior Students) is the flagship undergraduate program cited in research with distinct exam requirement and 50 slots annually. Rename and enrich id 13 to ACCESS Program with official primary_link to Metrobank Foundation education grants page. Do not add duplicate unless MSP and ACCESS are confirmed as separate active programs.', 'https://www.mbfoundation.org.ph/grants/grants-education/about-the-metrogold-scholarship-program-msp/', 'duplicate_resolution', 'ISKONNECT id 13 ''Metrobank Foundation Scholarship'' is generic. Official Metrobank Foundation site references MetroGold/MSP and education grants; ACCESS (Assistance for the Completion of College Education for Superior Students) is the flagship undergraduate program cited in research with distinct exam requirement and 50 slots annually.', 0.75, '2026-07-26 09:40:25.169599', NULL, NULL, '2026-07-26 09:40:24.840505');
