INSERT INTO "field_evidence" (id, scholarship_id, field_key, value_snapshot, source_url, source_type, evidence_snippet, confidence, retrieved_at, reviewer_id, superseded_at, created_at) VALUES (55, 14, 'description', 'ISKONNECT id 14 ''BPI Foundation Scholarship'' is generic. Pagpupugay is a specialized COVID-19 frontliner next-of-kin program (RA-adjacent special project), not the foundation''s general scholarship. Official bpifoundation.org documents distinct eligibility (medical frontliner kin, 85% GWA, partner HEI application). Either split Pagpupugay as separate record OR replace id 14 content if generic BPI scholarship does not exist as standalone program. Pagpupugay AY 2022-2023 deadline on page is stale—verify current cycle before import.', 'https://www.bpifoundation.org/programs/special-projects/pagpupugay-scholarship', 'duplicate_resolution', 'ISKONNECT id 14 ''BPI Foundation Scholarship'' is generic. Pagpupugay is a specialized COVID-19 frontliner next-of-kin program (RA-adjacent special project), not the foundation''s general scholarship. Official bpifoundation.org documents distinct eligibility (medical frontliner kin, 85% GWA, partner HEI application).', 1.0, '2026-07-26 09:40:25.318604', NULL, NULL, '2026-07-26 09:40:24.840505');
