INSERT INTO "field_evidence" (id, scholarship_id, field_key, value_snapshot, source_url, source_type, evidence_snippet, confidence, retrieved_at, reviewer_id, superseded_at, created_at) VALUES (66, 75, 'title', 'Aboitiz Brights (Aboitiz Future Leaders Scholarship)', 'https://www.aboitizfoundation.org/what-we-do/education/aboitiz-future-leaders-scholarship-program/', 'duplicate_resolution', 'ISKONNECT id 75 is titled ''Aboitiz Future Leaders Scholarship Program'' which appears to be the current official brand for Aboitiz Foundation college scholarships. The PDF''s ''Aboitiz Brights'' name could not be independently confirmed on aboitizfoundation.org (503 during verification). The foundation site historically uses Future Leaders branding for incoming sophomore support at partner universities.', 0.75, '2026-07-26 09:40:25.836049', NULL, NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "field_evidence" (id, scholarship_id, field_key, value_snapshot, source_url, source_type, evidence_snippet, confidence, retrieved_at, reviewer_id, superseded_at, created_at) VALUES (67, 75, 'link', 'https://www.aboitizfoundation.org/what-we-do/education/aboitiz-future-leaders-scholarship-program/', 'https://www.aboitizfoundation.org/what-we-do/education/aboitiz-future-leaders-scholarship-program/', 'duplicate_resolution', 'ISKONNECT id 75 is titled ''Aboitiz Future Leaders Scholarship Program'' which appears to be the current official brand for Aboitiz Foundation college scholarships. The PDF''s ''Aboitiz Brights'' name could not be independently confirmed on aboitizfoundation.org (503 during verification). The foundation site historically uses Future Leaders branding for incoming sophomore support at partner universities.', 0.75, '2026-07-26 09:40:25.870950', NULL, NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "field_evidence" (id, scholarship_id, field_key, value_snapshot, source_url, source_type, evidence_snippet, confidence, retrieved_at, reviewer_id, superseded_at, created_at) VALUES (68, 75, 'description', 'ISKONNECT id 75 is titled ''Aboitiz Future Leaders Scholarship Program'' which appears to be the current official brand for Aboitiz Foundation college scholarships. The PDF''s ''Aboitiz Brights'' name could not be independently confirmed on aboitizfoundation.org (503 during verification). The foundation site historically uses Future Leaders branding for incoming sophomore support at partner universities. Do not create duplicate. Review id 75 metadata against latest Aboitiz Foundation education page when site is accessible. If ''Brights'' is confirmed as a distinct sub-program, split then; otherwise treat as naming variant.', 'https://www.aboitizfoundation.org/what-we-do/education/aboitiz-future-leaders-scholarship-program/', 'duplicate_resolution', 'ISKONNECT id 75 is titled ''Aboitiz Future Leaders Scholarship Program'' which appears to be the current official brand for Aboitiz Foundation college scholarships. The PDF''s ''Aboitiz Brights'' name could not be independently confirmed on aboitizfoundation.org (503 during verification). The foundation site historically uses Future Leaders branding for incoming sophomore support at partner universities.', 0.75, '2026-07-26 09:40:25.907011', NULL, NULL, '2026-07-26 09:40:24.840505');
