INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (1, 25, 1, '{"action": "create", "snapshot": {"title": "Pasig City Regular Academic Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "The Pasig City Regular Academic Scholarship is designed for residents of Pasig City who demonstrate high academic performance and are enrolled in recognized higher education institutions. This program provides comprehensive tuition assistance and stipends to support college education for local youths. Applicants must maintain a minimum GWA of 85% or equivalent, with no grade lower than 85% in any subject. Eligibility requires presenting a valid Pasig City LGU ID or Barangay Certificate of Residency proving at least 3 years of residency, and registered voter status for parents or applicants of legal age. Application steps involve registering online via the official Pasig Scholarship portal, uploading scanned requirements, and attending an orientation once approved. Highly recurring cycle opening every first semester of the academic year. Financial need is factored via an annual family income cap of 300,000 PHP.", "min_age": null, "max_age": null, "application_deadline": "2026-08-15", "application_open_date": "2026-07-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Pasig\"]", "max_income_threshold": 300000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:30:07.161194');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (2, 26, 1, '{"action": "create", "snapshot": {"title": "Pasig City Arts and Design Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "This dedicated track supports creative individuals residing in Pasig City who pursue fields in fine arts, digital design, music, performing arts, or literature. Eligible applicants must showcase a portfolio or pass a talent audition managed by the Pasig Cultural Affairs Office. Academic requirements are set at a minimum GWA of 80%. Benefits include school fees financial aid and materials allowances. Registration is completed through the online portal, followed by an in-person portfolio review.", "min_age": null, "max_age": null, "application_deadline": "2026-09-10", "application_open_date": "2026-08-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\", \"Grade 11\", \"Grade 12\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Pasig\"]", "max_income_threshold": 350000, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 12:30:09.923743');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (3, 27, 1, '{"action": "create", "snapshot": {"title": "Taguig LANI Premier Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The Lifeline Assistance for Neighbors in Need (LANI) Premier Scholarship is Taguig City''s flagship merit track for top-tier residents studying in prestigious private universities or high-cost specialized institutions (e.g., UP, DLSU, ADMU, UST, Mapua). Applicants must be registered voters of Taguig for at least 3 years and have a minimum GWA of 90% (1.50 or better) with zero failing grades. It offers substantial financial aid up to 50,000 PHP per semester to directly cover tuition fees and modern learning tools. Applications are submitted via the Taguig LANI portal or at the Taguig Civic Center scholarship desk. Highly structured and strictly recurring every semester.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-06-20", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Taguig\"]", "max_income_threshold": 600000, "min_gwa_normalized": 90.0}}', NULL, '2026-06-30 12:30:23.519120');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (4, 28, 1, '{"action": "create", "snapshot": {"title": "Taguig LANI Priority Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "This specific LANI track directly targets priority fields of study essential for national development and city workforce planning, including STEM, digital engineering, data analytics, special education, and specialized medical courses. Eligible applicants need a minimum GWA of 82%. Financial benefits are elevated compared to basic tracks, supplying up to 30,000 PHP per semester. Priority status is also given to low-income applicants, PWDs, and dependents of solo parents.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-06-20", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Taguig\"]", "max_income_threshold": 350000, "min_gwa_normalized": 82.0}}', NULL, '2026-06-30 12:30:25.606885');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (5, 29, 1, '{"action": "create", "snapshot": {"title": "Taguig LANI LCU and SUC Assistance Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "This scholarship is specially tailored for Taguig residents who are already utilizing the Free Higher Education law at State Universities and Colleges (SUCs) or Local Colleges and Universities (LCUs) like Taguig City University (TCU) or PUP. Since tuition is free, this track converts assistance into a pure monthly cash living stipend of 1,500 PHP plus 2,000 PHP per semester for books. Requires a GWA of 80% and zero failures. Online submission occurs via the unified TCU-LANI interface.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-06-20", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Taguig\"]", "max_income_threshold": 250000, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 12:30:26.876500');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (6, 30, 1, '{"action": "create", "snapshot": {"title": "Taguig Lifeline Bar and Board Review Assistance", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "A specialized, one-time financial grant for Taguig residents who have completed their undergraduate degrees in Law, Engineering, Nursing, Accountancy, or Education and are preparing for professional licensure examinations (PRC Board Exams or Supreme Court Bar Exam). Provides a lump-sum financial grant of 15,000 PHP to 30,000 PHP to pay for review center enrollments and examination fees. Requires graduation proof, a certification from an official review center, and voter verification. No GWA check is enforced post-graduation.", "min_age": null, "max_age": null, "application_deadline": "2026-05-30", "application_open_date": "2026-04-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\", \"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Taguig\"]", "max_income_threshold": 600000, "min_gwa_normalized": null}}', NULL, '2026-06-30 12:30:28.297932');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (7, 31, 1, '{"action": "create", "snapshot": {"title": "Makati City SUC and Priority Courses Scholarship", "provider": "Makati City Government", "source": "gemini_research", "link": "https://www.makati.gov.ph", "description": "This LGU track caters to Makati residents enrolled in State Universities and Colleges (outside of UMak) pursuing priority industrial fields like IT, engineering, and digital science. It grants 20,000 PHP per semester to offset learning materials, transportation, and field training expenses. It requires 5 years of residency and an overall GWA of 82% (2.25) with no grades lower than 80%. Applications are handled through the Makati Education Department at City Hall.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-06-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Makati\"]", "max_income_threshold": 300000, "min_gwa_normalized": 82.0}}', NULL, '2026-06-30 12:30:29.090343');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (8, 32, 1, '{"action": "create", "snapshot": {"title": "University of Makati Token Fee Exemption Program", "provider": "University of Makati (UMak)", "source": "gemini_research", "link": "https://www.umak.edu.ph", "description": "The University of Makati (UMak) Token Fee Exemption Program serves as an institutional academic scholarship that waives the remaining standard token fees for high-performing student residents of Makati. Administered by the UMak Scholarship Office, applicants must achieve a GWA of 1.75 (88%) or better during their semester and maintain a full academic load. The program converts academic excellence directly into fully zeroed tuition liabilities and offers priority enlistment. Application is processed entirely internally through the UMak student portal at the close of every grading period.", "min_age": null, "max_age": null, "application_deadline": "2026-06-25", "application_open_date": "2026-05-10", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Makati\"]", "max_income_threshold": 250000, "min_gwa_normalized": 88.0}}', NULL, '2026-06-30 12:30:36.225020');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (9, 33, 1, '{"action": "create", "snapshot": {"title": "Valenzuela City Dr. Pio Valenzuela Scholarship Program", "provider": "Valenzuela City Government", "source": "gemini_research", "link": "https://valenzuela.gov.ph/drpioscholarship", "description": "The Dr. Pio Valenzuela Scholarship Program is an intensive LGU merit-need initiative by the Valenzuela City Government. It targets financially challenged but academically elite student residents. Eligible individuals must have spent at least 4 consecutive years in Valenzuela City, graduated Senior High School with a GWA of 85% or higher, and hold zero grades lower than 85% in Grades 11 and 12. Crucially, the total annual household income must not exceed 120,000 PHP. The program awards a financial support grant of 30,000 PHP per year (15,000 PHP per semester) for tuition and school compliance. Portal submissions require uploading digital copies of ITR or Indigency certificates, Form 138/137, and Barangay clearance.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-06-15", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Valenzuela\"]", "max_income_threshold": 120000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:30:39.143508');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (10, 34, 1, '{"action": "create", "snapshot": {"title": "NavotaAs Academic College Scholarship", "provider": "Navotas City Government", "source": "gemini_research", "link": "https://www.navotas.gov.ph", "description": "The NavotaAs Academic Scholarship Program is the baseline higher-education track for residents of Navotas City. It supports incoming first-year college students who graduated in the top 25% of their Senior High School class. Eligible applicants must have parents who are registered voters of Navotas. When utilized at the Navotas Polytechnic College (NPC), it yields full tuition exemption plus 22,000 PHP per year for allowances. If the student passes into other prominent universities outside Navotas, the grant upgrades to a merit value of 262,000 PHP per year to handle high tuition. Applications are manually screened by the Navotas Scholarship Secretariat.", "min_age": null, "max_age": null, "application_deadline": "2026-07-10", "application_open_date": "2026-06-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Navotas\"]", "max_income_threshold": 400000, "min_gwa_normalized": 88.0}}', NULL, '2026-06-30 12:30:41.126512');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (11, 35, 1, '{"action": "create", "snapshot": {"title": "Marikina City Medical Scholarship Program", "provider": "Marikina City Government", "source": "gemini_research", "link": "https://www.marikina.gov.ph", "description": "The Marikina City Medical Scholarship Program is a localized government intervention to support aspiring medical doctors who reside in Marikina City. It covers full tuition and provides educational assistance up to 150,000 PHP per year for students accepted into partner Doctor of Medicine programs (including PLM, FEU-NRMF, UST, MCU, St. Luke''s, Our Lady of Fatima University). Applicants must not exceed 30 years of age, must possess a clean record of good moral character, and maintain a household income below 600,000 PHP. Return service dictates that the recipient must practice medicine within the Marikina public healthcare network or city clinics for a duration matching the length of the scholarship.", "min_age": null, "max_age": 30, "application_deadline": "2026-06-15", "application_open_date": "2026-05-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Marikina\"]", "max_income_threshold": 600000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:30:42.207925');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (12, 36, 1, '{"action": "create", "snapshot": {"title": "Cebu City College Scholarship Program", "provider": "Cebu City Government", "source": "gemini_research", "link": "https://www.cebucity.gov.ph", "description": "The Cebu City College Scholarship Program (CCCSP) targets urban youth residents who graduated from public high schools located specifically within the north and south districts of Cebu City. It provides 10,000 PHP per semester for tuition if the recipient enrolls in accredited private universities, or 2,500 PHP per semester for books and uniform allowances if they enter tuition-free SUCs (like CTU or CNU). Requires a voter''s certification from Cebu City and a minimum GWA of 80%. Applications are handled at the Cebu City Sports Complex scholarship secretariat.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-15", "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"Region VII - Central Visayas\"]", "eligible_cities": "[\"Cebu City\"]", "max_income_threshold": 350000, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 12:30:44.282754');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (13, 37, 1, '{"action": "create", "snapshot": {"title": "Davao City STEP FA Category B", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "Administered by Davao City''s EBSU, the STEP Category B serves as the mid-tier merit assistance channel. It requires a baseline GWA of 88% with zero grade deficiencies. It offers a flat grant of 20,000 PHP per semester (40,000 PHP annually) to help cover tuition and computing materials at any CHED-accredited college in Region XI. Candidates must verify local voter status and clear the household income check managed by the local social services office.", "min_age": null, "max_age": null, "application_deadline": "2026-06-15", "application_open_date": "2026-05-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"Region XI - Davao\"]", "eligible_cities": "[\"Davao City\"]", "max_income_threshold": 300000, "min_gwa_normalized": 88.0}}', NULL, '2026-06-30 12:30:45.518671');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (14, 38, 1, '{"action": "create", "snapshot": {"title": "Davao City Special Educational Assistance Program for Lumad", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "The Special Educational Assistance Program (SEAP) for Lumad is a targeted indigenous equity track run by Davao City EBSU. It is exclusively reserved for college students belonging to the recognized Indigenous Cultural Communities (IPs/Lumad) within ancestral domains of Davao City (such as the Ata, Matigsalug, Maranao, and Kagan tribes). It offers a full living subsidy of 15,000 PHP per semester alongside basic tuition assistance. The academic barrier requires a standard passing mark (75% GWA). Crucially, a formal Tribal Certification from the tribal chieftain and validation from the NCIP local office are mandatory documents.", "min_age": null, "max_age": null, "application_deadline": "2026-06-15", "application_open_date": "2026-05-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\", \"TVET\"]", "eligible_regions": "[\"Region XI - Davao\"]", "eligible_cities": "[\"Davao City\"]", "max_income_threshold": 200000, "min_gwa_normalized": 75.0}}', NULL, '2026-06-30 12:30:46.786403');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (15, 39, 1, '{"action": "create", "snapshot": {"title": "Bislig City Collegiate Scholarship Program", "provider": "Bislig City Government", "source": "gemini_research", "link": "https://www.bislig.gov.ph", "description": "The Bislig City Scholarship Program (BCSP) is a localized LGU mandate in Caraga Region enacted to finance undergraduate degrees for local youths. Applicants must confirm 3 consecutive years of residency in Bislig City, present a clean barangay record, and maintain a GWA of 82% throughout college. It provides a flat 12,000 PHP annual educational grant to assist with registration expenses. Submissions are queued physically at the Bislig City Higher Education Desk or via their primary LGU landing page.", "min_age": null, "max_age": null, "application_deadline": "2026-07-20", "application_open_date": "2026-06-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"Region XIII - Caraga\"]", "eligible_cities": "[\"Bislig\"]", "max_income_threshold": 240000, "min_gwa_normalized": 82.0}}', NULL, '2026-06-30 12:30:47.838911');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (16, 40, 1, '{"action": "create", "snapshot": {"title": "Ateneo de Manila University Financial Aid Grant", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo de Manila University College Financial Aid Grant is a premium institutional program covering 100%, 75%, 50%, or 25% of tuition and laboratory fees for undergraduate students displaying high academic potential but deep financial need. Administered by the Office of Admission and Aid (OAA), applicants must submit comprehensive household assets records, utility bills, and parents'' ITRs. It includes an option for a monthly living allowance of 3,000 PHP and book allowances for absolute 100% grant recipients. Renewal requires an annual review of the family''s financial standing and keeping a minimum GWA of 78% (2.0 QPI) with no failing marks. Highly structured and opens annually in September for the subsequent academic year.", "min_age": null, "max_age": null, "application_deadline": "2026-11-15", "application_open_date": "2026-09-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[]", "max_income_threshold": 500000, "min_gwa_normalized": 78.0}}', NULL, '2026-06-30 12:30:48.956865');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (17, 41, 1, '{"action": "create", "snapshot": {"title": "Ateneo Directors List Scholarship", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Director''s List Scholarship is extended by the Ateneo OAA to the next tier of top-ranking ACET examinees (top 51-150 nationwide). It grants an annual flat-rate educational stipend of 100,000 PHP directly credited to the recipient''s tuition or disbursed as cash allowance across semesters. No financial indicators are used for selection. Recipients must preserve a minimum QPI of 2.50 (83% normalized GWA) and avoid any academic or disciplinary probationary states.", "min_age": null, "max_age": null, "application_deadline": "2026-11-15", "application_open_date": "2026-09-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 83.0}}', NULL, '2026-06-30 12:30:50.868160');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (18, 42, 1, '{"action": "create", "snapshot": {"title": "Ateneo Law School Financial Aid Program", "provider": "Ateneo Law School", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo Law School Financial Aid Program provides tuition assistance grants ranging from 25% to 100% for students enrolled in the Juris Doctor (JD) program at the Rockwell campus. Managed by the ALS Scholarship Committee, awards are heavily based on exceptional undergraduate academic honors, high scores in the Philippine Law School Admission test, and certified financial need. Maintenance requires keeping a minimum yearly weighted average of 82 (passing) and fulfilling service hours within the ALS legal aid clinics or administrative units.", "min_age": null, "max_age": null, "application_deadline": "2026-05-30", "application_open_date": "2026-04-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[]", "max_income_threshold": 600000, "min_gwa_normalized": 82.0}}', NULL, '2026-06-30 12:30:51.849930');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (19, 43, 1, '{"action": "create", "snapshot": {"title": "DLSU Star Scholars Program", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The DLSU Star Scholars Program is an elite academic recruitment track that signs the absolute top scorers of the DLSU College Admission Test (DCAT) nationwide. It waives 100% of all tuition, laboratory, and miscellaneous fees for the entire duration of the program, supplies a monthly cash living stipend of 8,000 PHP, a specialized laptop computer allowance upon entry, and guaranteed faculty mentorship for undergraduate research. Academic retention mandates a strict cumulative GWA of 3.0 out of 4.0 (90% normalized) with zero dropped courses.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-01", "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 90.0}}', NULL, '2026-06-30 12:30:52.914542');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (20, 44, 1, '{"action": "create", "snapshot": {"title": "DLSU Archer Achievers Scholarship", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The Archer Achievers Scholarship is automatically extended by DLSU to students who graduate as the absolute valedictorians and salutatorians of top-performing high schools accredited by the university. It automatically confers a 100% tuition waiver for the student''s selected undergraduate curriculum. No separate financial files are required, but students must preserve a high semestral GWA of 2.50 out of 4.0 (83% normalized) to sustain the benefit across academic years.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-01", "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 83.0}}', NULL, '2026-06-30 12:30:54.053405');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (21, 45, 1, '{"action": "create", "snapshot": {"title": "UST San Martin de Porres Equity Scholarship", "provider": "University of Santo Tomas", "source": "gemini_research", "link": "https://manila.ust.edu.ph", "description": "The San Martin de Porres Scholarship is UST''s foundational equity framework designed for financially marginalized students. Split into internal and external funds, it offers partial to full tuition waivers based on audited household documentation. Eligible candidates must have a GWA of 85% or better and a household annual income below 300,000 PHP. Submissions are processed online through the UST OSA web portal at the start of each academic year.", "min_age": null, "max_age": null, "application_deadline": "2026-07-25", "application_open_date": "2026-06-10", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[]", "max_income_threshold": 300000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:30:54.889087');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (22, 46, 1, '{"action": "create", "snapshot": {"title": "Mindanao State University SASE Academic Scholarship", "provider": "Mindanao State University System", "source": "gemini_research", "link": "https://www.msumain.edu.ph", "description": "The Mindanao State University System Academic Scholarship is awarded to incoming undergraduate freshmen who score in the top 5% of the annual MSU System Admission and Scholarship Examination (SASE) across Mindanao. Administered by the MSU Admissions Office, it offers full institutional tuition waivers, free dormitory lodging within the university campus, and a semestral book allowance. Grantees must maintain a GWA of 2.0 (85%) per semester to sustain benefits. This program forms a vital pipeline for students in conflict-affected regions.", "min_age": null, "max_age": null, "application_deadline": "2026-05-15", "application_open_date": "2026-03-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"BARMM\", \"Region IX - Zamboanga Peninsula\", \"Region X - Northern Mindanao\", \"Region XI - Davao\", \"Region XII - Soccsksargen\", \"Region XIII - Caraga\"]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:30:56.003639');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (23, 47, 1, '{"action": "create", "snapshot": {"title": "Muntinlupa MOST Academic Scholarship", "provider": "Muntinlupa Scholarship Division", "source": "gemini_research", "link": "https://www.muntinlupacity.gov.ph", "description": "The Muntinlupa Outstanding Students (MOST) Scholarship is an elite academic grant given to the top 10 highest-ranking graduating Senior High School students from every public and private high school operating in Muntinlupa City. Managed by the Muntinlupa Scholarship Division (MSD), it applies strictly to individuals who secure entry into premier State Universities (such as UP Diliman/Los Banos) or top-tier private institutions. It offers absolute tuition coverage up to 100,000 PHP annually, alongside a high monthly stipend of 5,000 PHP. Academic maintenance is strictly tied to a GWA of 1.50 (90%) with zero failures. Applications require certified high school ranking documents and automated validation.", "min_age": null, "max_age": null, "application_deadline": "2026-06-15", "application_open_date": "2026-05-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Muntinlupa\"]", "max_income_threshold": 500000, "min_gwa_normalized": 90.0}}', NULL, '2026-06-30 12:31:00.974508');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (24, 48, 1, '{"action": "create", "snapshot": {"title": "Muntinlupa CARES Financial Assistance Program", "provider": "Muntinlupa Scholarship Division", "source": "gemini_research", "link": "https://www.muntinlupacity.gov.ph", "description": "The Continuing Assistance for Reintegrating Students (CARES) is a equity-driven financial assistance mechanism for general college residents of Muntinlupa who are enrolled in public SUCs or local community colleges. It requires a baseline GWA of 80% (2.5) with no incomplete or failing grades. It disburses a direct financial support grant of 5,000 PHP per semester to cover transport and digital connectivity needs. Financial status is verified via Barangay Certificate of Indigency or low-income ITR. Registration occurs semestrally via the MSD localized offices.", "min_age": null, "max_age": null, "application_deadline": "2026-07-20", "application_open_date": "2026-06-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Muntinlupa\"]", "max_income_threshold": 200000, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 12:31:03.920771');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (25, 49, 1, '{"action": "create", "snapshot": {"title": "Cebu Province CP GIFTS Program", "provider": "Cebu Provincial Government", "source": "gemini_research", "link": "https://www.cebu.gov.ph", "description": "The Cebu Province Grants Intended for Tertiary Students (CP-GIFTS) is a massive provincial scholarship initiative under the Office of the Governor. It funds 5,900 concurrent slots for poor but deserving students living across the municipalities and component cities of Cebu Province. Applicants must study at designated SUCs, LUCs, or partner private schools within Cebu and maintain a minimum GWA of 85%. Household income must not cross 200,000 PHP annually. It grants a definitive flat sum of 10,000 PHP per semester for school requirements. A mandatory return component requires executing 160 hours of verified community civic service within the student''s home municipality.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-06-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"Region VII - Central Visayas\"]", "eligible_cities": "[]", "max_income_threshold": 200000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:31:06.339297');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (26, 50, 1, '{"action": "create", "snapshot": {"title": "Para\u00f1aque City Tertiary Education Financial Assistance Program", "provider": "Para\u00f1aque City Government", "source": "gemini_research", "link": "https://www.paranaquecity.gov.ph", "description": "The Tertiary Education Financial Assistance Program (TEFAP) is an open-access equity grant run by the Para\u00f1aque LGU for resident college students. To fit varying academic profiles, the cash stipend scales directly with academic performance: students maintaining a GWA of 88% and above receive 6,000 PHP per semester, while those with a GWA between 80% and 87% receive 4,000 PHP per semester. Requirements demand 3 years of residency and a parent''s voter registration record inside Para\u00f1aque. Online registrations are queued via the local city hall portal.", "min_age": null, "max_age": null, "application_deadline": "2026-08-20", "application_open_date": "2026-07-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Para\\u00f1aque\"]", "max_income_threshold": 300000, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 12:31:07.946980');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (27, 51, 1, '{"action": "create", "snapshot": {"title": "Tabuk City College Academic Scholarship", "provider": "Tabuk City Government", "source": "gemini_research", "link": "https://www.tabuk.gov.ph", "description": "Established under Tabuk City Ordinance No. 02 Series of 2018, this program supports tertiary students residing in Tabuk City, Kalinga Province (CAR). It targets low-income households with a maximum annual income cap of 120,000 PHP. Students must maintain a passing GWA of 75% with zero dropped classes to remain qualified. It awards a flat-rate cash assistance grant of 4,000 PHP per semester directly paid to students to handle living costs. Applications are reviewed by the Tabuk City Scholarship Committee at the City Youth and Sports Development Office.", "min_age": null, "max_age": null, "application_deadline": "2026-08-31", "application_open_date": "2026-07-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"CAR\"]", "eligible_cities": "[\"Tabuk\"]", "max_income_threshold": 120000, "min_gwa_normalized": 75.0}}', NULL, '2026-06-30 12:31:12.131160');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (28, 52, 1, '{"action": "create", "snapshot": {"title": "NCIP Educational Assistance Program Degree Track", "provider": "National Commission on Indigenous Peoples", "source": "gemini_research", "link": "https://ncip.gov.ph", "description": "The National Commission on Indigenous Peoples Educational Assistance Program (NCIP-EAP) Degree Track is a mandated sector-specific government program designed under NCIP Administrative Order No. 5 Series of 2012 and upgraded via AO No. 6 Series of 2023. It aims to extend tertiary educational access to recognized members of Indigenous Cultural Communities (ICCs/IPs) nationwide. Eligible candidates must secure a Certificate of Confirmation (COCO) from the NCIP Provincial/Regional Office confirming tribal identity. The academic bar requires a general passing GWA of 75% with zero dropped modules. It supplies an annual educational subsidy of 10,000 PHP to 20,000 PHP disbursed through regional offices to offset books, uniform, and field research. Highly recurring cycle synchronized with the fiscal year.", "min_age": null, "max_age": null, "application_deadline": "2026-08-15", "application_open_date": "2026-06-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 200000, "min_gwa_normalized": 75.0}}', NULL, '2026-06-30 12:31:14.417363');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (29, 53, 1, '{"action": "create", "snapshot": {"title": "NCIP Merit Based Scholarship Program", "provider": "National Commission on Indigenous Peoples", "source": "gemini_research", "link": "https://ncip.gov.ph", "description": "The NCIP Merit-Based Scholarship Program (NCIP-MBS) is a high-tier academic track within the commission reserved for outstanding IP students pursuing competitive national degrees (specifically STEM, Engineering, or Agriculture). Unlike the EAP, the MBS enforces a strict GWA requirement of 85% or higher and puts applicants through a competitive regional examination. It grants an expanded benefit package of 30,000 PHP per year to handle tuition balances or modern learning devices. Administered via the NCIP Bureau of Socio-Economic Literacy and Culture.", "min_age": null, "max_age": null, "application_deadline": "2026-08-15", "application_open_date": "2026-06-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 300000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:31:16.610215');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (30, 54, 1, '{"action": "create", "snapshot": {"title": "DOH Medical Scholarship and Return Service Program", "provider": "Department of Health", "source": "gemini_research", "link": "https://doh.gov.ph", "description": "The DOH Medical Scholarship and Return Service (MSRS) Program is a major sector-specific government intervention operating under the ''Doktor Para sa Bayan'' Act (RA 11509) in partnership with CHED. It funds full medical education (Doctor of Medicine) for qualified Filipino students across certified state and partner private universities. It covers 100% of tuition, laboratory fees, provides a high monthly living allowance of 15,000 PHP, a specialized book/equipment allowance of 20,000 PHP per semester, and basic board exam review subsidies. Eligible applicants must hold a Bachelor''s degree with a solid GWA, pass the medical school entrance and NMAT, and prioritize low-income roots or origin from underserved rural towns. Return service requires serving as a public health officer in a government hospital or rural health unit (RHU) for 1 year for every year of scholarship.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-01", "is_active": false, "data_status": "active", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 600000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:31:17.714353');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (31, 55, 1, '{"action": "create", "snapshot": {"title": "Department of Agriculture ACEF GIAHEP SUC Track", "provider": "Department of Agriculture", "source": "gemini_research", "link": "https://da.gov.ph", "description": "The Agricultural Competitiveness Enhancement Fund Grants-in-Aid for Higher Education Program (ACEF-GIAHEP) SUC Track is a targeted government financial aid tool managed by the Department of Agriculture in compliance with RA 10848. It extends funding to children of registered small farmers, fisherfolk, and agrarian reform beneficiaries who are enrolled in State Universities and Colleges. It covers educational assistance for specific courses in agriculture, agribusiness, agricultural engineering, and fisheries science. Requires a minimum GWA of 75% and presentation of the parent''s RSBSA (Registry System for Basic Sectors in Agriculture) certificate. Disburses a flat rate of 15,000 PHP per semester.", "min_age": null, "max_age": null, "application_deadline": "2026-08-15", "application_open_date": "2026-06-15", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 200000, "min_gwa_normalized": 75.0}}', NULL, '2026-06-30 12:31:19.523969');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (32, 56, 1, '{"action": "create", "snapshot": {"title": "AFPEBSO DND CHED PASUC Scholarship", "provider": "Armed Forces of the Philippines (AFPEBSO)", "source": "gemini_research", "link": "https://afpeebso.org", "description": "The AFPEBSO DND-CHED-PASUC Scholarship is a special sector-specific inter-agency government program managed by the Armed Forces of the Philippines Educational Benefit System Office. It extends 100% tuition and fee exemptions at any public State University or College (SUC) for the legitimate children and direct dependents of active-duty, retired, or deceased AFP military personnel. Academic requirements mandate a baseline GWA of 80% (2.5) with zero failures. Financial constraints are secondary to the parent''s military service record. Portals accept applications annually from May to July.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-05-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 12:31:21.080786');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (33, 57, 1, '{"action": "create", "snapshot": {"title": "DSWD AICS Educational Assistance", "provider": "Department of Social Welfare and Development", "source": "gemini_research", "link": "https://www.dswd.gov.ph", "description": "The DSWD Assistance to Individuals in Crisis Situation (AICS) Educational Assistance is a specialized cash intervention program designed for students experiencing extreme economic shock, sudden death of a breadwinner, abandonment, or loss of livelihood due to national disasters. Operated directly through the DSWD Crisis Intervention Units (CIU) or Social Welfare Operations Hubs, it provides a one-time cash grant ranging from 1,000 PHP (Elementary), 2,000 PHP (High School), 3,000 PHP (Senior High), to 4,000 PHP (College/TVET) per semester. Selection ignores GWA rankings but strictly requires an active Case Study Report or Certificate of Indigency from the local MSWDO.", "min_age": null, "max_age": null, "application_deadline": "2026-12-31", "application_open_date": "2026-01-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"Grade 11\", \"Grade 12\", \"College\", \"TVET\", \"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 150000, "min_gwa_normalized": null}}', NULL, '2026-06-30 12:31:22.881361');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (34, 58, 1, '{"action": "create", "snapshot": {"title": "Security Bank Foundation State Universities Scholarship", "provider": "Security Bank Foundation", "source": "gemini_research", "link": "https://www.securitybank.com", "description": "The Security Bank Foundation ''Scholars for Better Communities'' State Universities Scholarship provides full educational stipends to low-income student leaders enrolled in partner public SUCs (such as UP Diliman, MSU, or regional centers). It provides a high flat allowance of 50,000 PHP per year to cover learning modules, laptops, and transit costs. Applicants must present a GWA of 85% or higher, zero failed subjects, and clear an interview with Security Bank HR personnel. No return service is mandated, but scholars receive priority onboarding for corporate internships.", "min_age": null, "max_age": null, "application_deadline": "2026-06-15", "application_open_date": "2026-04-15", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 350000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:31:23.753842');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (35, 59, 1, '{"action": "create", "snapshot": {"title": "Caritas Manila YSLEP Scholarship Program", "provider": "Caritas Manila", "source": "gemini_research", "link": "https://www.caritasmanila.org.ph", "description": "The Youth Servant Leadership and Education Program (YSLEP) is Caritas Manila''s primary church-backed financial aid and leadership development initiative. Operating across Catholic dioceses nationwide, it supports poor and marginalized college and TVET students. It pays partial tuition up to 25,000 PHP per year and distributes a modest monthly allowance. Distinctively, selection prioritizes urban-slum families, 4Ps members, and indigenous youth. Recipients must join monthly leadership seminars, church volunteer hours, and community organizing programs. Academic criteria require a baseline 80% GWA with zero failures.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-05-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\", \"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 180000, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 12:31:24.655115');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (36, 60, 1, '{"action": "create", "snapshot": {"title": "Taiwan ICDF Higher Education Scholarship Program", "provider": "Taiwan International Cooperation and Development Fund", "source": "gemini_research", "link": "https://www.icdf.org.tw", "description": "The Taiwan ICDF Higher Education Scholarship Program is a full international bilateral grant offered to Filipino citizens for Master''s or Doctoral programs at partner Taiwanese universities. It provides full tuition coverage, modern campus housing, comprehensive health insurance, and a monthly stipend of 18,000 TWD (Master''s) or 20,000 TWD (PhD) (approximately 32,000 to 36,000 PHP). Focus areas are restricted to STEM, tropical agriculture, and electronic engineering. Requires an undergraduate GWA of 85% or better and an interview by the Taipei Economic and Cultural Office (TECO) in Manila.", "min_age": null, "max_age": null, "application_deadline": "2026-03-15", "application_open_date": "2026-01-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:31:33.676910');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (37, 61, 1, '{"action": "create", "snapshot": {"title": "Megaworld Foundation Scholarship Program", "provider": "Megaworld Foundation", "source": "gemini_research", "link": "https://www.megaworldfoundation.com", "description": "The Megaworld Foundation Scholarship Program is a high-impact mid-market corporate financial assistance framework that funds full undergraduate degrees for underprivileged youths across partner universities in Metro Manila and key regions. It covers 100% of actual tuition and institutional fees, and issues a monthly stipend of 2,500 PHP. Eligible candidates must maintain a GWA of 85% (2.0) with zero dropped subjects and possess a total combined annual household income not exceeding 400,000 PHP. Applications are routed through the Megaworld online portal, requiring an essay on community development and an executive interview.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-05-15", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\", \"Region III - Central Luzon\", \"Region IV-A - Calabarzon\", \"Region VI - Western Visayas\", \"Region VII - Central Visayas\"]", "eligible_cities": "[]", "max_income_threshold": 400000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:31:36.930199');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (38, 62, 1, '{"action": "create", "snapshot": {"title": "AFPSLAI Educational Grant Program", "provider": "Armed Forces of the Philippines (AFPSLAI)", "source": "gemini_research", "link": "https://www.afpslai.com.ph", "description": "The AFPSLAI Educational Grant Program (EGP) is an affiliation-based financial assistance platform run by the Armed Forces and Police Savings and Loan Association, Inc. It caters to the children and dependents of active or retired military personnel, PNP officers, and uniformed service members who are registered members of AFPSLAI. It delivers a comprehensive flat financial subsidy of 25,000 PHP per semester (50,000 PHP annually) directly to the student to offset undergraduate expenses. Candidates must post a minimum GWA of 85% and possess a clean disciplinary record. Submissions clear through AFPSLAI regional branch hubs.", "min_age": null, "max_age": null, "application_deadline": "2026-07-10", "application_open_date": "2026-05-15", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 500000, "min_gwa_normalized": 85.0}}', NULL, '2026-06-30 12:31:58.266413');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (39, 63, 1, '{"action": "create", "snapshot": {"title": "Erasmus Mundus Joint Masters Scholarship", "provider": "European Union", "source": "gemini_research", "link": "https://erasmus-plus.ec.europa.eu", "description": "The Erasmus Mundus Joint Masters Scholarship is a highly prestigious international bilateral program funded by the European Union for outstanding Filipino college graduates. It covers 100% of international tuition fees, laboratory charges, global travel costs, visa fees, and delivers a premium monthly living allowance of 1,400 EUR (approximately 88,000 PHP) for the entire 2-year graduate duration. Recipients study in at least three distinct European universities across different EU nations. It requires an elite undergraduate academic record (GWA 90% or equivalent), a comprehensive statement of purpose, academic essays, and dual letters of recommendation. Portals open annually in October.", "min_age": null, "max_age": null, "application_deadline": "2027-01-15", "application_open_date": "2026-10-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 90.0}}', NULL, '2026-06-30 12:32:00.312690');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (40, 64, 1, '{"action": "create", "snapshot": {"title": "Global Korea Scholarship (GKS) Graduate", "provider": "NIIED", "source": "gemini_research", "link": "https://www.studyinkorea.go.kr", "description": "South Korean government scholarship for master''s and doctoral degrees including mandatory one-year Korean language training. Provides round-trip airfare, tuition, living allowance, and health insurance. Embassy Track allows applying to up to three universities; applicants must be under 40.", "min_age": null, "max_age": 40, "application_deadline": "2026-02-25", "application_open_date": "2026-02-12", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:48.456861');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (41, 65, 1, '{"action": "create", "snapshot": {"title": "Global Korea Scholarship (GKS) Undergraduate", "provider": "NIIED", "source": "gemini_research", "link": "https://www.studyinkorea.go.kr", "description": "South Korean government scholarship for undergraduate bachelor''s degrees in Korea. Fully funded including airfare, tuition, living allowance, and health insurance with mandatory Korean language training. Embassy Track application cycle typically opens in September.", "min_age": null, "max_age": null, "application_deadline": "2025-09-30", "application_open_date": "2025-09-15", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:51.707074');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (42, 66, 1, '{"action": "create", "snapshot": {"title": "CHED-UniFAST Tertiary Education Subsidy (TES)", "provider": "UniFAST / CHED", "source": "gemini_research", "link": "https://tes.unifast.gov.ph", "description": "National need-based tertiary education subsidy administered through HEIs via the UniFAST portal. Targets underprivileged and 4Ps/Listahanan students enrolled in CHED-recognized programs. Provides allowance for tuition gaps, books, and living expenses based on prioritization guidelines.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:53.189947');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (43, 67, 1, '{"action": "create", "snapshot": {"title": "TESDA Private Education Student Financial Assistance", "provider": "TESDA", "source": "gemini_research", "link": "https://www.tesda.gov.ph", "description": "TESDA-administered financial assistance for students in private TVET institutions. Rolling applications processed through regional and provincial TESDA offices. Targets underprivileged learners pursuing technical-vocational education and training programs.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:54.619235');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (44, 68, 1, '{"action": "create", "snapshot": {"title": "PUP Entrance Scholarship Program", "provider": "PUP", "source": "gemini_research", "link": "https://www.pup.edu.ph/students/scholarships", "description": "Institutional merit scholarship for exemplary incoming PUP freshmen who qualify through the university entrance examination. Targets high-performing qualifiers with financial need considerations including PWD, IP, and solo parent dependents.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:55.867362');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (45, 69, 1, '{"action": "create", "snapshot": {"title": "PUP Student Assistantship Program", "provider": "PUP", "source": "gemini_research", "link": "https://www.pup.edu.ph/students/scholarships", "description": "Need-based student assistantship managed by the PUP student services office with rolling applications each semester. Provides work-study opportunities on campus to help enrolled students cover educational expenses.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:56.545374');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (46, 70, 1, '{"action": "create", "snapshot": {"title": "UP College of Law Scholarship Program", "provider": "UP College of Law", "source": "gemini_research", "link": "https://law.upd.edu.ph/call-for-scholarship-applications-ay-2025-2026/", "description": "Institutional merit-and-need scholarship for UP College of Law students. Targets underprivileged, PWD, and IP law students with demonstrated financial need and academic standing. Highly recurring annual grant administered by the law college.", "min_age": null, "max_age": null, "application_deadline": "2025-07-20", "application_open_date": "2025-06-30", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:57.236845');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (47, 71, 1, '{"action": "create", "snapshot": {"title": "Security Bank External Scholarship Program", "provider": "Security Bank Foundation", "source": "gemini_research", "link": "https://www.securitybank.com/agency-scholarships-program-dnd/", "description": "Private corporate scholarship for college students in NCR pursuing business, STEM, engineering, and IT fields. Requires minimum 86% GWA. Active program with partner university deadlines including PUP and Ateneo through July 31, 2026.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-05-23", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 86.0}}', NULL, '2026-06-30 13:52:57.855777');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (48, 72, 1, '{"action": "create", "snapshot": {"title": "Gokongwei Brothers Foundation STEM-College Scholarship", "provider": "Gokongwei Brothers Foundation", "source": "gemini_research", "link": "https://philscholar.com/gbf-stem-college-scholarship/", "description": "Annual corporate STEM scholarship for college students in engineering, IT, and related science fields. Covers tuition and provides allowances for scholars demonstrating academic merit and financial need. Annual cycle closed May 31, 2026 for current intake.", "min_age": null, "max_age": null, "application_deadline": "2026-05-31", "application_open_date": "2026-04-07", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:52:58.564013');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (49, 73, 1, '{"action": "create", "snapshot": {"title": "DOST-SEI Undergraduate Scholarships (RA 7687 / Merit)", "provider": "DOST-SEI", "source": "gemini_research", "link": "https://www.science-scholarships.ph/", "description": "Premier national science scholarship for four- or five-year baccalaureate degrees in science and technology. RA 7687 targets underprivileged students; Merit track is open regardless of income. Benefits include tuition up to 40000 PHP per year, 8000 PHP monthly living allowance, and 10000 PHP annual learning materials allowance.", "min_age": null, "max_age": null, "application_deadline": "2025-11-22", "application_open_date": "2025-10-13", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:01.497509');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (50, 74, 1, '{"action": "create", "snapshot": {"title": "Australia Awards Scholarships (Philippines)", "provider": "Australian Government", "source": "gemini_research", "link": "https://www.australiaawardsphilippines.org/scholarships", "description": "Fully funded master''s degrees at Australian universities for Filipino citizens with at least 12 months Philippine residency and two years cumulative work experience. Covers tuition, return air travel, establishment allowance, living expenses, and health insurance. Requires a Re-Entry Action Plan for development work upon return.", "min_age": null, "max_age": null, "application_deadline": "2026-04-30", "application_open_date": "2026-02-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:03.561747');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (51, 75, 1, '{"action": "create", "snapshot": {"title": "Aboitiz Future Leaders Scholarship Program", "provider": "Aboitiz Foundation", "source": "gemini_research", "link": "https://aboitiz.com/aboitiz-foundation/aboitiz-future-leaders-scholarship", "description": "Corporate scholarship for incoming sophomore students enrolled in partner state universities in engineering, data science, communications, and related fields. Covers full tuition, monthly allowance, and academic excellence incentives. Requires cumulative first-year GWA of 2.0 or better on the UP scale with no failing or incomplete grades, plus a mandatory 400-hour internship within Aboitiz Group business units.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-04-28", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 75.0}}', NULL, '2026-06-30 13:53:04.504414');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (52, 76, 1, '{"action": "create", "snapshot": {"title": "Bagong Pilipinas Merit Scholarship Program (BPMSP) - Higher Education Track", "provider": "Commission on Higher Education", "source": "gemini_research", "link": "https://bpms.ched.gov.ph/", "description": "National merit scholarship for incoming college freshmen under the Bagong Pilipinas framework. SUC scholars receive full tuition; private HEI scholars receive up to 45000 PHP annually for tuition and fees plus a 45000 PHP annual stipend. Requires minimum 95% SHS GWA or top-five batch ranking and combined household income up to 2000000 PHP per year.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-04-30", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 2000000, "min_gwa_normalized": 95.0}}', NULL, '2026-06-30 13:53:05.300719');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (53, 77, 1, '{"action": "create", "snapshot": {"title": "Bagong Pilipinas Merit Scholarship Program (BPMSP) - TVET Track", "provider": "Technical Education and Skills Development Authority", "source": "gemini_research", "link": "https://bpms.ched.gov.ph/", "description": "TVET diploma track under the joint CHED-DepEd-TESDA Bagong Pilipinas Merit Scholarship Program. Targets priority diploma programs with minimum 90% GWA and combined household income up to 2000000 PHP. Includes mandatory return-of-service of one year in the Philippines for every year of funding.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-04-30", "is_active": true, "data_status": "active", "eligible_levels": "[\"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 2000000, "min_gwa_normalized": 90.0}}', NULL, '2026-06-30 13:53:06.277562');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (54, 78, 1, '{"action": "create", "snapshot": {"title": "GSIS Subsidy for STEM Program (GSSP)", "provider": "Government Service Insurance System", "source": "gemini_research", "link": "https://www.gsis.gov.ph", "description": "New STEM-focused subsidy for children of active GSIS members and permanent total disability pensioners under 60. Supports CHED-recognized STEM degree programs for college freshmen with minimum 90% SHS GWA. Provides 15000 PHP annual subsidy per scholar, prioritizing parents in Salary Grade 15 and below.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": "2026-06-30", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 90.0}}', NULL, '2026-06-30 13:53:07.118988');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (56, 80, 1, '{"action": "create", "snapshot": {"title": "MEXT Scholarship - Research Category", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for Filipino college graduates pursuing master''s or doctoral degrees in Japan. Requires a feasible research proposal in humanities, social sciences, or natural sciences. Provides tuition, monthly stipend, regional allowance, and roundtrip airfare. Applicants must be under 35 years old.", "min_age": null, "max_age": 35, "application_deadline": "2026-05-29", "application_open_date": "2026-04-22", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:12.075658');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (57, 81, 1, '{"action": "create", "snapshot": {"title": "MEXT Scholarship - Undergraduate Track", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for high school graduates pursuing undergraduate degrees in Japan. Open to applicants under 25 with strong academic records. Covers tuition, monthly stipend, and roundtrip travel for full degree study in Japan.", "min_age": null, "max_age": 25, "application_deadline": "2026-05-29", "application_open_date": "2026-04-22", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:13.585723');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (58, 82, 1, '{"action": "create", "snapshot": {"title": "MEXT Scholarship - Specialized Training Track", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for vocational and specialized training programs in Japan. Targets high school graduates under 25 seeking technical skills development. Provides tuition, stipend, and travel support for designated training courses.", "min_age": null, "max_age": 25, "application_deadline": "2026-05-29", "application_open_date": "2026-04-22", "is_active": false, "data_status": "expired", "eligible_levels": "[\"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:14.680271');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (59, 83, 1, '{"action": "create", "snapshot": {"title": "MEXT Scholarship - College of Technology (KOSEN)", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for the College of Technology (KOSEN) five-year engineering program in Japan. Combines college and TVET-level technical training for high school graduates under 25. Covers tuition, stipend, and roundtrip airfare.", "min_age": null, "max_age": 25, "application_deadline": "2026-05-29", "application_open_date": "2026-04-22", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\", \"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:15.326982');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (60, 84, 1, '{"action": "create", "snapshot": {"title": "GSIS Educational Subsidy Program (GESP)", "provider": "Government Service Insurance System", "source": "gemini_research", "link": "https://www.gsis.gov.ph", "description": "Flat-rate educational grant of 10000 PHP for dependents of active GSIS members and permanent total disability pensioners. Open to all college courses without STEM restriction. Historically offered as a broad welfare benefit before the launch of the STEM-specific GSSP.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:15.956140');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (61, 85, 1, '{"action": "create", "snapshot": {"title": "OWWA Education for Development Scholarship (EDSP)", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://scholarship.owwa.gov.ph/", "description": "Competitive scholarship for high-performing dependents of active OWWA members. Freshmen must be single, under 21, with SHS GWA of at least 80% and must pass the DOST-SEI qualifying exam. Provides up to 60000 PHP per school year for any four- or five-year baccalaureate course.", "min_age": null, "max_age": 21, "application_deadline": "2025-11-28", "application_open_date": "2025-11-10", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 13:53:16.542823');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (62, 86, 1, '{"action": "create", "snapshot": {"title": "OWWA OFW Dependent Scholarship Program (ODSP)", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://scholarship.owwa.gov.ph/", "description": "Need-based scholarship for dependents of active OWWA members whose monthly salary does not exceed USD 600. Provides 20000 PHP per school year for baccalaureate or associate courses. Requires minimum 80% GWA for continuing eligibility.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 13:53:17.749955');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (63, 87, 1, '{"action": "create", "snapshot": {"title": "OWWA Congressional Migrant Workers Scholarship (CMWSP)", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://scholarship.owwa.gov.ph/", "description": "Congressional-funded scholarship for active OWWA members or dependents with combined household income of USD 2400 or less per year. Restricted to prioritized science and technology courses. Provides up to 60000 PHP per academic year with minimum 80% GWA requirement.", "min_age": null, "max_age": null, "application_deadline": "2025-11-28", "application_open_date": "2025-11-10", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 80.0}}', NULL, '2026-06-30 13:53:18.636193');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (64, 88, 1, '{"action": "create", "snapshot": {"title": "Quezon City Scholarship Program (QCSP)", "provider": "Quezon City Government", "source": "gemini_research", "link": "https://qceservices.quezoncity.gov.ph", "description": "City-wide LGU scholarship covering senior high school, vocational, college, and postgraduate students who are Quezon City residents with verified QCitizen ID. Directs 70% of tertiary slots to low-income and marginalized sectors. Supported 9377 active scholars in the most recent cycle.", "min_age": null, "max_age": null, "application_deadline": "2026-06-05", "application_open_date": "2026-05-25", "is_active": false, "data_status": "expired", "eligible_levels": "[\"High School\", \"College\", \"TVET\", \"Graduate\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Quezon City\"]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:19.692240');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (65, 89, 1, '{"action": "create", "snapshot": {"title": "Manuel L. Quezon Filipino Language and Literature Scholarship Program", "provider": "Quezon City Government", "source": "gemini_research", "link": "https://qceservices.quezoncity.gov.ph", "description": "Specialized Quezon City LGU humanities scholarship for college students, researchers, and educators pursuing Filipino language and literature. Requires QC residency and QCitizen verification. Counterpart to STEM-focused national programs, preserving cultural capital.", "min_age": null, "max_age": null, "application_deadline": "2026-06-05", "application_open_date": "2026-05-25", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\", \"Graduate\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Quezon City\"]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:21.861330');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (66, 90, 1, '{"action": "create", "snapshot": {"title": "Fulbright-PhilSA Graduate Program", "provider": "PAEF / PhilSA", "source": "gemini_research", "link": "https://apply.iie.org/ffsp2027", "description": "Bi-national Fulbright-Philippine Space Agency program financing master''s and doctoral degrees in the United States in space science and technology applications. Fully funded including tuition, travel, maintenance, and health insurance. Requires relevant college degree, two years post-college work experience, and return-to-Philippines service obligation.", "min_age": null, "max_age": null, "application_deadline": "2026-06-19", "application_open_date": null, "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:23.871313');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (67, 91, 1, '{"action": "create", "snapshot": {"title": "Chevening Scholarship", "provider": "FCDO / UK Government", "source": "gemini_research", "link": "https://www.chevening.org/apply", "description": "UK Government fully funded one-year master''s program in the United Kingdom. Highly competitive global selection based on leadership, networking, career plan, and study proposal. Requires at least 2800 hours of post-graduation work experience and two-year return commitment to the Philippines after completion.", "min_age": null, "max_age": null, "application_deadline": "2026-10-07", "application_open_date": "2026-08-05", "is_active": true, "data_status": "active", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-06-30 13:53:24.862931');
