INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (74, 1, 2, '{"link": {"from": "https://ched.gov.ph/merit-scholarship", "to": "https://legacy.ched.gov.ph/merit-scholarship/"}, "link_status": {"from": "broken", "to": "ok"}, "data_status": {"from": "broken_link", "to": "verified"}, "min_gwa_normalized": {"from": 90.0, "to": 93.0}, "max_income_threshold": {"from": 400000, "to": 500000}, "benefit_total_value": {"from": 80000, "to": 120000}, "benefit_allowance_monthly": {"from": 3000, "to": null}, "has_qualifying_exam": {"from": true, "to": false}, "application_deadline": {"from": "2026-06-30", "to": "2025-06-20"}}', NULL, '2026-07-26 09:40:17.202047');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (75, 5, 1, '{"title": {"from": "CHED-Tulong Dulong Program", "to": "Tulong Dunong Program (TDP)"}, "provider": {"from": "Commission on Higher Education", "to": "Unified Student Financial Assistance System (UniFAST)"}, "link": {"from": "https://ched.gov.ph", "to": "https://unifast.gov.ph/tes.html"}, "link_status": {"from": "broken", "to": "ok"}, "description": {"from": "Financial assistance for students from low-income families.", "to": "Subsidy under TES for first undergraduate degree; PhP7,500 per regular semester; income ceiling PhP400,000; cannot hold other national StuFAPs including TES and CHED CSPs."}, "benefit_total_value": {"from": 60000, "to": 15000}, "benefit_allowance_monthly": {"from": 2500, "to": null}}', NULL, '2026-07-26 09:40:17.202047');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (78, 76, 3, '{"link_status": {"from": "broken", "to": "ok"}, "data_status": {"from": "broken_link", "to": "verified"}}', NULL, '2026-07-26 09:40:17.202047');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (80, 3, 1, '{"title": {"from": "DOST-SEI Graduate Scholarship", "to": "DOST-SEI Graduate Scholarship Programs (ASTHRDP/CBPSME/ERDT/STRAND)"}, "description": {"from": "Graduate scholarship for master''s and doctoral programs in STEM.", "to": "Umbrella entry conflates ASTHRDP MS/PhD CBPSME ERDT STRAND and other graduate programs each with separate portals deadlines and consortium universities."}, "editorial_state": {"from": "published", "to": "needs_review"}, "cycle_type": {"from": "semester", "to": "semester/term (varies by university)"}}', NULL, '2026-07-26 09:40:21.853416');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (81, 11, 1, '{"title": {"from": "Ayala Foundation Scholarship Program", "to": "Ayala Foundation U-Go Scholar Grant"}, "link": {"from": "https://ayalafoundation.org/scholarships", "to": "https://www.ayalafoundation.org/program/u-go-scholar-grant/"}, "description": {"from": "Scholarship for students with leadership potential and financial need.", "to": "ISKONNECT id 11 ''Ayala Foundation Scholarship Program'' is a generic parent record. Official Ayala Foundation page documents U-Go as a distinct program implemented by Ayala Foundation for young women in public universities\u2014not a general merit scholarship. Update id 11 to U-Go Scholar Grant specifics OR add U-Go as separate record after human review. U-Go has distinct eligibility (female, public HEI, need-based) vs generic Ayala scholarship."}}', NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (82, 13, 1, '{"title": {"from": "Metrobank Foundation Scholarship", "to": "Metrobank Foundation ACCESS Program"}, "link": {"from": "https://metrobank-foundation.org/scholarship", "to": "https://www.mbfoundation.org.ph/grants/grants-education/about-the-metrogold-scholarship-program-msp/"}, "description": {"from": "Scholarship for deserving students with excellent academic records.", "to": "ISKONNECT id 13 ''Metrobank Foundation Scholarship'' is generic. Official Metrobank Foundation site references MetroGold/MSP and education grants; ACCESS (Assistance for the Completion of College Education for Superior Students) is the flagship undergraduate program cited in research with distinct exam requirement and 50 slots annually. Rename and enrich id 13 to ACCESS Program with official primary_link to Metrobank Foundation education grants page. Do not add duplicate unless MSP and ACCESS are confirmed as separate active programs."}}', NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (83, 14, 1, '{"title": {"from": "BPI Foundation Scholarship", "to": "BPI Foundation Pagpupugay Scholarship"}, "link": {"from": "https://bpifoundation.org", "to": "https://www.bpifoundation.org/programs/special-projects/pagpupugay-scholarship"}, "description": {"from": "College scholarship for academically gifted students.", "to": "ISKONNECT id 14 ''BPI Foundation Scholarship'' is generic. Pagpupugay is a specialized COVID-19 frontliner next-of-kin program (RA-adjacent special project), not the foundation''s general scholarship. Official bpifoundation.org documents distinct eligibility (medical frontliner kin, 85% GWA, partner HEI application). Either split Pagpupugay as separate record OR replace id 14 content if generic BPI scholarship does not exist as standalone program. Pagpupugay AY 2022-2023 deadline on page is stale\u2014verify current cycle before import."}}', NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (84, 16, 1, '{"title": {"from": "PLDT-Smart Foundation Scholarship", "to": "PLDT-Smart Foundation Gabay Guro Scholarship"}, "link": {"from": "https://pldtsmartfoundation.org", "to": "https://www.gabayguro.com/about-us"}, "description": {"from": "Scholarship for IT and tech-related degree programs.", "to": "ISKONNECT id 16 ''PLDT-Smart Foundation Scholarship'' is generic. Gabay Guro is the official education arm with teacher-training scholarships at 35+ partner HEIs for BEED/BSED majors\u2014distinct program with return-service teaching obligation per research. Update id 16 to Gabay Guro Program with education-specific metadata, partner HEI constraints, and teaching return-service. Do not add duplicate unless a separate non-Gabay PLDT scholarship is confirmed active."}}', NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (85, 54, 2, '{"title": {"from": "DOH Medical Scholarship and Return Service Program", "to": "CHED Medical Scholarship and Return Service (MSRS)"}, "provider": {"from": "Department of Health", "to": "Commission on Higher Education"}, "link": {"from": "https://doh.gov.ph", "to": "https://legacy.ched.gov.ph/msrs/"}, "is_active": {"from": false, "to": true}, "editorial_state": {"from": "archived", "to": "verified"}, "data_status": {"from": "expired", "to": "verified"}, "link_status": {"from": null, "to": "ok"}}', NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (86, 75, 2, '{"title": {"from": "Aboitiz Future Leaders Scholarship Program", "to": "Aboitiz Brights (Aboitiz Future Leaders Scholarship)"}, "link": {"from": "https://aboitiz.com/aboitiz-foundation/aboitiz-future-leaders-scholarship", "to": "https://www.aboitizfoundation.org/what-we-do/education/aboitiz-future-leaders-scholarship-program/"}, "description": {"from": "Corporate scholarship for incoming sophomore students enrolled in partner state universities in engineering, data science, communications, and related fields. Covers full tuition, monthly allowance, and academic excellence incentives. Requires cumulative first-year GWA of 2.0 or better on the UP scale with no failing or incomplete grades, plus a mandatory 400-hour internship within Aboitiz Group business units.", "to": "ISKONNECT id 75 is titled ''Aboitiz Future Leaders Scholarship Program'' which appears to be the current official brand for Aboitiz Foundation college scholarships. The PDF''s ''Aboitiz Brights'' name could not be independently confirmed on aboitizfoundation.org (503 during verification). The foundation site historically uses Future Leaders branding for incoming sophomore support at partner universities. Do not create duplicate. Review id 75 metadata against latest Aboitiz Foundation education page when site is accessible. If ''Brights'' is confirmed as a distinct sub-program, split then; otherwise treat as naming variant."}}', NULL, '2026-07-26 09:40:24.840505');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (87, 92, 1, '{"action": "create", "snapshot": {"title": "Pasig City Sports Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "The Pasig City Sports Scholarship caters to outstanding student-athletes who have represented Pasig City or their schools in regional, national, or international athletic competitions. It aims to support athletes in balancing academic progression with rigorous athletic training. Eligibility includes verified residency in Pasig City for 3 years, a minimum GWA of 80% to ensure academic compliance, and official endorsements from the Pasig Sports Development Office. Financial aid covers partial tuition and a monthly training stipend. Renewal requires active sports participation and maintaining passing marks. Portal registrations open annually in August.", "min_age": null, "max_age": null, "application_deadline": "2026-09-10", "application_open_date": "2026-08-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\", \"Grade 11\", \"Grade 12\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Pasig\"]", "max_income_threshold": 350000, "min_gwa_normalized": 80.0}}', NULL, '2026-07-26 09:42:24.798908');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (88, 93, 1, '{"action": "create", "snapshot": {"title": "Pasig City Out-of-School Learners Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "Designed specifically for out-of-school youths (OSYs) and adult learners in Pasig City who want to reintegrate into formal education, alternative learning systems (ALS), or technical-vocational (TVET) paths. Funded fully by the LGU, this program waives instructional fees and provides a substantial monthly allowance to cover daily transport and meal costs. Eligibility includes a minimum of 1 year of non-enrollment in school and a family income below 200,000 PHP. Applications are accepted directly through the Pasig Scholarship Office or Barangay halls.", "min_age": null, "max_age": null, "application_deadline": "2026-07-30", "application_open_date": "2026-06-15", "is_active": true, "data_status": "active", "eligible_levels": "[\"TVET\", \"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Pasig\"]", "max_income_threshold": 200000, "min_gwa_normalized": 75.0}}', NULL, '2026-07-26 09:42:25.956110');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (89, 94, 1, '{"action": "create", "snapshot": {"title": "Pasig City Sangguniang Kabataan Endorsed Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "A localized financial-aid track administered in collaboration with the Barangay Sangguniang Kabataan (SK) councils of Pasig City. This scholarship targets active community youth volunteers and leaders. Eligible applicants must possess a formal endorsement from their respective Barangay SK Chairman certifying leadership and civic engagement hours. A minimum GWA of 82% is required. Benefits comprise an annual educational subsidy disbursed in two semester installments.", "min_age": null, "max_age": null, "application_deadline": "2026-08-20", "application_open_date": "2026-07-10", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Pasig\"]", "max_income_threshold": 250000, "min_gwa_normalized": 82.0}}', NULL, '2026-07-26 09:42:27.027880');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (90, 95, 1, '{"action": "create", "snapshot": {"title": "Taguig LANI Full Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The LANI Full Scholarship track supports Taguig residents enrolled in private higher education institutions within or outside Metro Manila. It is designed to alleviate tuition burdens for middle-income families. Requires a minimum GWA of 85% (2.0 or better) and 3 years of verifiable city residency. Provides a flat cash assistance rate of 20,000 PHP to 25,000 PHP per semester. Renewal is contingent upon submitting semestral grade sheets confirming no failing marks. Online application processing is strictly required through the LANI desk.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-06-20", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Taguig\"]", "max_income_threshold": 450000, "min_gwa_normalized": 85.0}}', NULL, '2026-07-26 09:42:28.113935');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (91, 96, 1, '{"action": "create", "snapshot": {"title": "Taguig LANI Basic Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The LANI Basic Scholarship is a broad-access financial assistance grant for Taguig residents enrolled in non-priority programs across public or private institutions. It operates under a lower academic barrier, requiring only a passing GWA of 78% (3.0 or equivalent). It guarantees basic equity support, providing 10,000 PHP per semester to handle textbooks, uniform fees, and transportation costs. Verification of local voter registration is strictly checked during the mandatory manual verification phase.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-06-20", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Taguig\"]", "max_income_threshold": 300000, "min_gwa_normalized": 78.0}}', NULL, '2026-07-26 09:42:29.173441');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (92, 97, 1, '{"action": "create", "snapshot": {"title": "Taguig LANI LEAD Graduate Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The Leadership and Educators Advancement and Development (LEAD) program is an advanced LANI track designed for licensed teachers, city employees, and professionals residing in Taguig who are pursuing Master''s or Doctorate degrees. It funds advanced research, dissertation expenses, and postgraduate tuition up to 40,000 PHP per semester. Applicants must maintain a postgrad GWA of 2.0 (85%) and submit an approved thesis proposal. Return service involves a mandatory 1-year community or institutional service within Taguig for every year of funding.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-15", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Taguig\"]", "max_income_threshold": 750000, "min_gwa_normalized": 85.0}}', NULL, '2026-07-26 09:42:30.236617');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (93, 98, 1, '{"action": "create", "snapshot": {"title": "Makati City Premier and Specialized School Scholarship", "provider": "Makati City Government", "source": "gemini_research", "link": "https://www.makati.gov.ph", "description": "The Makati City Government Scholarship Program offers elite financial backing to top-tier Makati residents who secure admission into designated Centers of Excellence or top private universities (such as DLSU, ADMU, UST, Mapua). Applicants must provide proof of at least 5 years of continuous city residency, valid Makati LGU ID/QCitizen equivalent, and rank in the top 10% of their graduating Senior High School class. It supplies up to 80,000 PHP annually for tuition and institutional fees. Recipients must sign a contract committing to a mandatory 2-year return service within the Makati LGU or city public school system upon graduation. GWA maintenance of 88% (1.75) is strictly audited per semester.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-06-01", "is_active": true, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Makati\"]", "max_income_threshold": 500000, "min_gwa_normalized": 88.0}}', NULL, '2026-07-26 09:42:31.317001');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (94, 99, 1, '{"action": "create", "snapshot": {"title": "University of Makati Special Institutional Scholarship", "provider": "University of Makati (UMak)", "source": "gemini_research", "link": "https://www.umak.edu.ph", "description": "UMak''s Special Institutional Scholarship provides targeted need-and-affiliation assistance for unique sectors inside the university community, including registered PWD students, certified children of active Makati LGU employees, barangay officials, and student-artists in the UMak cultural troupe. It provides complete fee exemptions and a monthly book allowance of 1,000 PHP. Candidates must hold a GWA of 75% (passing) with no dropped or incomplete modules. Formal verification requires presenting civil service certificates or PWD IDs.", "min_age": null, "max_age": null, "application_deadline": "2026-06-25", "application_open_date": "2026-05-10", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\", \"TVET\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Makati\"]", "max_income_threshold": 350000, "min_gwa_normalized": 75.0}}', NULL, '2026-07-26 09:42:32.380731');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (95, 100, 1, '{"action": "create", "snapshot": {"title": "NavotaAs Fisherfolk Children Scholarship Track", "provider": "Navotas City Government", "source": "gemini_research", "link": "https://www.navotas.gov.ph", "description": "A sector-specific LGU track designed to extend educational equity to the children of registered municipal fisherfolk in Navotas City. Administered under the NavotaAs framework, applicants must submit a certified copy of their parent''s Navotas Fisherfolk Registration ID or validation from the City Agriculture Office. Academic performance requires a standard passing GWA of 78%. It funds full college or TVET technical training at local institutes, along with a monthly sea-fare/allowance of 1,500 PHP. Highly recurring and designed to break generation poverty in maritime-coastal zones.", "min_age": null, "max_age": null, "application_deadline": "2026-07-10", "application_open_date": "2026-06-01", "is_active": true, "data_status": "expired", "eligible_levels": "[\"College\", \"TVET\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[\"Navotas\"]", "max_income_threshold": 180000, "min_gwa_normalized": 78.0}}', NULL, '2026-07-26 09:42:33.444420');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (96, 101, 1, '{"action": "create", "snapshot": {"title": "Davao City STEP FA Category A", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "The Scholarship on Tertiary Education Program (STEP) Category A is the premier academic merit award administered by the Educational Benefit System Unit (EBSU) of Davao City. It targets high-achieving residents who attained an elite GWA of 93% or higher upon graduating Senior High School. It supplies a robust funding package of 25,000 PHP per semester to completely offset academic fees or serve as general living stipends. Financial standing is reviewed via the City Social Welfare and Development Office (CSWDO) indigency screening. Highly stable and recurring annually.", "min_age": null, "max_age": null, "application_deadline": "2026-06-15", "application_open_date": "2026-05-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"Region XI - Davao\"]", "eligible_cities": "[\"Davao City\"]", "max_income_threshold": 250000, "min_gwa_normalized": 93.0}}', NULL, '2026-07-26 09:42:34.497893');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (97, 102, 1, '{"action": "create", "snapshot": {"title": "Davao City STEP FA Category C", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "STEP Category C is a broad-access financial assistance tier by Davao City EBSU focused purely on educational access for lower-income groups. It operates under a standard academic barrier of a 80% passing GWA. It delivers a support fund of 7,500 PHP per semester (15,000 PHP annually) designed to buffer costs for students attending free public SUCs or local institutes. Application processing is synchronized with the main EBSU online schedule.", "min_age": null, "max_age": null, "application_deadline": "2026-06-15", "application_open_date": "2026-05-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"Region XI - Davao\"]", "eligible_cities": "[\"Davao City\"]", "max_income_threshold": 180000, "min_gwa_normalized": 80.0}}', NULL, '2026-07-26 09:42:35.562430');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (98, 103, 1, '{"action": "create", "snapshot": {"title": "Davao City Medical and Law Education Assistance Program", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "This postgraduate track funded by the Davao City Government supports resident college graduates pursuing higher professional degrees in Doctor of Medicine (MD) or Juris Doctor (JD) within institutions located in Davao City (such as DMSF, Ateneo de Davao Law). It supplies substantial funding up to 50,000 PHP per semester to directly offset high professional tuition costs. Applicants must pass a screening panel, present an NMAT or Law School Admission test result, and possess a solid undergraduate GWA of 85%. Requires a corresponding 1-year return service within Davao City offices or city public health units for each year of grant support.", "min_age": null, "max_age": null, "application_deadline": "2026-05-30", "application_open_date": "2026-04-15", "is_active": false, "data_status": "expired", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[\"Region XI - Davao\"]", "eligible_cities": "[\"Davao City\"]", "max_income_threshold": 500000, "min_gwa_normalized": 85.0}}', NULL, '2026-07-26 09:42:36.611281');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (99, 104, 1, '{"action": "create", "snapshot": {"title": "Ateneo Freshman Merit Scholarship", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo Freshman Merit Scholarship is awarded annually to the top 50 absolute highest-performing applicants who excel in the Ateneo College Entrance Test (ACET) nationwide. Selected automatically by the OAA without requiring a separate application form, this elite award grants 100% full tuition exemption, waives all institutional miscellaneous fees, and grants a flat book allowance of 10,000 PHP per year. Academic retention is strictly audited, requiring a minimum QPI of 3.0 (90% normalized GWA) and active leadership participation within approved campus organizations.", "min_age": null, "max_age": null, "application_deadline": "2026-11-15", "application_open_date": "2026-09-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 90.0}}', NULL, '2026-07-26 09:42:37.662316');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (100, 105, 1, '{"action": "create", "snapshot": {"title": "Ateneo Magis Scholarship", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo Magis Scholarship is a specialized institutional track specifically reserved for high-achieving graduates of public high schools nationwide who showcase outstanding leadership profiles and financial need. It provides 100% tuition and fee coverage, an allocated monthly living stipend of 4,000 PHP, full book allowances, and on-campus dormitory accommodation at the Cervini or Eliazo Halls if the student is from the provinces. Application requires public school principal endorsement, ACET certification, and thorough interview evaluations.", "min_age": null, "max_age": null, "application_deadline": "2026-11-15", "application_open_date": "2026-09-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 250000, "min_gwa_normalized": 85.0}}', NULL, '2026-07-26 09:42:38.666564');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (101, 106, 1, '{"action": "create", "snapshot": {"title": "DLSU St La Salle Financial Assistance Grant", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The St. La Salle Financial Assistance Grant is De La Salle University''s primary need-based equity tool for undergraduate college students. Administered by the Oasis-Scholarships and Financial Assistance Hub (OASFAH), it provides full or partial tuition and fee waivers. Eligible applicants must prove a combined annual family income below 700,000 PHP and submit standard academic records showing a GWA of 85% or above with no failures. It includes a monthly allowance of 3,500 PHP for absolute 100% grantees. Portals open semestrally for current students and annually for incoming freshmen.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-06-01", "is_active": true, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 700000, "min_gwa_normalized": 85.0}}', NULL, '2026-07-26 09:42:39.732382');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (102, 107, 1, '{"action": "create", "snapshot": {"title": "DLSU Vaugirard Scholarship Program", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The Vaugirard Scholarship Program is exclusively targeted at exceptional graduates of Philippine public high schools who emerged as the top academic scorers in the DCAT. It completely bridges equity and excellence by presenting 100% free tuition and institutional fee waivers, a monthly allowance of 4,000 PHP, and specialized academic counseling. Eligible applicants must be formally certified by their public high school principals and pass the OASFAH panel verification.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-01", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 300000, "min_gwa_normalized": 88.0}}', NULL, '2026-07-26 09:42:40.793216');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (103, 108, 1, '{"action": "create", "snapshot": {"title": "UST San Lorenzo Ruiz Student Assistance Scholarship", "provider": "University of Santo Tomas", "source": "gemini_research", "link": "https://manila.ust.edu.ph", "description": "The San Lorenzo Ruiz Student Assistance Scholarship is the University of Santo Tomas'' premier internal working scholarship program managed by the Office for Student Affairs (OSA). It caters to regular UST college students who possess financial need and are willing to render 20 to 30 hours of service per week within university offices, laboratories, or libraries. It presents a 100% full waiver of tuition and miscellaneous fees, plus a basic hourly stipend. Applicants must maintain a minimum GWA of 82% (2.25) with zero failures. Highly structured and recurring every semester.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-15", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[]", "max_income_threshold": 250000, "min_gwa_normalized": 82.0}}', NULL, '2026-07-26 09:42:41.851770');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (104, 109, 1, '{"action": "create", "snapshot": {"title": "UST Santo Tomas Academic Scholarship", "provider": "University of Santo Tomas", "source": "gemini_research", "link": "https://manila.ust.edu.ph", "description": "The Santo Tomas Academic Scholarship is awarded to incoming freshmen who graduated as Valedictorians (100% tuition coverage) or Salutatorians (50% tuition coverage) of their high school classes. Validated through the UST OSA, recipients must pass the UST Entrance Test (USTET) and secure regular status enrollment. Retention mandates keeping a clean disciplinary record and a high semestral GWA of 1.75 or better (88% normalized). No financial background checks are applied.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-05-15", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\"]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 88.0}}', NULL, '2026-07-26 09:42:42.898782');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (106, 111, 1, '{"action": "create", "snapshot": {"title": "Security Bank Foundation Agency Personnel Scholarship", "provider": "Security Bank Foundation", "source": "gemini_research", "link": "https://www.securitybank.com", "description": "This unique corporate affiliation-based scholarship track is exclusively reserved for the legitimate children and dependents of Security Bank''s third-party agency personnel (including dedicated security guards, janitorial workers, and building maintenance staff). It extends a direct annual educational allowance of 30,000 PHP for undergraduate studies to ease school costs for working-class contractor families. Requires a minimum passing GWA of 80% and validation of the parent''s active employment contract with the bank''s agency partner.", "min_age": null, "max_age": null, "application_deadline": "2026-06-15", "application_open_date": "2026-04-15", "is_active": false, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 250000, "min_gwa_normalized": 80.0}}', NULL, '2026-07-26 09:42:44.927812');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (107, 112, 1, '{"action": "create", "snapshot": {"title": "TESDA Training for Work Scholarship Program", "provider": "Technical Education and Skills Development Authority", "source": "gemini_research", "link": "https://tesda.gov.ph", "description": "The TESDA Training for Work Scholarship Program (TWSP) is a major sector-specific national TVET pipeline designed to fulfill critical skills requirements in high-growth industries such as IT-BPO, electronics, tourism, and metal engineering. Fully funded by the national government, it covers 100% of the training and instructional fees for short-term tech-voc modules (ranging from 1 to 6 months). Additionally, it distributes a daily training allowance of 160 PHP and provides full coverage for the National Assessment fee. Open to all Filipinos aged 18 and above with a high school diploma. Applications are processed directly through TESDA Regional Offices or accredited tech-voc institutions.", "min_age": 18, "max_age": null, "application_deadline": "2026-12-31", "application_open_date": "2026-01-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 75.0}}', NULL, '2026-07-26 09:42:45.966213');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (108, 113, 1, '{"action": "create", "snapshot": {"title": "TESDA Special Training for Employment Program", "provider": "Technical Education and Skills Development Authority", "source": "gemini_research", "link": "https://tesda.gov.ph", "description": "The Special Training for Employment Program (STEP) is a community-focused TESDA scholarship path targeted at grass-roots livelihood creation and entrepreneurial development. It offers free technical training in community-based skills (e.g., electrical repair, baking, welding, masonry). Critically, it delivers an allocated daily allowance of 160 PHP, a clothing allowance of 500 PHP, and provides a comprehensive high-value Entrepreneurship Tool Kit (e.g., actual baking or welding kits) upon module completion to assist immediate employment. No GWA restrictions are applied.", "min_age": 15, "max_age": null, "application_deadline": "2026-12-31", "application_open_date": "2026-01-01", "is_active": true, "data_status": "active", "eligible_levels": "[\"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 75.0}}', NULL, '2026-07-26 09:42:46.947347');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (112, 117, 1, '{"action": "create", "snapshot": {"title": "Scholarship Program for Coconut Farmers and their Families (CoScho)", "provider": "Commission on Higher Education (CHED)", "source": "discovery_verification", "link": "https://legacy.ched.gov.ph/coscho/", "description": "Scholarship for registered coconut farmers in NCFRS or their dependents pursuing agriculture-related undergraduate degrees. Does not cover tuition at SUCs (FHE-aligned); provides cost-of-living stipend and allowances.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 300000, "min_gwa_normalized": 80.0}}', NULL, '2026-07-26 09:42:51.166137');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (113, 118, 1, '{"action": "create", "snapshot": {"title": "Scholarship Grant Program for Children and Dependents of Sugarcane Industry Workers and Small Sugarcane Farmers (SIDA-SGP)", "provider": "Commission on Higher Education (CHED)", "source": "discovery_verification", "link": "https://legacy.ched.gov.ph/sida-sgp/", "description": "Scholarship for children and dependents of sugarcane industry workers and small sugarcane farmers certified by SRA, covering undergraduate and graduate programs in sugar technology, chemical engineering, agricultural mechanics, and related fields.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\", \"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 400000, "min_gwa_normalized": null}}', NULL, '2026-07-26 09:42:52.082316');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (114, 119, 1, '{"action": "create", "snapshot": {"title": "CHED Scholarship Program for Future Statisticians (Estatistikolar)", "provider": "Commission on Higher Education (CHED)", "source": "discovery_verification", "link": "https://legacy.ched.gov.ph/estatistikolar/", "description": "Scholarship for students enrolled in BS Statistics, BS Applied Statistics, and PSA-identified programs at CHED-recognized HEIs to develop national statistics and data science capacity.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 500000, "min_gwa_normalized": 80.0}}', NULL, '2026-07-26 09:42:52.935217');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (115, 120, 1, '{"action": "create", "snapshot": {"title": "Scholarships for Instructors'' Knowledge Advancement Program (SIKAP)", "provider": "Commission on Higher Education (CHED)", "source": "discovery_verification", "link": "https://sikap.ched.gov.ph/", "description": "Graduate scholarship for full-time teaching and non-teaching personnel of CHED-recognized HEIs and MOU partner agencies to pursue Master''s or Doctorate at CHED-identified DHEIs. SIKAP-N pathway for non-regular personnel.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"Graduate\", \"Faculty\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-07-26 09:42:53.859948');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (116, 121, 1, '{"action": "create", "snapshot": {"title": "DOST-SEI Junior Level Science Scholarship \u2014 Merit Track", "provider": "Department of Science and Technology - Science Education Institute (DOST-SEI)", "source": "discovery_verification", "link": "https://jlss.science-scholarships.ph/", "description": "Merit track of JLSS for regular second-year college students in DOST-SEI priority S&T courses with high aptitude in science and mathematics. No income ceiling. Exam fee PHP 200 unless waived.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 83.0}}', NULL, '2026-07-26 09:42:54.647299');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (117, 122, 1, '{"action": "create", "snapshot": {"title": "DOST-SEI Junior Level Science Scholarship \u2014 RA 7687 Track", "provider": "Department of Science and Technology - Science Education Institute (DOST-SEI)", "source": "discovery_verification", "link": "https://jlss.science-scholarships.ph/", "description": "Need-based JLSS track for talented students whose household socio-economic indicators do not exceed DOST-SEI cut-off values. Requires utility bills and tax exemption documentation.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 83.0}}', NULL, '2026-07-26 09:42:55.512655');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (118, 123, 1, '{"action": "create", "snapshot": {"title": "DOST-SEI Junior Level Science Scholarship \u2014 RA 10612 Track", "provider": "Department of Science and Technology - Science Education Institute (DOST-SEI)", "source": "discovery_verification", "link": "https://jlss.science-scholarships.ph/", "description": "Teacher-track JLSS for graduates committed to teaching STEM full-time in secondary schools. No restrictive income limits. DepEd provides deployment support.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 83.0}}', NULL, '2026-07-26 09:42:56.387321');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (119, 124, 1, '{"action": "create", "snapshot": {"title": "OWWA Education and Livelihood Assistance Program (ELAP)", "provider": "Overseas Workers Welfare Administration (OWWA)", "source": "discovery_verification", "link": "https://owwa.gov.ph/education-and-livelihood-assistance-program-elap/", "description": "Humanitarian educational and livelihood assistance for dependents of deceased active OWWA members or dependents of OFWs incarcerated/convicted with death penalty abroad.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": true, "data_status": "active", "eligible_levels": "[\"College\", \"Senior High School\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-07-26 09:42:57.247324');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (120, 125, 1, '{"action": "create", "snapshot": {"title": "DOH Medical Scholarship and Return Service Program", "provider": "Department of Health", "source": "gemini_research", "link": "https://doh.gov.ph", "description": "The DOH Medical Scholarship and Return Service (MSRS) Program is a major sector-specific government intervention operating under the ''Doktor Para sa Bayan'' Act (RA 11509) in partnership with CHED. It funds full medical education (Doctor of Medicine) for qualified Filipino students across certified state and partner private universities. It covers 100% of tuition, laboratory fees, provides a high monthly living allowance of 15,000 PHP, a specialized book/equipment allowance of 20,000 PHP per semester, and basic board exam review subsidies. Eligible applicants must hold a Bachelor''s degree with a solid GWA, pass the medical school entrance and NMAT, and prioritize low-income roots or origin from underserved rural towns. Return service requires serving as a public health officer in a government hospital or rural health unit (RHU) for 1 year for every year of scholarship.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"Graduate\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 600000, "min_gwa_normalized": 85.0}}', NULL, '2026-07-26 09:42:58.032959');
