INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (244, 127, 1, '{"action": "create", "snapshot": {"title": "OWWA Educational Livelihood Assistance Program College Track", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://owwa.gov.ph", "description": "The OWWA Educational Livelihood Assistance Program (ELAP) College Track is an allocation reserved for the children or dependents of active or deceased Overseas Filipino Workers (OFWs) who faced sudden distress, repatriation, or death while serving abroad. Distinct from the EDSP/ODSP merit lines, ELAP operates primarily as a livelihood-linked equity framework. It guarantees an educational subsidy of 10,000 PHP per year for the designated student dependent enrolled in any undergraduate college or technical track. Academic evaluation relies on basic passing marks (75% GWA) with no explicit ranking requirements. Online processing must clear the OWWA Regional Welfare Offices.", "min_age": null, "max_age": null, "application_deadline": "2026-07-15", "application_open_date": "2026-05-01", "is_active": true, "data_status": "expired", "eligible_levels": "[\"College\", \"TVET\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 250000, "min_gwa_normalized": 75.0}}', NULL, '2026-08-01 06:44:11.047516');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (245, 128, 1, '{"action": "create", "snapshot": {"title": "Aboitiz Future Leaders Scholarship Program", "provider": "Aboitiz Foundation", "source": "gemini_research", "link": "https://aboitiz.com/aboitiz-foundation/aboitiz-future-leaders-scholarship", "description": "Corporate scholarship for incoming sophomore students enrolled in partner state universities in engineering, data science, communications, and related fields. Covers full tuition, monthly allowance, and academic excellence incentives. Requires cumulative first-year GWA of 2.0 or better on the UP scale with no failing or incomplete grades, plus a mandatory 400-hour internship within Aboitiz Group business units.", "min_age": null, "max_age": null, "application_deadline": "2026-06-30", "application_open_date": "2026-04-28", "is_active": true, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": 75.0}}', NULL, '2026-08-01 06:44:12.258725');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (246, 129, 1, '{"action": "create", "snapshot": {"title": "CHED Merit Scholarship Program (CMSP)", "provider": "Commission on Higher Education", "source": "gemini_research", "link": "https://legacy.ched.gov.ph/merit-scholarship/", "description": "Legacy CHED merit program for incoming college freshmen with minimum 93% GWA and combined annual household income up to 500000 PHP. Covers tuition and fees for scholars in CHED-recognized programs nationwide. Open for AY 2026-2027 applications.", "min_age": null, "max_age": null, "application_deadline": "2026-07-31", "application_open_date": "2026-06-22", "is_active": true, "data_status": "expired", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 500000, "min_gwa_normalized": 93.0}}', NULL, '2026-08-01 06:44:13.280739');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (247, 130, 1, '{"action": "create", "snapshot": {"title": "DOST-SEI Junior Level Science Scholarship (JLSS)", "provider": "DOST-SEI", "source": "gemini_research", "link": "https://www.science-scholarships.ph/", "description": "Scholarship for incoming third-year college students pursuing science and technology degrees. Requires strong university GWA and completion of the first two years of a four- or five-year STEM program. Provides tuition, monthly living allowance, and learning materials support similar to the undergraduate program.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": null, "min_gwa_normalized": null}}', NULL, '2026-08-01 06:44:14.375804');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (248, 131, 1, '{"action": "create", "snapshot": {"title": "SM Foundation College Scholarship Program", "provider": "SM Foundation", "source": "gemini_research", "link": "https://scholarship.sm-foundation.org/", "description": "Corporate scholarship for graduating Grade 12 students from public schools or private voucher completers with household income up to 250000 PHP per year and minimum 92% GWA. Covers full tuition and fees plus monthly stipend at partner schools across designated regions. Includes semestral employment and post-graduation job placement within the SM Group.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[\"NCR\", \"Region III - Central Luzon\", \"Region IV-A - Calabarzon\", \"Region V - Bicol\", \"Region VI - Western Visayas\", \"Region VII - Central Visayas\", \"Region VIII - Eastern Visayas\", \"Region IX - Zamboanga Peninsula\", \"Region X - Northern Mindanao\", \"Region XI - Davao\", \"Region XII - Soccsksargen\", \"Region XIII - Caraga\"]", "eligible_cities": "[]", "max_income_threshold": 250000, "min_gwa_normalized": 92.0}}', NULL, '2026-08-01 06:44:15.191437');
INSERT INTO "scholarship_versions" (id, scholarship_id, version_number, changes, changed_by, changed_at) VALUES (249, 132, 1, '{"action": "create", "snapshot": {"title": "Megaworld Foundation College Scholarship", "provider": "Megaworld Foundation", "source": "gemini_research", "link": "https://www.megaworldfoundation.com/scholarship/apply/form", "description": "Corporate college scholarship for underprivileged students in STEM, engineering, IT, business, and architecture. Requires minimum 85% GWA with zero dropped subjects and combined household income not exceeding 400000 PHP. Covers full tuition and institutional fees plus monthly stipend.", "min_age": null, "max_age": null, "application_deadline": null, "application_open_date": null, "is_active": false, "data_status": "active", "eligible_levels": "[\"College\"]", "eligible_regions": "[]", "eligible_cities": "[]", "max_income_threshold": 400000, "min_gwa_normalized": 85.0}}', NULL, '2026-08-01 06:44:16.137982');
