INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (1, 'Pasig City Regular Academic Scholarship', 'Pasig City Government', 'gemini_research', '{"title": "Pasig City Regular Academic Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "The Pasig City Regular Academic Scholarship is designed for residents of Pasig City who demonstrate high academic performance and are enrolled in recognized higher education institutions. This program provides comprehensive tuition assistance and stipends to support college education for local youths. Applicants must maintain a minimum GWA of 85% or equivalent, with no grade lower than 85% in any subject. Eligibility requires presenting a valid Pasig City LGU ID or Barangay Certificate of Residency proving at least 3 years of residency, and registered voter status for parents or applicants of legal age. Application steps involve registering online via the official Pasig Scholarship portal, uploading scanned requirements, and attending an orientation once approved. Highly recurring cycle opening every first semester of the academic year. Financial need is factored via an annual family income cap of 300,000 PHP.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Pasig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All accredited undergraduate degrees", "max_income_threshold": "300000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "4Ps|Listahanan", "benefit_tuition": "true", "benefit_allowance_monthly": "1500", "benefit_books": "true", "benefit_total_value": "25000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|GOOD_MORAL|TOR", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-07-01", "application_deadline": "2026-08-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-07-05", "last_close_date": "2025-08-20", "is_active": "true", "source_slug": "pasig_city_regular_academic_2026", "research_notes": "application_status=opening_soon | confidence=high | link_quality=primary", "source_urls": "https://scholars.pasigcity.gov.ph|https://assets.pasigcity.gov.ph", "dedupe_rationale": "Net-new LGU program specific to Pasig City residents not present in Round 1."}', 'approved', '4ebc5ddc93c0dd225233b1e4eba12994c93637144e1032b7c2be308aaab3a1d2', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:07.351379');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (2, 'Pasig City Sports Scholarship', 'Pasig City Government', 'gemini_research', '{"title": "Pasig City Sports Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "The Pasig City Sports Scholarship caters to outstanding student-athletes who have represented Pasig City or their schools in regional, national, or international athletic competitions. It aims to support athletes in balancing academic progression with rigorous athletic training. Eligibility includes verified residency in Pasig City for 3 years, a minimum GWA of 80% to ensure academic compliance, and official endorsements from the Pasig Sports Development Office. Financial aid covers partial tuition and a monthly training stipend. Renewal requires active sports participation and maintaining passing marks. Portal registrations open annually in August.", "provider_type": "LGU", "scholarship_type": "Affiliation", "eligible_levels": "College|Grade 11|Grade 12", "eligible_regions": "NCR", "eligible_cities": "Pasig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All courses", "max_income_threshold": "350000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "Student Athletes", "benefit_tuition": "true", "benefit_allowance_monthly": "2000", "benefit_books": "true", "benefit_total_value": "30000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|FORM_137", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-08-01", "application_deadline": "2026-09-10", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-08-05", "last_close_date": "2025-09-15", "is_active": "true", "source_slug": "pasig_city_sports_scholarship_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://scholars.pasigcity.gov.ph", "dedupe_rationale": "Distinct athletic-based track with separate funding and GWA criteria from Pasig Regular."}', 'approved', '4dfa54a55ed7df2da5c4012ce61d7dcae6f37f63d68ef2c1a8efafa59d42779e', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:25.766038');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (3, 'Pasig City Arts and Design Scholarship', 'Pasig City Government', 'gemini_research', '{"title": "Pasig City Arts and Design Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "This dedicated track supports creative individuals residing in Pasig City who pursue fields in fine arts, digital design, music, performing arts, or literature. Eligible applicants must showcase a portfolio or pass a talent audition managed by the Pasig Cultural Affairs Office. Academic requirements are set at a minimum GWA of 80%. Benefits include school fees financial aid and materials allowances. Registration is completed through the online portal, followed by an in-person portfolio review.", "provider_type": "LGU", "scholarship_type": "Affiliation", "eligible_levels": "College|Grade 11|Grade 12", "eligible_regions": "NCR", "eligible_cities": "Pasig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "Arts", "eligible_courses_specific": "Fine Arts|Digital Design|Music|Performing Arts", "max_income_threshold": "350000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "Artists and Creatives", "benefit_tuition": "true", "benefit_allowance_monthly": "1500", "benefit_books": "true", "benefit_total_value": "28000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|FORM_137|ESSAY", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-08-01", "application_deadline": "2026-09-10", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-08-05", "last_close_date": "2025-09-15", "is_active": "true", "source_slug": "pasig_city_arts_design_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://scholars.pasigcity.gov.ph", "dedupe_rationale": "Targeted LGU creative arts track absent from the baseline document."}', 'approved', '986b57cb5b04aacae465da1bed392be2cac845641cb0e3fe44c2c9c2bea5f84f', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:10.038784');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (4, 'Pasig City Out-of-School Learners Scholarship', 'Pasig City Government', 'gemini_research', '{"title": "Pasig City Out-of-School Learners Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "Designed specifically for out-of-school youths (OSYs) and adult learners in Pasig City who want to reintegrate into formal education, alternative learning systems (ALS), or technical-vocational (TVET) paths. Funded fully by the LGU, this program waives instructional fees and provides a substantial monthly allowance to cover daily transport and meal costs. Eligibility includes a minimum of 1 year of non-enrollment in school and a family income below 200,000 PHP. Applications are accepted directly through the Pasig Scholarship Office or Barangay halls.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "TVET|College", "eligible_regions": "NCR", "eligible_cities": "Pasig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "ALS and TVET short courses", "max_income_threshold": "200000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "Out of School Youth", "benefit_tuition": "true", "benefit_allowance_monthly": "2500", "benefit_books": "true", "benefit_total_value": "35000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|4PS_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-15", "application_deadline": "2026-07-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-20", "last_close_date": "2025-07-25", "is_active": "true", "source_slug": "pasig_city_osl_scholarship_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://scholars.pasigcity.gov.ph|https://assets.pasigcity.gov.ph", "dedupe_rationale": "Special social welfare track for out-of-school youth reintegration."}', 'approved', '519de69b3565064078e0a20d20e42a8642579816e6fa387f66520c727c9574af', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:26.839115');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (5, 'Pasig City Sangguniang Kabataan Endorsed Scholarship', 'Pasig City Government', 'gemini_research', '{"title": "Pasig City Sangguniang Kabataan Endorsed Scholarship", "provider": "Pasig City Government", "source": "gemini_research", "link": "https://scholars.pasigcity.gov.ph", "description": "A localized financial-aid track administered in collaboration with the Barangay Sangguniang Kabataan (SK) councils of Pasig City. This scholarship targets active community youth volunteers and leaders. Eligible applicants must possess a formal endorsement from their respective Barangay SK Chairman certifying leadership and civic engagement hours. A minimum GWA of 82% is required. Benefits comprise an annual educational subsidy disbursed in two semester installments.", "provider_type": "LGU", "scholarship_type": "Affiliation", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Pasig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate programs", "max_income_threshold": "250000", "min_gwa_normalized": "82", "min_age": null, "max_age": null, "priority_groups": "Community Leaders", "benefit_tuition": "false", "benefit_allowance_monthly": "1500", "benefit_books": "true", "benefit_total_value": "20000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2026-07-10", "application_deadline": "2026-08-20", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-07-12", "last_close_date": "2025-08-25", "is_active": "true", "source_slug": "pasig_city_sk_endorsed_2026", "research_notes": "application_status=opening_soon | confidence=high | link_quality=primary", "source_urls": "https://scholars.pasigcity.gov.ph", "dedupe_rationale": "SK leadership affiliation-based LGU grant omitted in Round 1."}', 'approved', '4ae883e9c19511ed51a53a6fcb0b0a75505ee524f49a5f86e1aa1f03fb60fce9', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:27.932107');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (6, 'Taguig LANI Premier Scholarship', 'Taguig City Government', 'gemini_research', '{"title": "Taguig LANI Premier Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The Lifeline Assistance for Neighbors in Need (LANI) Premier Scholarship is Taguig City''s flagship merit track for top-tier residents studying in prestigious private universities or high-cost specialized institutions (e.g., UP, DLSU, ADMU, UST, Mapua). Applicants must be registered voters of Taguig for at least 3 years and have a minimum GWA of 90% (1.50 or better) with zero failing grades. It offers substantial financial aid up to 50,000 PHP per semester to directly cover tuition fees and modern learning tools. Applications are submitted via the Taguig LANI portal or at the Taguig Civic Center scholarship desk. Highly structured and strictly recurring every semester.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Taguig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "Top-tier institutional degrees", "max_income_threshold": "600000", "min_gwa_normalized": "90", "min_age": null, "max_age": null, "priority_groups": "Top 10 Percent Graduates", "benefit_tuition": "true", "benefit_allowance_monthly": "3000", "benefit_books": "true", "benefit_total_value": "100000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-06-20", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2026-01-05", "last_close_date": "2026-02-15", "is_active": "true", "source_slug": "taguig_lani_premier_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://tcu.edu.ph/lani-scholarship|https://www.taguig.gov.ph", "dedupe_rationale": "LANI flagship elite track for top private/specialized universities."}', 'approved', '935a1e82c295819063f11b9a1fc5216c83bfe62bea1c3f6ba3d85195194eb76f', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:23.597302');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (7, 'Taguig LANI Full Scholarship', 'Taguig City Government', 'gemini_research', '{"title": "Taguig LANI Full Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The LANI Full Scholarship track supports Taguig residents enrolled in private higher education institutions within or outside Metro Manila. It is designed to alleviate tuition burdens for middle-income families. Requires a minimum GWA of 85% (2.0 or better) and 3 years of verifiable city residency. Provides a flat cash assistance rate of 20,000 PHP to 25,000 PHP per semester. Renewal is contingent upon submitting semestral grade sheets confirming no failing marks. Online application processing is strictly required through the LANI desk.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Taguig", "residency_required": "true", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All approved degree programs", "max_income_threshold": "450000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Middle Income Learners", "benefit_tuition": "true", "benefit_allowance_monthly": "2000", "benefit_books": "true", "benefit_total_value": "50000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR|ITR", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-20", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2026-01-05", "last_close_date": "2026-02-15", "is_active": "true", "source_slug": "taguig_lani_full_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://tcu.edu.ph/lani-scholarship", "dedupe_rationale": "Standard full-tuition LANI option for private colleges; distinct criteria."}', 'approved', 'e535c7930736630797e85ac28798fc0b4c81cc9848800d8a5e26ceff7ffff3de', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:28.989547');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (8, 'Taguig LANI Priority Scholarship', 'Taguig City Government', 'gemini_research', '{"title": "Taguig LANI Priority Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "This specific LANI track directly targets priority fields of study essential for national development and city workforce planning, including STEM, digital engineering, data analytics, special education, and specialized medical courses. Eligible applicants need a minimum GWA of 82%. Financial benefits are elevated compared to basic tracks, supplying up to 30,000 PHP per semester. Priority status is also given to low-income applicants, PWDs, and dependents of solo parents.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Taguig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical", "eligible_courses_specific": "STEM and Allied Medical Courses", "max_income_threshold": "350000", "min_gwa_normalized": "82", "min_age": null, "max_age": null, "priority_groups": "PWD|Solo Parent Dependents", "benefit_tuition": "true", "benefit_allowance_monthly": "2500", "benefit_books": "true", "benefit_total_value": "60000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR|4PS_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-20", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2026-01-05", "last_close_date": "2026-02-15", "is_active": "true", "source_slug": "taguig_lani_priority_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://tcu.edu.ph/lani-scholarship", "dedupe_rationale": "Course-restricted LANI track prioritizing STEM and health sciences."}', 'approved', '5590ff0f69c4de940fad306b2b1e583926881bddf03a0623ed336c8b8ab0e6b2', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:25.686729');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (9, 'Taguig LANI Basic Scholarship', 'Taguig City Government', 'gemini_research', '{"title": "Taguig LANI Basic Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The LANI Basic Scholarship is a broad-access financial assistance grant for Taguig residents enrolled in non-priority programs across public or private institutions. It operates under a lower academic barrier, requiring only a passing GWA of 78% (3.0 or equivalent). It guarantees basic equity support, providing 10,000 PHP per semester to handle textbooks, uniform fees, and transportation costs. Verification of local voter registration is strictly checked during the mandatory manual verification phase.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Taguig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate degrees", "max_income_threshold": "300000", "min_gwa_normalized": "78", "min_age": null, "max_age": null, "priority_groups": "Low Income Families", "benefit_tuition": "false", "benefit_allowance_monthly": "1000", "benefit_books": "true", "benefit_total_value": "20000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-20", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2026-01-05", "last_close_date": "2026-02-15", "is_active": "true", "source_slug": "taguig_lani_basic_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://tcu.edu.ph/lani-scholarship", "dedupe_rationale": "Low-barrier mass-equity LANI track missing from the Round 1 catalog."}', 'approved', '63b057456d8492b7027fa552b3ea79dada264a71e4ea78a67a10f2755ae0f5cf', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:30.053000');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (10, 'Taguig LANI LCU and SUC Assistance Scholarship', 'Taguig City Government', 'gemini_research', '{"title": "Taguig LANI LCU and SUC Assistance Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "This scholarship is specially tailored for Taguig residents who are already utilizing the Free Higher Education law at State Universities and Colleges (SUCs) or Local Colleges and Universities (LCUs) like Taguig City University (TCU) or PUP. Since tuition is free, this track converts assistance into a pure monthly cash living stipend of 1,500 PHP plus 2,000 PHP per semester for books. Requires a GWA of 80% and zero failures. Online submission occurs via the unified TCU-LANI interface.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Taguig", "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "SUC and LCU courses", "max_income_threshold": "250000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "SUC|LCU Students", "benefit_tuition": "false", "benefit_allowance_monthly": "1500", "benefit_books": "true", "benefit_total_value": "19000", "required_documents": "BARANGAY_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-20", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2026-01-05", "last_close_date": "2026-02-15", "is_active": "true", "source_slug": "taguig_lani_suc_lcu_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://tcu.edu.ph/lani-scholarship", "dedupe_rationale": "Pure living stipend track tailored for students enrolled in free-tuition SUCs/LCUs."}', 'approved', '0adb2b3169ffc681dc6273b7b29a2a3a27e1e82204a6119dfb93e07ffe950b7f', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:26.956686');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (11, 'Taguig LANI LEAD Graduate Scholarship', 'Taguig City Government', 'gemini_research', '{"title": "Taguig LANI LEAD Graduate Scholarship", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "The Leadership and Educators Advancement and Development (LEAD) program is an advanced LANI track designed for licensed teachers, city employees, and professionals residing in Taguig who are pursuing Master''s or Doctorate degrees. It funds advanced research, dissertation expenses, and postgraduate tuition up to 40,000 PHP per semester. Applicants must maintain a postgrad GWA of 2.0 (85%) and submit an approved thesis proposal. Return service involves a mandatory 1-year community or institutional service within Taguig for every year of funding.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": "NCR", "eligible_cities": "Taguig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Education|Medical|Business", "eligible_courses_specific": "Master''s and Doctoral Programs", "max_income_threshold": "750000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Public Servants and Teachers", "benefit_tuition": "true", "benefit_allowance_monthly": "2000", "benefit_books": "true", "benefit_total_value": "80000", "required_documents": "BARANGAY_CERT|TOR|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-05-15", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-20", "last_close_date": "2025-06-28", "is_active": "false", "source_slug": "taguig_lani_lead_grad_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://tcu.edu.ph/lani-scholarship", "dedupe_rationale": "Postgraduate LANI track with strict return service rules; completely net-new."}', 'approved', 'eb2c45c5a0e5f83ba1b92d68247eacd8e03f1a0ae1652ff88f4d8beaea472b9c', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:31.135873');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (12, 'Taguig Lifeline Bar and Board Review Assistance', 'Taguig City Government', 'gemini_research', '{"title": "Taguig Lifeline Bar and Board Review Assistance", "provider": "Taguig City Government", "source": "gemini_research", "link": "https://tcu.edu.ph/lani-scholarship", "description": "A specialized, one-time financial grant for Taguig residents who have completed their undergraduate degrees in Law, Engineering, Nursing, Accountancy, or Education and are preparing for professional licensure examinations (PRC Board Exams or Supreme Court Bar Exam). Provides a lump-sum financial grant of 15,000 PHP to 30,000 PHP to pay for review center enrollments and examination fees. Requires graduation proof, a certification from an official review center, and voter verification. No GWA check is enforced post-graduation.", "provider_type": "LGU", "scholarship_type": "Affiliation", "eligible_levels": "Graduate|College", "eligible_regions": "NCR", "eligible_cities": "Taguig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|Education|Medical|Business", "eligible_courses_specific": "Board or Bar review courses", "max_income_threshold": "600000", "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": "Board Exam Takers", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "30000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-04-01", "application_deadline": "2026-05-30", "academic_year_target": "2026-2027", "cycle_type": "rolling", "last_open_date": "2025-04-05", "last_close_date": "2025-05-28", "is_active": "false", "source_slug": "taguig_lifeline_review_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://tcu.edu.ph/lani-scholarship", "dedupe_rationale": "Short-term, one-time post-graduate professional licensure assistance track."}', 'approved', '600bce1fa29d430f01e1d8330f4d52f9cae5828547f4a63221d68069d109d53c', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:28.388905');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (13, 'Makati City Premier and Specialized School Scholarship', 'Makati City Government', 'gemini_research', '{"title": "Makati City Premier and Specialized School Scholarship", "provider": "Makati City Government", "source": "gemini_research", "link": "https://www.makati.gov.ph", "description": "The Makati City Government Scholarship Program offers elite financial backing to top-tier Makati residents who secure admission into designated Centers of Excellence or top private universities (such as DLSU, ADMU, UST, Mapua). Applicants must provide proof of at least 5 years of continuous city residency, valid Makati LGU ID/QCitizen equivalent, and rank in the top 10% of their graduating Senior High School class. It supplies up to 80,000 PHP annually for tuition and institutional fees. Recipients must sign a contract committing to a mandatory 2-year return service within the Makati LGU or city public school system upon graduation. GWA maintenance of 88% (1.75) is strictly audited per semester.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Makati", "residency_required": "true", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business", "eligible_courses_specific": "Elite institutional programs", "max_income_threshold": "500000", "min_gwa_normalized": "88", "min_age": null, "max_age": null, "priority_groups": "Top 10 Percent Graduates", "benefit_tuition": "true", "benefit_allowance_monthly": "4000", "benefit_books": "true", "benefit_total_value": "80000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2026-06-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-02", "last_close_date": "2025-07-20", "is_active": "true", "source_slug": "makati_city_premier_2026", "research_notes": "application_status=open | confidence=high | link_quality=secondary", "source_urls": "https://www.makati.gov.ph|https://mirror.pia.gov.ph", "dedupe_rationale": "Elite private university track for Makati residents with a 2-year service obligation."}', 'approved', 'c21a82a8eb4e02fec103ba215f19dfaf6413c1f241705832190881949c0a4b4d', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:32.198095');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (14, 'Makati City SUC and Priority Courses Scholarship', 'Makati City Government', 'gemini_research', '{"title": "Makati City SUC and Priority Courses Scholarship", "provider": "Makati City Government", "source": "gemini_research", "link": "https://www.makati.gov.ph", "description": "This LGU track caters to Makati residents enrolled in State Universities and Colleges (outside of UMak) pursuing priority industrial fields like IT, engineering, and digital science. It grants 20,000 PHP per semester to offset learning materials, transportation, and field training expenses. It requires 5 years of residency and an overall GWA of 82% (2.25) with no grades lower than 80%. Applications are handled through the Makati Education Department at City Hall.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Makati", "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT", "eligible_courses_specific": "IT and Engineering courses", "max_income_threshold": "300000", "min_gwa_normalized": "82", "min_age": null, "max_age": null, "priority_groups": "Low to Middle Income", "benefit_tuition": "false", "benefit_allowance_monthly": "2000", "benefit_books": "true", "benefit_total_value": "40000", "required_documents": "BARANGAY_CERT|TOR|ITR", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-02", "last_close_date": "2025-07-20", "is_active": "true", "source_slug": "makati_city_suc_priority_2026", "research_notes": "application_status=open | confidence=high | link_quality=secondary", "source_urls": "https://www.makati.gov.ph", "dedupe_rationale": "Non-UMak SUC track for Makati residents emphasizing localized technical fields."}', 'approved', '3094ec5dd951c45df4549868b7cf328c0604d73d0b931e03bf1bc07c4281bf9b', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:29.174927');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (15, 'University of Makati Token Fee Exemption Program', 'University of Makati (UMak)', 'gemini_research', '{"title": "University of Makati Token Fee Exemption Program", "provider": "University of Makati (UMak)", "source": "gemini_research", "link": "https://www.umak.edu.ph", "description": "The University of Makati (UMak) Token Fee Exemption Program serves as an institutional academic scholarship that waives the remaining standard token fees for high-performing student residents of Makati. Administered by the UMak Scholarship Office, applicants must achieve a GWA of 1.75 (88%) or better during their semester and maintain a full academic load. The program converts academic excellence directly into fully zeroed tuition liabilities and offers priority enlistment. Application is processed entirely internally through the UMak student portal at the close of every grading period.", "provider_type": "Institutional", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Makati", "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All UMak college courses", "max_income_threshold": "250000", "min_gwa_normalized": "88", "min_age": null, "max_age": null, "priority_groups": "UMak Internals", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "5000", "required_documents": "TOR|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-10", "application_deadline": "2026-06-25", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2025-05-15", "last_close_date": "2025-06-30", "is_active": "false", "source_slug": "umak_token_fee_exemption_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.umak.edu.ph/admissions/scholarships", "dedupe_rationale": "UMak internal institutional merit track distinct from general LGU grants."}', 'approved', '249b421c3c3c8b37d249776f1fc8fbbe5508c3fc7880c381002150bb1cecb97c', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:36.303516');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (16, 'University of Makati Special Institutional Scholarship', 'University of Makati (UMak)', 'gemini_research', '{"title": "University of Makati Special Institutional Scholarship", "provider": "University of Makati (UMak)", "source": "gemini_research", "link": "https://www.umak.edu.ph", "description": "UMak''s Special Institutional Scholarship provides targeted need-and-affiliation assistance for unique sectors inside the university community, including registered PWD students, certified children of active Makati LGU employees, barangay officials, and student-artists in the UMak cultural troupe. It provides complete fee exemptions and a monthly book allowance of 1,000 PHP. Candidates must hold a GWA of 75% (passing) with no dropped or incomplete modules. Formal verification requires presenting civil service certificates or PWD IDs.", "provider_type": "Institutional", "scholarship_type": "Affiliation", "eligible_levels": "College|TVET", "eligible_regions": "NCR", "eligible_cities": "Makati", "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All UMak offerings", "max_income_threshold": "350000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "PWD|LGU Dependents", "benefit_tuition": "true", "benefit_allowance_monthly": "1000", "benefit_books": "true", "benefit_total_value": "15000", "required_documents": "BARANGAY_CERT|TOR|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-10", "application_deadline": "2026-06-25", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2025-05-15", "last_close_date": "2025-06-30", "is_active": "false", "source_slug": "umak_special_scholarship_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.umak.edu.ph/admissions/scholarships", "dedupe_rationale": "Affiliation-based institutional grant for specific Makati employee/PWD sectors."}', 'approved', 'a4ad7ff94457da1f223c91adf8c7d865b77e929a06f111520470376b2a92f47a', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:33.261971');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (17, 'Valenzuela City Dr. Pio Valenzuela Scholarship Program', 'Valenzuela City Government', 'gemini_research', '{"title": "Valenzuela City Dr. Pio Valenzuela Scholarship Program", "provider": "Valenzuela City Government", "source": "gemini_research", "link": "https://valenzuela.gov.ph/drpioscholarship", "description": "The Dr. Pio Valenzuela Scholarship Program is an intensive LGU merit-need initiative by the Valenzuela City Government. It targets financially challenged but academically elite student residents. Eligible individuals must have spent at least 4 consecutive years in Valenzuela City, graduated Senior High School with a GWA of 85% or higher, and hold zero grades lower than 85% in Grades 11 and 12. Crucially, the total annual household income must not exceed 120,000 PHP. The program awards a financial support grant of 30,000 PHP per year (15,000 PHP per semester) for tuition and school compliance. Portal submissions require uploading digital copies of ITR or Indigency certificates, Form 138/137, and Barangay clearance.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Valenzuela", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate degrees", "max_income_threshold": "120000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Indigent Achievers", "benefit_tuition": "true", "benefit_allowance_monthly": "2000", "benefit_books": "true", "benefit_total_value": "30000", "required_documents": "FORM_137|BARANGAY_CERT|ITR|BIRTH_CERT", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-15", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-20", "last_close_date": "2025-08-05", "is_active": "true", "source_slug": "valenzuela_dr_pio_scholarship_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://valenzuela.gov.ph/drpioscholarship|https://valenzuela.gov.ph/files/pdfs/scholarship_form.pdf", "dedupe_rationale": "Strict local income cap (120k) LGU scholarship program with high GWA criteria."}', 'approved', 'b3b97af4631ab9ef6bba369535e5b6c91e4a85d94d63ef916402f3eec63efdfa', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:39.225151');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (18, 'Muntinlupa MOST Academic Scholarship', 'Muntinlupa Scholarship Division', 'gemini_research', '{"title": "Muntinlupa MOST Academic Scholarship", "provider": "Muntinlupa Scholarship Division", "source": "gemini_research", "link": "https://www.muntinlupacity.gov.ph", "description": "The Muntinlupa Outstanding Students (MOST) Scholarship is an elite academic grant given to the top 10 highest-ranking graduating Senior High School students from every public and private high school operating in Muntinlupa City. Managed by the Muntinlupa Scholarship Division (MSD), it applies strictly to individuals who secure entry into premier State Universities (such as UP Diliman/Los Banos) or top-tier private institutions. It offers absolute tuition coverage up to 100,000 PHP annually, alongside a high monthly stipend of 5,000 PHP. Academic maintenance is strictly tied to a GWA of 1.50 (90%) with zero failures. Applications require certified high school ranking documents and automated validation.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Muntinlupa", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical", "eligible_courses_specific": "Top tier national courses", "max_income_threshold": "500000", "min_gwa_normalized": "90", "min_age": null, "max_age": null, "priority_groups": "Top Valedictorians", "benefit_tuition": "true", "benefit_allowance_monthly": "5000", "benefit_books": "true", "benefit_total_value": "130000", "required_documents": "FORM_137|GOOD_MORAL|BIRTH_CERT", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-05", "last_close_date": "2025-06-20", "is_active": "false", "source_slug": "muntinlupa_most_scholarship_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=secondary", "source_urls": "https://www.muntinlupacity.gov.ph", "dedupe_rationale": "Highly selective top-10 graduation rank LGU merit award omitted in Round 1."}', 'approved', '5c917d3c4d287986558f441c10164183fe0992685aad385920411213c0a95918', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:01.056514');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (19, 'Muntinlupa CARES Financial Assistance Program', 'Muntinlupa Scholarship Division', 'gemini_research', '{"title": "Muntinlupa CARES Financial Assistance Program", "provider": "Muntinlupa Scholarship Division", "source": "gemini_research", "link": "https://www.muntinlupacity.gov.ph", "description": "The Continuing Assistance for Reintegrating Students (CARES) is a equity-driven financial assistance mechanism for general college residents of Muntinlupa who are enrolled in public SUCs or local community colleges. It requires a baseline GWA of 80% (2.5) with no incomplete or failing grades. It disburses a direct financial support grant of 5,000 PHP per semester to cover transport and digital connectivity needs. Financial status is verified via Barangay Certificate of Indigency or low-income ITR. Registration occurs semestrally via the MSD localized offices.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Muntinlupa", "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All standard courses", "max_income_threshold": "200000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "Low Income Residents", "benefit_tuition": "false", "benefit_allowance_monthly": "1000", "benefit_books": "false", "benefit_total_value": "10000", "required_documents": "BARANGAY_CERT|TOR|4PS_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-07-20", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2026-01-10", "last_close_date": "2026-02-25", "is_active": "true", "source_slug": "muntinlupa_cares_program_2026", "research_notes": "application_status=open | confidence=high | link_quality=secondary", "source_urls": "https://www.muntinlupacity.gov.ph", "dedupe_rationale": "Broad need-based LGU assistance program operating in Muntinlupa."}', 'approved', 'a4ef4987bbb05887f1f18a09cf567ca84d56deaca5fb797114240a819e3f2680', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:04.000312');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (20, 'NavotaAs Academic College Scholarship', 'Navotas City Government', 'gemini_research', '{"title": "NavotaAs Academic College Scholarship", "provider": "Navotas City Government", "source": "gemini_research", "link": "https://www.navotas.gov.ph", "description": "The NavotaAs Academic Scholarship Program is the baseline higher-education track for residents of Navotas City. It supports incoming first-year college students who graduated in the top 25% of their Senior High School class. Eligible applicants must have parents who are registered voters of Navotas. When utilized at the Navotas Polytechnic College (NPC), it yields full tuition exemption plus 22,000 PHP per year for allowances. If the student passes into other prominent universities outside Navotas, the grant upgrades to a merit value of 262,000 PHP per year to handle high tuition. Applications are manually screened by the Navotas Scholarship Secretariat.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Navotas", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All accredited college paths", "max_income_threshold": "400000", "min_gwa_normalized": "88", "min_age": null, "max_age": null, "priority_groups": "Top Academic Quartile", "benefit_tuition": "true", "benefit_allowance_monthly": "2200", "benefit_books": "true", "benefit_total_value": "262000", "required_documents": "FORM_137|BARANGAY_CERT|BIRTH_CERT", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-07-10", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-05", "last_close_date": "2025-07-15", "is_active": "true", "source_slug": "navotas_academic_college_2026", "research_notes": "application_status=open | confidence=high | link_quality=secondary", "source_urls": "https://www.navotas.gov.ph", "dedupe_rationale": "High-value LGU merit model expanding funding if studying outside the home city."}', 'approved', 'ee2f2b596a7cec7db044b47a1c2615d22781ce9c9e2fffcd8af9bc07d8d3bf6b', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:41.206329');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (21, 'NavotaAs Fisherfolk Children Scholarship Track', 'Navotas City Government', 'gemini_research', '{"title": "NavotaAs Fisherfolk Children Scholarship Track", "provider": "Navotas City Government", "source": "gemini_research", "link": "https://www.navotas.gov.ph", "description": "A sector-specific LGU track designed to extend educational equity to the children of registered municipal fisherfolk in Navotas City. Administered under the NavotaAs framework, applicants must submit a certified copy of their parent''s Navotas Fisherfolk Registration ID or validation from the City Agriculture Office. Academic performance requires a standard passing GWA of 78%. It funds full college or TVET technical training at local institutes, along with a monthly sea-fare/allowance of 1,500 PHP. Highly recurring and designed to break generation poverty in maritime-coastal zones.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "College|TVET", "eligible_regions": "NCR", "eligible_cities": "Navotas", "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All available courses", "max_income_threshold": "180000", "min_gwa_normalized": "78", "min_age": null, "max_age": null, "priority_groups": "Fisherfolk Children", "benefit_tuition": "true", "benefit_allowance_monthly": "1500", "benefit_books": "true", "benefit_total_value": "20000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-07-10", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-05", "last_close_date": "2025-07-15", "is_active": "true", "source_slug": "navotas_fisherfolk_children_2026", "research_notes": "application_status=open | confidence=high | link_quality=secondary", "source_urls": "https://www.navotas.gov.ph", "dedupe_rationale": "Specialized coastal equity LGU scholarship for fisherfolk dependents."}', 'approved', 'b47953d510407e0932dafe57cbc8952e9d0961dbd589f2e10a51aeea1f318dd0', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:34.316828');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (22, 'Marikina City Medical Scholarship Program', 'Marikina City Government', 'gemini_research', '{"title": "Marikina City Medical Scholarship Program", "provider": "Marikina City Government", "source": "gemini_research", "link": "https://www.marikina.gov.ph", "description": "The Marikina City Medical Scholarship Program is a localized government intervention to support aspiring medical doctors who reside in Marikina City. It covers full tuition and provides educational assistance up to 150,000 PHP per year for students accepted into partner Doctor of Medicine programs (including PLM, FEU-NRMF, UST, MCU, St. Luke''s, Our Lady of Fatima University). Applicants must not exceed 30 years of age, must possess a clean record of good moral character, and maintain a household income below 600,000 PHP. Return service dictates that the recipient must practice medicine within the Marikina public healthcare network or city clinics for a duration matching the length of the scholarship.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "Graduate", "eligible_regions": "NCR", "eligible_cities": "Marikina", "residency_required": "true", "eligible_school_types": "Private|Public", "eligible_courses_psced": "Medical", "eligible_courses_specific": "Doctor of Medicine (MD)", "max_income_threshold": "600000", "min_gwa_normalized": "85", "min_age": null, "max_age": "30", "priority_groups": "Aspiring Physicians", "benefit_tuition": "true", "benefit_allowance_monthly": "4000", "benefit_books": "true", "benefit_total_value": "150000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL|ESSAY", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-05-01", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-10", "last_close_date": "2025-06-20", "is_active": "false", "source_slug": "marikina_medical_scholarship_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=secondary", "source_urls": "https://www.marikina.gov.ph", "dedupe_rationale": "Targeted graduate medical track by Marikina LGU with explicit partner-school ties."}', 'approved', '7495c7d528be9810083220afdf282cb629289bfa03ceb1c63cf7906dc5ff6223', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:42.292882');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (23, 'Parañaque City Tertiary Education Financial Assistance Program', 'Parañaque City Government', 'gemini_research', '{"title": "Para\u00f1aque City Tertiary Education Financial Assistance Program", "provider": "Para\u00f1aque City Government", "source": "gemini_research", "link": "https://www.paranaquecity.gov.ph", "description": "The Tertiary Education Financial Assistance Program (TEFAP) is an open-access equity grant run by the Para\u00f1aque LGU for resident college students. To fit varying academic profiles, the cash stipend scales directly with academic performance: students maintaining a GWA of 88% and above receive 6,000 PHP per semester, while those with a GWA between 80% and 87% receive 4,000 PHP per semester. Requirements demand 3 years of residency and a parent''s voter registration record inside Para\u00f1aque. Online registrations are queued via the local city hall portal.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": "Para\u00f1aque", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate paths", "max_income_threshold": "300000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "General College Residents", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "12000", "required_documents": "BARANGAY_CERT|TOR|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-07-01", "application_deadline": "2026-08-20", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2025-07-10", "last_close_date": "2025-08-25", "is_active": "true", "source_slug": "paranaque_tefap_2026", "research_notes": "application_status=opening_soon | confidence=medium | link_quality=secondary", "source_urls": "https://www.paranaquecity.gov.ph", "dedupe_rationale": "Scalable financial grant based on tiered GWA levels for Para\u00f1aque residents."}', 'approved', 'fcdb1cf1d7bb64d8740fcc00e91f5bf27c20fa4c33b35a31fbbcfe8f97ef16c4', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:08.028509');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (24, 'Cebu Province CP GIFTS Program', 'Cebu Provincial Government', 'gemini_research', '{"title": "Cebu Province CP GIFTS Program", "provider": "Cebu Provincial Government", "source": "gemini_research", "link": "https://www.cebu.gov.ph", "description": "The Cebu Province Grants Intended for Tertiary Students (CP-GIFTS) is a massive provincial scholarship initiative under the Office of the Governor. It funds 5,900 concurrent slots for poor but deserving students living across the municipalities and component cities of Cebu Province. Applicants must study at designated SUCs, LUCs, or partner private schools within Cebu and maintain a minimum GWA of 85%. Household income must not cross 200,000 PHP annually. It grants a definitive flat sum of 10,000 PHP per semester for school requirements. A mandatory return component requires executing 160 hours of verified community civic service within the student''s home municipality.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": "Region VII - Central Visayas", "eligible_cities": null, "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All accredited degrees in Cebu", "max_income_threshold": "200000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Provincial Rural Youth", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "20000", "required_documents": "BARANGAY_CERT|TOR|ITR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2026-06-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-15", "last_close_date": "2025-07-30", "is_active": "true", "source_slug": "cebu_province_cp_gifts_2026", "research_notes": "application_status=open | confidence=high | link_quality=secondary", "source_urls": "https://www.cebu.gov.ph|https://cebudailynews.inquirer.net", "dedupe_rationale": "Substantial provincial equity program for Cebu with explicit community service hours."}', 'approved', '1fb13f248884a4004112a17a39ba636c594382227a13a3f1600798682b8bab18', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:06.418150');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (25, 'Cebu City College Scholarship Program', 'Cebu City Government', 'gemini_research', '{"title": "Cebu City College Scholarship Program", "provider": "Cebu City Government", "source": "gemini_research", "link": "https://www.cebucity.gov.ph", "description": "The Cebu City College Scholarship Program (CCCSP) targets urban youth residents who graduated from public high schools located specifically within the north and south districts of Cebu City. It provides 10,000 PHP per semester for tuition if the recipient enrolls in accredited private universities, or 2,500 PHP per semester for books and uniform allowances if they enter tuition-free SUCs (like CTU or CNU). Requires a voter''s certification from Cebu City and a minimum GWA of 80%. Applications are handled at the Cebu City Sports Complex scholarship secretariat.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "Region VII - Central Visayas", "eligible_cities": "Cebu City", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate programs", "max_income_threshold": "350000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "Urban Public High Graduates", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "20000", "required_documents": "FORM_137|BARANGAY_CERT|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-15", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-20", "last_close_date": "2025-07-05", "is_active": "false", "source_slug": "cebu_city_cccsp_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=secondary", "source_urls": "https://www.cebucity.gov.ph", "dedupe_rationale": "Dedicated urban city scholarship dividing benefit values between public and private tracks."}', 'approved', '9547a84c7cf740b20f40008d524bafff53b63d4c0242d472c4008ca30b9b6f64', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:44.361866');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (26, 'Davao City STEP FA Category A', 'Davao City Government (EBSU)', 'gemini_research', '{"title": "Davao City STEP FA Category A", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "The Scholarship on Tertiary Education Program (STEP) Category A is the premier academic merit award administered by the Educational Benefit System Unit (EBSU) of Davao City. It targets high-achieving residents who attained an elite GWA of 93% or higher upon graduating Senior High School. It supplies a robust funding package of 25,000 PHP per semester to completely offset academic fees or serve as general living stipends. Financial standing is reviewed via the City Social Welfare and Development Office (CSWDO) indigency screening. Highly stable and recurring annually.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "Region XI - Davao", "eligible_cities": "Davao City", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business", "eligible_courses_specific": "High priority developmental tracks", "max_income_threshold": "250000", "min_gwa_normalized": "93", "min_age": null, "max_age": null, "priority_groups": "Elite Mindanao Scholars", "benefit_tuition": "true", "benefit_allowance_monthly": "3000", "benefit_books": "true", "benefit_total_value": "50000", "required_documents": "FORM_137|BARANGAY_CERT|BIRTH_CERT", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-10", "last_close_date": "2025-06-25", "is_active": "false", "source_slug": "davao_city_step_cat_a_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://davaocity.gov.ph/transparency/forms-and-reports/forms/ebsu-online-application", "dedupe_rationale": "Davao EBSU top merit tier requiring a 93% GWA baseline."}', 'approved', 'baee992f6bcc963ec85806b614b165c23c87a150abaf5872e82b9f648f40d485', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:35.381085');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (27, 'Davao City STEP FA Category B', 'Davao City Government (EBSU)', 'gemini_research', '{"title": "Davao City STEP FA Category B", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "Administered by Davao City''s EBSU, the STEP Category B serves as the mid-tier merit assistance channel. It requires a baseline GWA of 88% with zero grade deficiencies. It offers a flat grant of 20,000 PHP per semester (40,000 PHP annually) to help cover tuition and computing materials at any CHED-accredited college in Region XI. Candidates must verify local voter status and clear the household income check managed by the local social services office.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "Region XI - Davao", "eligible_cities": "Davao City", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All accredited college courses", "max_income_threshold": "300000", "min_gwa_normalized": "88", "min_age": null, "max_age": null, "priority_groups": "Middle Class Achievers", "benefit_tuition": "false", "benefit_allowance_monthly": "2000", "benefit_books": "true", "benefit_total_value": "40000", "required_documents": "FORM_137|BARANGAY_CERT|ITR", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-10", "last_close_date": "2025-06-25", "is_active": "false", "source_slug": "davao_city_step_cat_b_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://davaocity.gov.ph/transparency/forms-and-reports/forms/ebsu-online-application", "dedupe_rationale": "Davao EBSU mid-tier option with distinct financial caps and lower GWA bar."}', 'approved', '72ef3cb1c736d0b2971b286634827aaf8d2c931ffb54555f2fa0a63a0cf99fa5', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:45.598993');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (28, 'Davao City STEP FA Category C', 'Davao City Government (EBSU)', 'gemini_research', '{"title": "Davao City STEP FA Category C", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "STEP Category C is a broad-access financial assistance tier by Davao City EBSU focused purely on educational access for lower-income groups. It operates under a standard academic barrier of a 80% passing GWA. It delivers a support fund of 7,500 PHP per semester (15,000 PHP annually) designed to buffer costs for students attending free public SUCs or local institutes. Application processing is synchronized with the main EBSU online schedule.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": "Region XI - Davao", "eligible_cities": "Davao City", "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All standard programs", "max_income_threshold": "180000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "Low Income Urban Youth", "benefit_tuition": "false", "benefit_allowance_monthly": "1000", "benefit_books": "false", "benefit_total_value": "15000", "required_documents": "TOR|BARANGAY_CERT|4PS_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-10", "last_close_date": "2025-06-25", "is_active": "false", "source_slug": "davao_city_step_cat_c_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://davaocity.gov.ph/transparency/forms-and-reports/forms/ebsu-online-application", "dedupe_rationale": "Davao EBSU mass equity level targeted at low-income college students."}', 'approved', '7a13f1256d663f1a3af755bfade677ab210d8e755c16be7b9e64d215490db530', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:36.432123');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (29, 'Davao City Special Educational Assistance Program for Lumad', 'Davao City Government (EBSU)', 'gemini_research', '{"title": "Davao City Special Educational Assistance Program for Lumad", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "The Special Educational Assistance Program (SEAP) for Lumad is a targeted indigenous equity track run by Davao City EBSU. It is exclusively reserved for college students belonging to the recognized Indigenous Cultural Communities (IPs/Lumad) within ancestral domains of Davao City (such as the Ata, Matigsalug, Maranao, and Kagan tribes). It offers a full living subsidy of 15,000 PHP per semester alongside basic tuition assistance. The academic barrier requires a standard passing mark (75% GWA). Crucially, a formal Tribal Certification from the tribal chieftain and validation from the NCIP local office are mandatory documents.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "College|TVET", "eligible_regions": "Region XI - Davao", "eligible_cities": "Davao City", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All courses", "max_income_threshold": "200000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "Indigenous Peoples (Lumad)", "benefit_tuition": "false", "benefit_allowance_monthly": "2000", "benefit_books": "true", "benefit_total_value": "30000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-10", "last_close_date": "2025-06-25", "is_active": "false", "source_slug": "davao_city_ebsu_lumad_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://davaocity.gov.ph/transparency/forms-and-reports/forms/ebsu-online-application", "dedupe_rationale": "Targeted indigenous track under Davao LGU requiring formal Chieftain/NCIP certification."}', 'approved', 'bec411bb0c9b699d8d541113c18c5e85e1a1a8872844debdb5214a80bbcb3964', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:46.867156');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (30, 'Davao City Medical and Law Education Assistance Program', 'Davao City Government (EBSU)', 'gemini_research', '{"title": "Davao City Medical and Law Education Assistance Program", "provider": "Davao City Government (EBSU)", "source": "gemini_research", "link": "https://davaocity.gov.ph", "description": "This postgraduate track funded by the Davao City Government supports resident college graduates pursuing higher professional degrees in Doctor of Medicine (MD) or Juris Doctor (JD) within institutions located in Davao City (such as DMSF, Ateneo de Davao Law). It supplies substantial funding up to 50,000 PHP per semester to directly offset high professional tuition costs. Applicants must pass a screening panel, present an NMAT or Law School Admission test result, and possess a solid undergraduate GWA of 85%. Requires a corresponding 1-year return service within Davao City offices or city public health units for each year of grant support.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": "Region XI - Davao", "eligible_cities": "Davao City", "residency_required": "true", "eligible_school_types": "Private|Public", "eligible_courses_psced": "Medical", "eligible_courses_specific": "Doctor of Medicine|Juris Doctor", "max_income_threshold": "500000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Law and Medicine Students", "benefit_tuition": "true", "benefit_allowance_monthly": "4000", "benefit_books": "true", "benefit_total_value": "100000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL|ESSAY", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-04-15", "application_deadline": "2026-05-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-04-20", "last_close_date": "2025-06-05", "is_active": "false", "source_slug": "davao_city_medical_law_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://davaocity.gov.ph/transparency/forms-and-reports/forms/ebsu-online-application", "dedupe_rationale": "Elite postgraduate LGU track explicitly for medical and legal tracks with service rules."}', 'approved', '1a15fccae09fad54120b6c46dcdc4dbff1a002a3bcf92efdb5b3651c9e1bce3d', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:37.483223');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (31, 'Bislig City Collegiate Scholarship Program', 'Bislig City Government', 'gemini_research', '{"title": "Bislig City Collegiate Scholarship Program", "provider": "Bislig City Government", "source": "gemini_research", "link": "https://www.bislig.gov.ph", "description": "The Bislig City Scholarship Program (BCSP) is a localized LGU mandate in Caraga Region enacted to finance undergraduate degrees for local youths. Applicants must confirm 3 consecutive years of residency in Bislig City, present a clean barangay record, and maintain a GWA of 82% throughout college. It provides a flat 12,000 PHP annual educational grant to assist with registration expenses. Submissions are queued physically at the Bislig City Higher Education Desk or via their primary LGU landing page.", "provider_type": "LGU", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "Region XIII - Caraga", "eligible_cities": "Bislig", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate tracks", "max_income_threshold": "240000", "min_gwa_normalized": "82", "min_age": null, "max_age": null, "priority_groups": "Provincial Achievers", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "12000", "required_documents": "BARANGAY_CERT|TOR|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-07-20", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-10", "last_close_date": "2025-07-25", "is_active": "true", "source_slug": "bislig_city_collegiate_2026", "research_notes": "application_status=open | confidence=medium | link_quality=secondary", "source_urls": "https://www.bislig.gov.ph", "dedupe_rationale": "Localized Caraga region LGU collegiate grant omitted from standard lists."}', 'approved', '98976b67a7e477e15d3ea6085e32fe39a3e672aaf03e5cb34e73edd488863bd0', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:47.918355');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (32, 'Tabuk City College Academic Scholarship', 'Tabuk City Government', 'gemini_research', '{"title": "Tabuk City College Academic Scholarship", "provider": "Tabuk City Government", "source": "gemini_research", "link": "https://www.tabuk.gov.ph", "description": "Established under Tabuk City Ordinance No. 02 Series of 2018, this program supports tertiary students residing in Tabuk City, Kalinga Province (CAR). It targets low-income households with a maximum annual income cap of 120,000 PHP. Students must maintain a passing GWA of 75% with zero dropped classes to remain qualified. It awards a flat-rate cash assistance grant of 4,000 PHP per semester directly paid to students to handle living costs. Applications are reviewed by the Tabuk City Scholarship Committee at the City Youth and Sports Development Office.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": "CAR", "eligible_cities": "Tabuk", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All standard tracks", "max_income_threshold": "120000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "CAR Indigenous Youth", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "8000", "required_documents": "BARANGAY_CERT|TOR|ITR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-07-01", "application_deadline": "2026-08-31", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2025-07-05", "last_close_date": "2025-09-02", "is_active": "true", "source_slug": "tabuk_city_college_academic_2026", "research_notes": "application_status=opening_soon | confidence=high | link_quality=secondary", "source_urls": "https://www.tabuk.gov.ph", "dedupe_rationale": "Enacted by specific localized city ordinance in Kalinga CAR; low-income target."}', 'approved', 'e9daa7633e8f5444bcb22b3bcf55bbb597bce49b5239c39e281c407e41f826d5', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:12.213322');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (33, 'Ateneo de Manila University Financial Aid Grant', 'Ateneo de Manila University', 'gemini_research', '{"title": "Ateneo de Manila University Financial Aid Grant", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo de Manila University College Financial Aid Grant is a premium institutional program covering 100%, 75%, 50%, or 25% of tuition and laboratory fees for undergraduate students displaying high academic potential but deep financial need. Administered by the Office of Admission and Aid (OAA), applicants must submit comprehensive household assets records, utility bills, and parents'' ITRs. It includes an option for a monthly living allowance of 3,000 PHP and book allowances for absolute 100% grant recipients. Renewal requires an annual review of the family''s financial standing and keeping a minimum GWA of 78% (2.0 QPI) with no failing marks. Highly structured and opens annually in September for the subsequent academic year.", "provider_type": "Institutional", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All ADMU undergraduate courses", "max_income_threshold": "500000", "min_gwa_normalized": "78", "min_age": null, "max_age": null, "priority_groups": "High Need Achievers", "benefit_tuition": "true", "benefit_allowance_monthly": "3000", "benefit_books": "true", "benefit_total_value": "180000", "required_documents": "ITR|BARANGAY_CERT|TOR|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-09-01", "application_deadline": "2026-11-15", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2025-09-05", "last_close_date": "2025-11-20", "is_active": "true", "source_slug": "admu_financial_aid_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ateneo.edu/college/admissions/scholarships", "dedupe_rationale": "Comprehensive institutional need-based grant by ADMU with scalable tuition brackets."}', 'approved', '99e5d6db949421e2e23522d2b142281297d31ef9fdc4545f65a84f404daa2e8e', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:49.050908');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (34, 'Ateneo Freshman Merit Scholarship', 'Ateneo de Manila University', 'gemini_research', '{"title": "Ateneo Freshman Merit Scholarship", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo Freshman Merit Scholarship is awarded annually to the top 50 absolute highest-performing applicants who excel in the Ateneo College Entrance Test (ACET) nationwide. Selected automatically by the OAA without requiring a separate application form, this elite award grants 100% full tuition exemption, waives all institutional miscellaneous fees, and grants a flat book allowance of 10,000 PHP per year. Academic retention is strictly audited, requiring a minimum QPI of 3.0 (90% normalized GWA) and active leadership participation within approved campus organizations.", "provider_type": "Institutional", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All ADMU undergraduate programs", "max_income_threshold": null, "min_gwa_normalized": "90", "min_age": null, "max_age": null, "priority_groups": "Top ACET Performers", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "160000", "required_documents": "TOR|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-09-01", "application_deadline": "2026-11-15", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2025-09-05", "last_close_date": "2025-11-20", "is_active": "true", "source_slug": "ateneo_freshman_merit_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ateneo.edu/college/admissions/scholarships", "dedupe_rationale": "Elite merit award for top 50 ACET examinees with elevated GWA standards."}', 'approved', '13a1cea27cd86311327d10710ba1521366933c56818c013c833f2487fc3ea8b6', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:38.484021');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (35, 'Ateneo Directors List Scholarship', 'Ateneo de Manila University', 'gemini_research', '{"title": "Ateneo Directors List Scholarship", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Director''s List Scholarship is extended by the Ateneo OAA to the next tier of top-ranking ACET examinees (top 51-150 nationwide). It grants an annual flat-rate educational stipend of 100,000 PHP directly credited to the recipient''s tuition or disbursed as cash allowance across semesters. No financial indicators are used for selection. Recipients must preserve a minimum QPI of 2.50 (83% normalized GWA) and avoid any academic or disciplinary probationary states.", "provider_type": "Institutional", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate majors", "max_income_threshold": null, "min_gwa_normalized": "83", "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "100000", "required_documents": "TOR", "has_qualifying_exam": "true", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-09-01", "application_deadline": "2026-11-15", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2025-09-05", "last_close_date": "2025-11-20", "is_active": "true", "source_slug": "ateneo_directors_list_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ateneo.edu/college/admissions/scholarships", "dedupe_rationale": "Automatic merit track for top 150 ACET scorers providing a flat 100k annual stipend."}', 'approved', 'd164b5bef275467c9a948bd8c42905f99e1438de4c2b23597ba81d528c2312d8', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:50.980000');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (36, 'Ateneo Magis Scholarship', 'Ateneo de Manila University', 'gemini_research', '{"title": "Ateneo Magis Scholarship", "provider": "Ateneo de Manila University", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo Magis Scholarship is a specialized institutional track specifically reserved for high-achieving graduates of public high schools nationwide who showcase outstanding leadership profiles and financial need. It provides 100% tuition and fee coverage, an allocated monthly living stipend of 4,000 PHP, full book allowances, and on-campus dormitory accommodation at the Cervini or Eliazo Halls if the student is from the provinces. Application requires public school principal endorsement, ACET certification, and thorough interview evaluations.", "provider_type": "Institutional", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate paths", "max_income_threshold": "250000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Public High School Grads", "benefit_tuition": "true", "benefit_allowance_monthly": "4000", "benefit_books": "true", "benefit_total_value": "220000", "required_documents": "ITR|BARANGAY_CERT|FORM_137|ESSAY", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-09-01", "application_deadline": "2026-11-15", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2025-09-05", "last_close_date": "2025-11-20", "is_active": "true", "source_slug": "ateneo_magis_scholarship_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ateneo.edu/college/admissions/scholarships", "dedupe_rationale": "Targeted public school equity track including fully funded dorm provisions."}', 'approved', 'e28ad7ee27a59831a2a564260eaf2077a81d8b9bea55dc938bf76b9d89e3435e', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:39.551789');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (37, 'Ateneo Law School Financial Aid Program', 'Ateneo Law School', 'gemini_research', '{"title": "Ateneo Law School Financial Aid Program", "provider": "Ateneo Law School", "source": "gemini_research", "link": "https://www.ateneo.edu", "description": "The Ateneo Law School Financial Aid Program provides tuition assistance grants ranging from 25% to 100% for students enrolled in the Juris Doctor (JD) program at the Rockwell campus. Managed by the ALS Scholarship Committee, awards are heavily based on exceptional undergraduate academic honors, high scores in the Philippine Law School Admission test, and certified financial need. Maintenance requires keeping a minimum yearly weighted average of 82 (passing) and fulfilling service hours within the ALS legal aid clinics or administrative units.", "provider_type": "Institutional", "scholarship_type": "Merit-and-Need", "eligible_levels": "Graduate", "eligible_regions": "NCR", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "Business", "eligible_courses_specific": "Juris Doctor (JD)", "max_income_threshold": "600000", "min_gwa_normalized": "82", "min_age": null, "max_age": null, "priority_groups": "Aspiring Lawyers", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "120000", "required_documents": "TOR|ITR|GOOD_MORAL|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-04-01", "application_deadline": "2026-05-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-04-10", "last_close_date": "2025-06-02", "is_active": "false", "source_slug": "ateneo_law_financial_aid_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.ateneo.edu/als/admissions/scholarships", "dedupe_rationale": "Postgraduate professional law track grant distinct from undergraduate lines."}', 'approved', 'a12dd8947b151807317759cbd4f8ff0b8e6869b201aded3cfa149b5cbe2fd95c', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:51.950261');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (38, 'DLSU St La Salle Financial Assistance Grant', 'De La Salle University', 'gemini_research', '{"title": "DLSU St La Salle Financial Assistance Grant", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The St. La Salle Financial Assistance Grant is De La Salle University''s primary need-based equity tool for undergraduate college students. Administered by the Oasis-Scholarships and Financial Assistance Hub (OASFAH), it provides full or partial tuition and fee waivers. Eligible applicants must prove a combined annual family income below 700,000 PHP and submit standard academic records showing a GWA of 85% or above with no failures. It includes a monthly allowance of 3,500 PHP for absolute 100% grantees. Portals open semestrally for current students and annually for incoming freshmen.", "provider_type": "Institutional", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All undergraduate degree courses", "max_income_threshold": "700000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "High Financial Need", "benefit_tuition": "true", "benefit_allowance_monthly": "3500", "benefit_books": "true", "benefit_total_value": "180000", "required_documents": "ITR|BARANGAY_CERT|TOR|BIRTH_CERT", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2026-01-10", "last_close_date": "2026-02-20", "is_active": "true", "source_slug": "dlsu_st_la_salle_grant_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://www.dlsu.edu.ph/scholarships/st-la-salle-financial-assistance-grant", "dedupe_rationale": "DLSU baseline institutional need-based grant with distinct token funding framework."}', 'approved', '5479c4ed0a244c88084c6a41ccb9628ae82e0fc8971020a255e9c1eee82a48ca', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:40.607908');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (39, 'DLSU Star Scholars Program', 'De La Salle University', 'gemini_research', '{"title": "DLSU Star Scholars Program", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The DLSU Star Scholars Program is an elite academic recruitment track that signs the absolute top scorers of the DLSU College Admission Test (DCAT) nationwide. It waives 100% of all tuition, laboratory, and miscellaneous fees for the entire duration of the program, supplies a monthly cash living stipend of 8,000 PHP, a specialized laptop computer allowance upon entry, and guaranteed faculty mentorship for undergraduate research. Academic retention mandates a strict cumulative GWA of 3.0 out of 4.0 (90% normalized) with zero dropped courses.", "provider_type": "Institutional", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All undergraduate offerings", "max_income_threshold": null, "min_gwa_normalized": "90", "min_age": null, "max_age": null, "priority_groups": "Elite DCAT Performers", "benefit_tuition": "true", "benefit_allowance_monthly": "8000", "benefit_books": "true", "benefit_total_value": "250000", "required_documents": "TOR|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-15", "last_close_date": "2025-07-05", "is_active": "false", "source_slug": "dlsu_star_scholars_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.dlsu.edu.ph/scholarships/the-star-scholars-program", "dedupe_rationale": "Automatic high-value merit recruitment model with 8,000 PHP monthly stipends."}', 'approved', 'c3690ff97488f59d4ea154aa74166907ae6122f7c8c5935e734caf0f0fcde661', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:53.047615');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (40, 'DLSU Vaugirard Scholarship Program', 'De La Salle University', 'gemini_research', '{"title": "DLSU Vaugirard Scholarship Program", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The Vaugirard Scholarship Program is exclusively targeted at exceptional graduates of Philippine public high schools who emerged as the top academic scorers in the DCAT. It completely bridges equity and excellence by presenting 100% free tuition and institutional fee waivers, a monthly allowance of 4,000 PHP, and specialized academic counseling. Eligible applicants must be formally certified by their public high school principals and pass the OASFAH panel verification.", "provider_type": "Institutional", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All undergraduate degrees", "max_income_threshold": "300000", "min_gwa_normalized": "88", "min_age": null, "max_age": null, "priority_groups": "Public High School Grads", "benefit_tuition": "true", "benefit_allowance_monthly": "4000", "benefit_books": "true", "benefit_total_value": "190000", "required_documents": "FORM_137|BARANGAY_CERT|BIRTH_CERT", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-15", "last_close_date": "2025-07-05", "is_active": "false", "source_slug": "dlsu_vaugirard_scholarship_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.dlsu.edu.ph/scholarships/vaugirard-scholarship-program", "dedupe_rationale": "DLSU public high school exclusive merit-need program omitted in Round 1."}', 'approved', '06741bb33292c907733633d508d1c29c4b319e3097ba4cd8aa0274afb945a930', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:41.670450');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (41, 'DLSU Archer Achievers Scholarship', 'De La Salle University', 'gemini_research', '{"title": "DLSU Archer Achievers Scholarship", "provider": "De La Salle University", "source": "gemini_research", "link": "https://www.dlsu.edu.ph", "description": "The Archer Achievers Scholarship is automatically extended by DLSU to students who graduate as the absolute valedictorians and salutatorians of top-performing high schools accredited by the university. It automatically confers a 100% tuition waiver for the student''s selected undergraduate curriculum. No separate financial files are required, but students must preserve a high semestral GWA of 2.50 out of 4.0 (83% normalized) to sustain the benefit across academic years.", "provider_type": "Institutional", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All undergraduate tracks", "max_income_threshold": null, "min_gwa_normalized": "83", "min_age": null, "max_age": null, "priority_groups": "High School Valedictorians", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "140000", "required_documents": "TOR|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-15", "last_close_date": "2025-07-05", "is_active": "false", "source_slug": "dlsu_archer_achievers_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.dlsu.edu.ph/scholarships/archer-achievers", "dedupe_rationale": "Automatic merit track recognizing top high school graduates with zero service rules."}', 'approved', '7877737cad109bbdc8707ee85754c9353abdf8d7aa3d3af0404573bcb6f4ddfc', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:54.139897');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (42, 'UST San Lorenzo Ruiz Student Assistance Scholarship', 'University of Santo Tomas', 'gemini_research', '{"title": "UST San Lorenzo Ruiz Student Assistance Scholarship", "provider": "University of Santo Tomas", "source": "gemini_research", "link": "https://manila.ust.edu.ph", "description": "The San Lorenzo Ruiz Student Assistance Scholarship is the University of Santo Tomas'' premier internal working scholarship program managed by the Office for Student Affairs (OSA). It caters to regular UST college students who possess financial need and are willing to render 20 to 30 hours of service per week within university offices, laboratories, or libraries. It presents a 100% full waiver of tuition and miscellaneous fees, plus a basic hourly stipend. Applicants must maintain a minimum GWA of 82% (2.25) with zero failures. Highly structured and recurring every semester.", "provider_type": "Institutional", "scholarship_type": "Affiliation", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All UST college programs", "max_income_threshold": "250000", "min_gwa_normalized": "82", "min_age": null, "max_age": null, "priority_groups": "Student Assistants", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "60000", "required_documents": "TOR|BARANGAY_CERT|GOOD_MORAL|ITR", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-15", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "semester", "last_open_date": "2025-05-20", "last_close_date": "2025-07-02", "is_active": "false", "source_slug": "ust_san_lorenzo_ruiz_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://manila.ust.edu.ph/osawebapp/osainfo-scholarshipoffered", "dedupe_rationale": "UST internal working student track requiring office hours in exchange for tuition."}', 'approved', '51eb1cd10dc7547b7afc6145dd6f6d2944cb743bb6507a0af5bc509ee3e0cd7f', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:42.713510');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (43, 'UST San Martin de Porres Equity Scholarship', 'University of Santo Tomas', 'gemini_research', '{"title": "UST San Martin de Porres Equity Scholarship", "provider": "University of Santo Tomas", "source": "gemini_research", "link": "https://manila.ust.edu.ph", "description": "The San Martin de Porres Scholarship is UST''s foundational equity framework designed for financially marginalized students. Split into internal and external funds, it offers partial to full tuition waivers based on audited household documentation. Eligible candidates must have a GWA of 85% or better and a household annual income below 300,000 PHP. Submissions are processed online through the UST OSA web portal at the start of each academic year.", "provider_type": "Institutional", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All undergraduate degrees", "max_income_threshold": "300000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Low Income Catholics", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "45000", "required_documents": "ITR|BARANGAY_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-10", "application_deadline": "2026-07-25", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-15", "last_close_date": "2025-08-02", "is_active": "true", "source_slug": "ust_san_martin_de_porres_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://manila.ust.edu.ph/osawebapp/osainfo-scholarshipoffered", "dedupe_rationale": "UST central need-based equity option with explicit income screening."}', 'approved', '190e8dc94a0a647f70961f7b51a94afab010518665ebdac477bd95866047bc84', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:54.974394');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (44, 'UST Santo Tomas Academic Scholarship', 'University of Santo Tomas', 'gemini_research', '{"title": "UST Santo Tomas Academic Scholarship", "provider": "University of Santo Tomas", "source": "gemini_research", "link": "https://manila.ust.edu.ph", "description": "The Santo Tomas Academic Scholarship is awarded to incoming freshmen who graduated as Valedictorians (100% tuition coverage) or Salutatorians (50% tuition coverage) of their high school classes. Validated through the UST OSA, recipients must pass the UST Entrance Test (USTET) and secure regular status enrollment. Retention mandates keeping a clean disciplinary record and a high semestral GWA of 1.75 or better (88% normalized). No financial background checks are applied.", "provider_type": "Institutional", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "NCR", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Arts", "eligible_courses_specific": "All university programs", "max_income_threshold": null, "min_gwa_normalized": "88", "min_age": null, "max_age": null, "priority_groups": "High School Honor Grads", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "100000", "required_documents": "FORM_137|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-15", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-20", "last_close_date": "2025-07-02", "is_active": "false", "source_slug": "ust_santo_tomas_academic_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://manila.ust.edu.ph/osawebapp/osainfo-scholarshipoffered", "dedupe_rationale": "UST baseline automatic merit track for top high school grads."}', 'approved', 'b3656457333aa3d54f5f2082db570382d40ace04d0db83eb2cfaf502feaf0bf4', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:43.699982');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (45, 'Mindanao State University SASE Academic Scholarship', 'Mindanao State University System', 'gemini_research', '{"title": "Mindanao State University SASE Academic Scholarship", "provider": "Mindanao State University System", "source": "gemini_research", "link": "https://www.msumain.edu.ph", "description": "The Mindanao State University System Academic Scholarship is awarded to incoming undergraduate freshmen who score in the top 5% of the annual MSU System Admission and Scholarship Examination (SASE) across Mindanao. Administered by the MSU Admissions Office, it offers full institutional tuition waivers, free dormitory lodging within the university campus, and a semestral book allowance. Grantees must maintain a GWA of 2.0 (85%) per semester to sustain benefits. This program forms a vital pipeline for students in conflict-affected regions.", "provider_type": "Institutional", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": "BARMM|Region IX - Zamboanga Peninsula|Region X - Northern Mindanao|Region XI - Davao|Region XII - Soccsksargen|Region XIII - Caraga", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate tracks", "max_income_threshold": null, "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Mindanao Youth", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "20000", "required_documents": "TOR|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-03-01", "application_deadline": "2026-05-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-03-10", "last_close_date": "2025-05-20", "is_active": "false", "source_slug": "msu_sase_academic_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=secondary", "source_urls": "https://www.msumain.edu.ph", "dedupe_rationale": "MSU system-wide elite SASE exam award offering full tuition and dorm allocations."}', 'approved', '7a976bd7917478a76aac67444b5380832aa3e12853672c979e33d87ac10c11ba', '2026-06-30 12:29:13.395770', '2026-06-30 12:30:56.084619');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (46, 'NCIP Educational Assistance Program Degree Track', 'National Commission on Indigenous Peoples', 'gemini_research', '{"title": "NCIP Educational Assistance Program Degree Track", "provider": "National Commission on Indigenous Peoples", "source": "gemini_research", "link": "https://ncip.gov.ph", "description": "The National Commission on Indigenous Peoples Educational Assistance Program (NCIP-EAP) Degree Track is a mandated sector-specific government program designed under NCIP Administrative Order No. 5 Series of 2012 and upgraded via AO No. 6 Series of 2023. It aims to extend tertiary educational access to recognized members of Indigenous Cultural Communities (ICCs/IPs) nationwide. Eligible candidates must secure a Certificate of Confirmation (COCO) from the NCIP Provincial/Regional Office confirming tribal identity. The academic bar requires a general passing GWA of 75% with zero dropped modules. It supplies an annual educational subsidy of 10,000 PHP to 20,000 PHP disbursed through regional offices to offset books, uniform, and field research. Highly recurring cycle synchronized with the fiscal year.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate pathways", "max_income_threshold": "200000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "Indigenous Peoples (IP)", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "20000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-08-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-10", "last_close_date": "2025-08-20", "is_active": "true", "source_slug": "ncip_eap_degree_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://ncip.gov.ph|https://eais.ncip.gov.ph", "dedupe_rationale": "Mandated national sector program for IPs requiring a Certificate of Confirmation."}', 'approved', '6b673e1321dd9e2b746b6b254f4e28d0b0a151cbae227429560e1bbae7408842', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:14.541815');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (47, 'NCIP Merit Based Scholarship Program', 'National Commission on Indigenous Peoples', 'gemini_research', '{"title": "NCIP Merit Based Scholarship Program", "provider": "National Commission on Indigenous Peoples", "source": "gemini_research", "link": "https://ncip.gov.ph", "description": "The NCIP Merit-Based Scholarship Program (NCIP-MBS) is a high-tier academic track within the commission reserved for outstanding IP students pursuing competitive national degrees (specifically STEM, Engineering, or Agriculture). Unlike the EAP, the MBS enforces a strict GWA requirement of 85% or higher and puts applicants through a competitive regional examination. It grants an expanded benefit package of 30,000 PHP per year to handle tuition balances or modern learning devices. Administered via the NCIP Bureau of Socio-Economic Literacy and Culture.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|Agriculture", "eligible_courses_specific": "STEM and Agriculture tracks", "max_income_threshold": "300000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "IP Academic Achievers", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "30000", "required_documents": "BARANGAY_CERT|TOR|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-01", "application_deadline": "2026-08-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-10", "last_close_date": "2025-08-20", "is_active": "true", "source_slug": "ncip_mbs_merit_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://ncip.gov.ph|https://eais.ncip.gov.ph", "dedupe_rationale": "Elite competitive track within NCIP with strict 85% GWA and entry testing."}', 'approved', 'e5a3468dc58214d83d8c06c770ba23053dd2798ebbfe57051771be654288a1f9', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:16.690490');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (48, 'DOH Medical Scholarship and Return Service Program', 'Department of Health', 'gemini_research', '{"title": "DOH Medical Scholarship and Return Service Program", "provider": "Department of Health", "source": "gemini_research", "link": "https://doh.gov.ph", "description": "The DOH Medical Scholarship and Return Service (MSRS) Program is a major sector-specific government intervention operating under the ''Doktor Para sa Bayan'' Act (RA 11509) in partnership with CHED. It funds full medical education (Doctor of Medicine) for qualified Filipino students across certified state and partner private universities. It covers 100% of tuition, laboratory fees, provides a high monthly living allowance of 15,000 PHP, a specialized book/equipment allowance of 20,000 PHP per semester, and basic board exam review subsidies. Eligible applicants must hold a Bachelor''s degree with a solid GWA, pass the medical school entrance and NMAT, and prioritize low-income roots or origin from underserved rural towns. Return service requires serving as a public health officer in a government hospital or rural health unit (RHU) for 1 year for every year of scholarship.", "provider_type": "Government", "scholarship_type": "Merit-and-Need", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "Medical", "eligible_courses_specific": "Doctor of Medicine (MD)", "max_income_threshold": "600000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Rural Public Health", "benefit_tuition": "true", "benefit_allowance_monthly": "15000", "benefit_books": "true", "benefit_total_value": "250000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL|ITR|ESSAY", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-05-01", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-15", "last_close_date": "2025-07-05", "is_active": "false", "source_slug": "doh_msrs_doctor_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://doh.gov.ph|https://ched.gov.ph", "dedupe_rationale": "National statutory medical track under RA 11509 with comprehensive returns."}', 'approved', 'ad8af4e5d4e5af8416cecfc4c83ab2b9ab44b2bba9923ae242f0ec3560c904f2', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:17.795780');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (49, 'Department of Agriculture ACEF GIAHEP SUC Track', 'Department of Agriculture', 'gemini_research', '{"title": "Department of Agriculture ACEF GIAHEP SUC Track", "provider": "Department of Agriculture", "source": "gemini_research", "link": "https://da.gov.ph", "description": "The Agricultural Competitiveness Enhancement Fund Grants-in-Aid for Higher Education Program (ACEF-GIAHEP) SUC Track is a targeted government financial aid tool managed by the Department of Agriculture in compliance with RA 10848. It extends funding to children of registered small farmers, fisherfolk, and agrarian reform beneficiaries who are enrolled in State Universities and Colleges. It covers educational assistance for specific courses in agriculture, agribusiness, agricultural engineering, and fisheries science. Requires a minimum GWA of 75% and presentation of the parent''s RSBSA (Registry System for Basic Sectors in Agriculture) certificate. Disburses a flat rate of 15,000 PHP per semester.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public", "eligible_courses_psced": "Agriculture|Engineering", "eligible_courses_specific": "Agriculture and Agribusiness", "max_income_threshold": "200000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "Farmers and Fishers Dependents", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "30000", "required_documents": "BARANGAY_CERT|TOR|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-15", "application_deadline": "2026-08-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-06-20", "last_close_date": "2025-08-25", "is_active": "true", "source_slug": "da_acef_giahep_suc_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://da.gov.ph|https://ched.gov.ph", "dedupe_rationale": "Statutory DA fund under RA 10848 requiring RSBSA registration profiles."}', 'approved', 'f8db6484aba09bf384c25d93d8e5e9b891fa3f037c24def1d9dd361816df5658', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:19.632125');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (50, 'OWWA Educational Livelihood Assistance Program College Track', 'Overseas Workers Welfare Administration', 'gemini_research', '{"title": "OWWA Educational Livelihood Assistance Program College Track", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://owwa.gov.ph", "description": "The OWWA Educational Livelihood Assistance Program (ELAP) College Track is an allocation reserved for the children or dependents of active or deceased Overseas Filipino Workers (OFWs) who faced sudden distress, repatriation, or death while serving abroad. Distinct from the EDSP/ODSP merit lines, ELAP operates primarily as a livelihood-linked equity framework. It guarantees an educational subsidy of 10,000 PHP per year for the designated student dependent enrolled in any undergraduate college or technical track. Academic evaluation relies on basic passing marks (75% GWA) with no explicit ranking requirements. Online processing must clear the OWWA Regional Welfare Offices.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College|TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All accredited lines", "max_income_threshold": "250000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "Distressed OFW Dependents", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "OFW_DOCS|BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-05", "last_close_date": "2025-07-20", "is_active": "true", "source_slug": "owwa_elap_college_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://owwa.gov.ph|https://ro1.owwa.gov.ph", "dedupe_rationale": "OWWA humanitarian track for distressed/repatriated OFW children; low barrier."}', 'approved', '9ccea555637900a7f73841c4a8f85c0c6dc859817a04e77a31e66fd0d20fc29d', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:44.747956');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (51, 'AFPEBSO DND CHED PASUC Scholarship', 'Armed Forces of the Philippines (AFPEBSO)', 'gemini_research', '{"title": "AFPEBSO DND CHED PASUC Scholarship", "provider": "Armed Forces of the Philippines (AFPEBSO)", "source": "gemini_research", "link": "https://afpeebso.org", "description": "The AFPEBSO DND-CHED-PASUC Scholarship is a special sector-specific inter-agency government program managed by the Armed Forces of the Philippines Educational Benefit System Office. It extends 100% tuition and fee exemptions at any public State University or College (SUC) for the legitimate children and direct dependents of active-duty, retired, or deceased AFP military personnel. Academic requirements mandate a baseline GWA of 80% (2.5) with zero failures. Financial constraints are secondary to the parent''s military service record. Portals accept applications annually from May to July.", "provider_type": "Government", "scholarship_type": "Affiliation", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "true", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All SUC undergraduate paths", "max_income_threshold": null, "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "Military Dependents", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "15000", "required_documents": "BARANGAY_CERT|TOR|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-10", "last_close_date": "2025-07-20", "is_active": "true", "source_slug": "afpebso_dnd_ched_pasuc_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://www.afp.mil.ph|https://ched.gov.ph", "dedupe_rationale": "AFP sector program in partnership with CHED for SUC placements."}', 'approved', '1fac5d3a42b6f56b9cd5290516c9ea744e640280900d1e056934a1871c4a3909', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:21.163639');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (52, 'AFPSLAI Educational Grant Program', 'Armed Forces of the Philippines (AFPSLAI)', 'gemini_research', '{"title": "AFPSLAI Educational Grant Program", "provider": "Armed Forces of the Philippines (AFPSLAI)", "source": "gemini_research", "link": "https://www.afpslai.com.ph", "description": "The AFPSLAI Educational Grant Program (EGP) is an affiliation-based financial assistance platform run by the Armed Forces and Police Savings and Loan Association, Inc. It caters to the children and dependents of active or retired military personnel, PNP officers, and uniformed service members who are registered members of AFPSLAI. It delivers a comprehensive flat financial subsidy of 25,000 PHP per semester (50,000 PHP annually) directly to the student to offset undergraduate expenses. Candidates must post a minimum GWA of 85% and possess a clean disciplinary record. Submissions clear through AFPSLAI regional branch hubs.", "provider_type": "Private", "scholarship_type": "Affiliation", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergraduate tracks", "max_income_threshold": "500000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Uniformed Service Dependents", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "50000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-15", "application_deadline": "2026-07-10", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-20", "last_close_date": "2025-07-15", "is_active": "true", "source_slug": "afpslai_egp_grant_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://www.afpslai.com.ph", "dedupe_rationale": "Uniformed service savings-association dependent award; high financial stability."}', 'approved', '2d13eae2aa27892dcee03c7b4e869c7f89b42c13119201a7c14136921db5d517', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:58.348825');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (53, 'DSWD AICS Educational Assistance', 'Department of Social Welfare and Development', 'gemini_research', '{"title": "DSWD AICS Educational Assistance", "provider": "Department of Social Welfare and Development", "source": "gemini_research", "link": "https://www.dswd.gov.ph", "description": "The DSWD Assistance to Individuals in Crisis Situation (AICS) Educational Assistance is a specialized cash intervention program designed for students experiencing extreme economic shock, sudden death of a breadwinner, abandonment, or loss of livelihood due to national disasters. Operated directly through the DSWD Crisis Intervention Units (CIU) or Social Welfare Operations Hubs, it provides a one-time cash grant ranging from 1,000 PHP (Elementary), 2,000 PHP (High School), 3,000 PHP (Senior High), to 4,000 PHP (College/TVET) per semester. Selection ignores GWA rankings but strictly requires an active Case Study Report or Certificate of Indigency from the local MSWDO.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "Grade 11|Grade 12|College|TVET|Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All educational lines", "max_income_threshold": "150000", "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": "Students in Crisis", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "4000", "required_documents": "BARANGAY_CERT|BIRTH_CERT|4PS_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-01-01", "application_deadline": "2026-12-31", "academic_year_target": "2026-2027", "cycle_type": "rolling", "last_open_date": "2025-01-05", "last_close_date": "2025-12-28", "is_active": "true", "source_slug": "dswd_aics_educational_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://www.dswd.gov.ph", "dedupe_rationale": "One-time crisis-driven humanitarian cash grant with rolling application schedules."}', 'approved', 'f367035dae8c99de0abdb2705231d07c4e7871305f1664dfc5a66fab431a8dba', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:22.961992');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (54, 'Megaworld Foundation Scholarship Program', 'Megaworld Foundation', 'gemini_research', '{"title": "Megaworld Foundation Scholarship Program", "provider": "Megaworld Foundation", "source": "gemini_research", "link": "https://www.megaworldfoundation.com", "description": "The Megaworld Foundation Scholarship Program is a high-impact mid-market corporate financial assistance framework that funds full undergraduate degrees for underprivileged youths across partner universities in Metro Manila and key regions. It covers 100% of actual tuition and institutional fees, and issues a monthly stipend of 2,500 PHP. Eligible candidates must maintain a GWA of 85% (2.0) with zero dropped subjects and possess a total combined annual household income not exceeding 400,000 PHP. Applications are routed through the Megaworld online portal, requiring an essay on community development and an executive interview.", "provider_type": "Private", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR|Region III - Central Luzon|Region IV-A - Calabarzon|Region VI - Western Visayas|Region VII - Central Visayas", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Business|Arts", "eligible_courses_specific": "Engineering Architecture and Tech", "max_income_threshold": "400000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Underprivileged Youth", "benefit_tuition": "true", "benefit_allowance_monthly": "2500", "benefit_books": "false", "benefit_total_value": "120000", "required_documents": "ITR|BARANGAY_CERT|TOR|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-05-15", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-20", "last_close_date": "2025-07-22", "is_active": "true", "source_slug": "megaworld_foundation_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://www.megaworldfoundation.com", "dedupe_rationale": "Corporate foundation program targeting urban engineering and tech tracks."}', 'approved', 'a68a9d63f6e17c135201f20c13d8a091b592f6634d2cf28657c11b7a0b724b32', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:37.031507');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (55, 'Security Bank Foundation State Universities Scholarship', 'Security Bank Foundation', 'gemini_research', '{"title": "Security Bank Foundation State Universities Scholarship", "provider": "Security Bank Foundation", "source": "gemini_research", "link": "https://www.securitybank.com", "description": "The Security Bank Foundation ''Scholars for Better Communities'' State Universities Scholarship provides full educational stipends to low-income student leaders enrolled in partner public SUCs (such as UP Diliman, MSU, or regional centers). It provides a high flat allowance of 50,000 PHP per year to cover learning modules, laptops, and transit costs. Applicants must present a GWA of 85% or higher, zero failed subjects, and clear an interview with Security Bank HR personnel. No return service is mandated, but scholars receive priority onboarding for corporate internships.", "provider_type": "Private", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Business|IT", "eligible_courses_specific": "Finance Accounting and IT courses", "max_income_threshold": "350000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Low Income Achievers", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "50000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL|ITR", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-04-15", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-04-20", "last_close_date": "2025-06-25", "is_active": "false", "source_slug": "security_bank_snb_suc_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.securitybank.com/foundation/scholars-for-better-communities", "dedupe_rationale": "Mid-market financial corporate grant supporting public SUC courses."}', 'approved', '26754cd9d7e4f7774caf78c79c91a6167d4a294e8bac5536e26e8251346281a2', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:23.839771');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (56, 'Security Bank Foundation Agency Personnel Scholarship', 'Security Bank Foundation', 'gemini_research', '{"title": "Security Bank Foundation Agency Personnel Scholarship", "provider": "Security Bank Foundation", "source": "gemini_research", "link": "https://www.securitybank.com", "description": "This unique corporate affiliation-based scholarship track is exclusively reserved for the legitimate children and dependents of Security Bank''s third-party agency personnel (including dedicated security guards, janitorial workers, and building maintenance staff). It extends a direct annual educational allowance of 30,000 PHP for undergraduate studies to ease school costs for working-class contractor families. Requires a minimum passing GWA of 80% and validation of the parent''s active employment contract with the bank''s agency partner.", "provider_type": "Private", "scholarship_type": "Affiliation", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All undergrad programs", "max_income_threshold": "250000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "Agency Worker Children", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": "30000", "required_documents": "BIRTH_CERT|TOR|BARANGAY_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-04-15", "application_deadline": "2026-06-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-04-20", "last_close_date": "2025-06-25", "is_active": "false", "source_slug": "security_bank_agency_dep_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.securitybank.com/foundation/scholars-for-better-communities", "dedupe_rationale": "Affiliation corporate program targeting bank contractor/agency staff children."}', 'approved', 'c47bf497ba2a826a7d8c8a36a5d3328eae8d0b8e149a5e81b4587522da8786bf', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:45.785115');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (57, 'Caritas Manila YSLEP Scholarship Program', 'Caritas Manila', 'gemini_research', '{"title": "Caritas Manila YSLEP Scholarship Program", "provider": "Caritas Manila", "source": "gemini_research", "link": "https://www.caritasmanila.org.ph", "description": "The Youth Servant Leadership and Education Program (YSLEP) is Caritas Manila''s primary church-backed financial aid and leadership development initiative. Operating across Catholic dioceses nationwide, it supports poor and marginalized college and TVET students. It pays partial tuition up to 25,000 PHP per year and distributes a modest monthly allowance. Distinctively, selection prioritizes urban-slum families, 4Ps members, and indigenous youth. Recipients must join monthly leadership seminars, church volunteer hours, and community organizing programs. Academic criteria require a baseline 80% GWA with zero failures.", "provider_type": "Private", "scholarship_type": "Need", "eligible_levels": "College|TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All approved courses", "max_income_threshold": "180000", "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "4Ps|Urban Slum Youth", "benefit_tuition": "true", "benefit_allowance_monthly": "1000", "benefit_books": "true", "benefit_total_value": "35000", "required_documents": "BARANGAY_CERT|4PS_CERT|TOR|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2026-05-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-10", "last_close_date": "2025-07-20", "is_active": "true", "source_slug": "caritas_manila_yslep_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://www.caritasmanila.org.ph|https://www.caritas.org", "dedupe_rationale": "Church-backed development grant integrating civic volunteer hours."}', 'approved', 'abbfd73a3ec90777d10142b12204027e003f9fe791f83ee9736fc91ef3d4b945', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:24.735314');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (58, 'TESDA Training for Work Scholarship Program', 'Technical Education and Skills Development Authority', 'gemini_research', '{"title": "TESDA Training for Work Scholarship Program", "provider": "Technical Education and Skills Development Authority", "source": "gemini_research", "link": "https://tesda.gov.ph", "description": "The TESDA Training for Work Scholarship Program (TWSP) is a major sector-specific national TVET pipeline designed to fulfill critical skills requirements in high-growth industries such as IT-BPO, electronics, tourism, and metal engineering. Fully funded by the national government, it covers 100% of the training and instructional fees for short-term tech-voc modules (ranging from 1 to 6 months). Additionally, it distributes a daily training allowance of 160 PHP and provides full coverage for the National Assessment fee. Open to all Filipinos aged 18 and above with a high school diploma. Applications are processed directly through TESDA Regional Offices or accredited tech-voc institutions.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "IT|Engineering", "eligible_courses_specific": "Short term tech voc modules", "max_income_threshold": null, "min_gwa_normalized": "75", "min_age": "18", "max_age": null, "priority_groups": "Unemployed Youth", "benefit_tuition": "true", "benefit_allowance_monthly": "3500", "benefit_books": "false", "benefit_total_value": "15000", "required_documents": "BIRTH_CERT|FORM_137|BARANGAY_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-01-01", "application_deadline": "2026-12-31", "academic_year_target": "2026-2027", "cycle_type": "rolling", "last_open_date": "2025-01-05", "last_close_date": "2025-12-28", "is_active": "true", "source_slug": "tesda_twsp_tvet_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://tesda.gov.ph", "dedupe_rationale": "National short-term TVET sector fund with daily stipends; separate from baseline PESFA."}', 'approved', 'a5379daf42e297c694403206214d7ec63c4c9dce4a8b2d2ad01fdf72825159ef', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:46.766836');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (59, 'TESDA Special Training for Employment Program', 'Technical Education and Skills Development Authority', 'gemini_research', '{"title": "TESDA Special Training for Employment Program", "provider": "Technical Education and Skills Development Authority", "source": "gemini_research", "link": "https://tesda.gov.ph", "description": "The Special Training for Employment Program (STEP) is a community-focused TESDA scholarship path targeted at grass-roots livelihood creation and entrepreneurial development. It offers free technical training in community-based skills (e.g., electrical repair, baking, welding, masonry). Critically, it delivers an allocated daily allowance of 160 PHP, a clothing allowance of 500 PHP, and provides a comprehensive high-value Entrepreneurship Tool Kit (e.g., actual baking or welding kits) upon module completion to assist immediate employment. No GWA restrictions are applied.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "Engineering", "eligible_courses_specific": "Community livelihood short courses", "max_income_threshold": null, "min_gwa_normalized": "75", "min_age": "15", "max_age": null, "priority_groups": "Grassroots Poor", "benefit_tuition": "true", "benefit_allowance_monthly": "3500", "benefit_books": "false", "benefit_total_value": "22000", "required_documents": "BIRTH_CERT|BARANGAY_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-01-01", "application_deadline": "2026-12-31", "academic_year_target": "2026-2027", "cycle_type": "rolling", "last_open_date": "2025-01-05", "last_close_date": "2025-12-28", "is_active": "true", "source_slug": "tesda_step_tvet_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://tesda.gov.ph", "dedupe_rationale": "Community TVET program providing physical entrepreneur tool kits upon graduation."}', 'approved', '2c99dda0510102ee14854b8d2bfffc156221982898f0a9e4bec54cda959a0a48', '2026-06-30 12:29:13.395770', '2026-07-26 09:42:47.746504');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (60, 'Erasmus Mundus Joint Masters Scholarship', 'European Union', 'gemini_research', '{"title": "Erasmus Mundus Joint Masters Scholarship", "provider": "European Union", "source": "gemini_research", "link": "https://erasmus-plus.ec.europa.eu", "description": "The Erasmus Mundus Joint Masters Scholarship is a highly prestigious international bilateral program funded by the European Union for outstanding Filipino college graduates. It covers 100% of international tuition fees, laboratory charges, global travel costs, visa fees, and delivers a premium monthly living allowance of 1,400 EUR (approximately 88,000 PHP) for the entire 2-year graduate duration. Recipients study in at least three distinct European universities across different EU nations. It requires an elite undergraduate academic record (GWA 90% or equivalent), a comprehensive statement of purpose, academic essays, and dual letters of recommendation. Portals open annually in October.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private|Public", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All approved European joint master tracks", "max_income_threshold": null, "min_gwa_normalized": "90", "min_age": null, "max_age": null, "priority_groups": "Filipino Global Scholars", "benefit_tuition": "true", "benefit_allowance_monthly": "88000", "benefit_books": "true", "benefit_total_value": "2200000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-10-01", "application_deadline": "2027-01-15", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2025-10-05", "last_close_date": "2026-01-20", "is_active": "true", "source_slug": "erasmus_mundus_ph_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://erasmus-plus.ec.europa.eu|https://www.eeas.europa.eu/philippines", "dedupe_rationale": "Elite international bilateral master''s track with multi-country EU residency."}', 'approved', '1b64766f18c2792941a97200dc3231c8d4d223454aad4cfc2f24b7e73306cbce', '2026-06-30 12:29:13.395770', '2026-06-30 12:32:00.402078');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (61, 'Taiwan ICDF Higher Education Scholarship Program', 'Taiwan International Cooperation and Development Fund', 'gemini_research', '{"title": "Taiwan ICDF Higher Education Scholarship Program", "provider": "Taiwan International Cooperation and Development Fund", "source": "gemini_research", "link": "https://www.icdf.org.tw", "description": "The Taiwan ICDF Higher Education Scholarship Program is a full international bilateral grant offered to Filipino citizens for Master''s or Doctoral programs at partner Taiwanese universities. It provides full tuition coverage, modern campus housing, comprehensive health insurance, and a monthly stipend of 18,000 TWD (Master''s) or 20,000 TWD (PhD) (approximately 32,000 to 36,000 PHP). Focus areas are restricted to STEM, tropical agriculture, and electronic engineering. Requires an undergraduate GWA of 85% or better and an interview by the Taipei Economic and Cultural Office (TECO) in Manila.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|Agriculture", "eligible_courses_specific": "STEM and Tropical Agriculture fields", "max_income_threshold": null, "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Advanced Tech Researchers", "benefit_tuition": "true", "benefit_allowance_monthly": "35000", "benefit_books": "true", "benefit_total_value": "900000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-01-01", "application_deadline": "2026-03-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-01-05", "last_close_date": "2025-03-15", "is_active": "false", "source_slug": "taiwan_icdf_scholarship_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://www.icdf.org.tw|https://www.roc-taiwan.org/ph", "dedupe_rationale": "Bilateral international postgraduate track managed by TECO Manila."}', 'approved', '2e437df68438629c31bbb10fe3ca30242d228a95586eaa59c0d4364a61c2881a', '2026-06-30 12:29:13.395770', '2026-06-30 12:31:33.759816');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (62, 'Aboitiz Future Leaders Scholarship Program', 'Aboitiz Foundation', 'gemini_research', '{"title": "Aboitiz Future Leaders Scholarship Program", "provider": "Aboitiz Foundation", "source": "gemini_research", "link": "https://aboitiz.com/aboitiz-foundation/aboitiz-future-leaders-scholarship", "description": "Corporate scholarship for incoming sophomore students enrolled in partner state universities in engineering, data science, communications, and related fields. Covers full tuition, monthly allowance, and academic excellence incentives. Requires cumulative first-year GWA of 2.0 or better on the UP scale with no failing or incomplete grades, plus a mandatory 400-hour internship within Aboitiz Group business units.", "provider_type": "Private", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Business|Agriculture|Arts", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|GOOD_MORAL|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-04-28", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "aboitiz_future_leaders_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://aboitiz.com/aboitiz-foundation/aboitiz-future-leaders-scholarship|https://sikap.upd.edu.ph/posts/scholarships/128/", "dedupe_rationale": "Sophomore-only corporate pipeline restricted to Aboitiz partner SUCs, distinct from freshman merit programs."}', 'approved', '5cf484eb13401735370c1a99d50099875af66010f68c0bc36c471336040eb52a', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:04.574530');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (63, 'Bagong Pilipinas Merit Scholarship Program (BPMSP) - Higher Education Track', 'Commission on Higher Education', 'gemini_research', '{"title": "Bagong Pilipinas Merit Scholarship Program (BPMSP) - Higher Education Track", "provider": "Commission on Higher Education", "source": "gemini_research", "link": "https://bpms.ched.gov.ph/", "description": "National merit scholarship for incoming college freshmen under the Bagong Pilipinas framework. SUC scholars receive full tuition; private HEI scholars receive up to 45000 PHP annually for tuition and fees plus a 45000 PHP annual stipend. Requires minimum 95% SHS GWA or top-five batch ranking and combined household income up to 2000000 PHP per year.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Agriculture|Medical|IT|Education", "eligible_courses_specific": null, "max_income_threshold": "2000000", "min_gwa_normalized": "95", "min_age": null, "max_age": null, "priority_groups": "Underprivileged|PWD|IP|Solo Parent Dependent", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "90000", "required_documents": "FORM_137|TOR|ITR|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2026-04-30", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "bpmsp_higher_education_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://bpms.ched.gov.ph/", "dedupe_rationale": "Higher Education Track under BPMSP with 95% GWA and 2M income ceiling, separate from the TVET diploma track."}', 'approved', '42b4110d947630d90a66f2516226584028bd6d3319ed2ac3e2a32ee054bdcb23', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:05.381868');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (64, 'Bagong Pilipinas Merit Scholarship Program (BPMSP) - TVET Track', 'Technical Education and Skills Development Authority', 'gemini_research', '{"title": "Bagong Pilipinas Merit Scholarship Program (BPMSP) - TVET Track", "provider": "Technical Education and Skills Development Authority", "source": "gemini_research", "link": "https://bpms.ched.gov.ph/", "description": "TVET diploma track under the joint CHED-DepEd-TESDA Bagong Pilipinas Merit Scholarship Program. Targets priority diploma programs with minimum 90% GWA and combined household income up to 2000000 PHP. Includes mandatory return-of-service of one year in the Philippines for every year of funding.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": "2000000", "min_gwa_normalized": "90", "min_age": null, "max_age": null, "priority_groups": "Underprivileged|PWD|IP|Solo Parent Dependent", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|TOR|ITR|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2026-04-30", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "bpmsp_tvet_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://bpms.ched.gov.ph/", "dedupe_rationale": "TVET diploma track with 90% GWA threshold, distinct from the BPMSP Higher Education baccalaureate track."}', 'approved', '42b75c071dcc82f1746c7fbd569c0c1ba990bc05ad9f44c2cc2ced4840c73aac', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:06.350744');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (65, 'GSIS Subsidy for STEM Program (GSSP)', 'Government Service Insurance System', 'gemini_research', '{"title": "GSIS Subsidy for STEM Program (GSSP)", "provider": "Government Service Insurance System", "source": "gemini_research", "link": "https://www.gsis.gov.ph", "description": "New STEM-focused subsidy for children of active GSIS members and permanent total disability pensioners under 60. Supports CHED-recognized STEM degree programs for college freshmen with minimum 90% SHS GWA. Provides 15000 PHP annual subsidy per scholar, prioritizing parents in Salary Grade 15 and below.", "provider_type": "Government", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Medical", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": "90", "min_age": null, "max_age": null, "priority_groups": "PWD|IP|Solo Parent Dependent", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "15000", "required_documents": "BIRTH_CERT|FORM_137|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-30", "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "gsis_gssp_2026", "research_notes": "application_status=opening_soon | confidence=high | link_quality=primary", "source_urls": "https://www.gsis.gov.ph/2026/01/06/gsis-to-launch-stem-scholarship-this-year/|https://www.gsis.gov.ph/tag/stem/", "dedupe_rationale": "STEM-restricted GSIS member-dependent subsidy launching AY 2026-2027, distinct from the flat-rate GESP grant."}', 'approved', '5766819df7beb811120099cc1e4dea680671fefae2f6a119d0c9f58c015d52ff', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:07.192524');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (66, 'CHED Merit Scholarship Program (CMSP)', 'Commission on Higher Education', 'gemini_research', '{"title": "CHED Merit Scholarship Program (CMSP)", "provider": "Commission on Higher Education", "source": "gemini_research", "link": "https://legacy.ched.gov.ph/merit-scholarship/", "description": "Legacy CHED merit program for incoming college freshmen with minimum 93% GWA and combined annual household income up to 500000 PHP. Covers tuition and fees for scholars in CHED-recognized programs nationwide. Open for AY 2026-2027 applications.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Medical|Business|Education|Agriculture|Arts|Architecture", "eligible_courses_specific": null, "max_income_threshold": "500000", "min_gwa_normalized": "93", "min_age": null, "max_age": null, "priority_groups": "Underprivileged|PWD|IP|Solo Parent Dependent", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|TOR|ITR|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-22", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "ched_cmsp_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://legacy.ched.gov.ph/merit-scholarship/", "dedupe_rationale": "Legacy CMSP with 93% GWA and 500K income cap, separate from the newer BPMSP with higher thresholds."}', 'approved', '1d3f4b5c554a0364286d89049633c52a0085a3d94ded82ffb59c47b98e7628d0', '2026-06-30 13:50:54.073056', '2026-07-26 09:42:48.820769');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (67, 'DOST-SEI Undergraduate Scholarships (RA 7687 / Merit)', 'DOST-SEI', 'gemini_research', '{"title": "DOST-SEI Undergraduate Scholarships (RA 7687 / Merit)", "provider": "DOST-SEI", "source": "gemini_research", "link": "https://www.science-scholarships.ph/", "description": "Premier national science scholarship for four- or five-year baccalaureate degrees in science and technology. RA 7687 targets underprivileged students; Merit track is open regardless of income. Benefits include tuition up to 40000 PHP per year, 8000 PHP monthly living allowance, and 10000 PHP annual learning materials allowance.", "provider_type": "Government", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Medical|Agriculture", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": "Underprivileged", "benefit_tuition": "true", "benefit_allowance_monthly": "8000", "benefit_books": "true", "benefit_total_value": "106000", "required_documents": "FORM_137|BIRTH_CERT|GOOD_MORAL|ITR", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2025-10-13", "application_deadline": "2025-11-22", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-10-13", "last_close_date": "2025-11-22", "is_active": "false", "source_slug": "dost_sei_undergraduate_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.science-scholarships.ph/|https://governmentph.com/dost-scholarship-online/", "dedupe_rationale": "Flagship DOST-SEI undergraduate RA 7687 and Merit combined entry, distinct from the JLSS third-year track."}', 'approved', 'c4a49cc2d697a72593b01240f5b24767e0b44f1d0104c5b1deae413c2516c6f7', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:01.574280');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (68, 'DOST-SEI Junior Level Science Scholarship (JLSS)', 'DOST-SEI', 'gemini_research', '{"title": "DOST-SEI Junior Level Science Scholarship (JLSS)", "provider": "DOST-SEI", "source": "gemini_research", "link": "https://www.science-scholarships.ph/", "description": "Scholarship for incoming third-year college students pursuing science and technology degrees. Requires strong university GWA and completion of the first two years of a four- or five-year STEM program. Provides tuition, monthly living allowance, and learning materials support similar to the undergraduate program.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Medical|Agriculture", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": "8000", "benefit_books": "true", "benefit_total_value": "106000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": "2026-04-13", "application_deadline": "2026-05-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2026-04-13", "last_close_date": "2026-05-15", "is_active": "false", "source_slug": "dost_sei_jlss_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.science-scholarships.ph/|https://governmentph.com/dost-jlss-scholarship/", "dedupe_rationale": "JLSS targets incoming third-year STEM students only, not freshmen covered by the main DOST-SEI undergraduate program."}', 'approved', '000076de633aa9d9c7da9c22f957cf4130c666ae325a19a5660c724ba561d96e', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:10.777379');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (69, 'SM Foundation College Scholarship Program', 'SM Foundation', 'gemini_research', '{"title": "SM Foundation College Scholarship Program", "provider": "SM Foundation", "source": "gemini_research", "link": "https://scholarship.sm-foundation.org/", "description": "Corporate scholarship for graduating Grade 12 students from public schools or private voucher completers with household income up to 250000 PHP per year and minimum 92% GWA. Covers full tuition and fees plus monthly stipend at partner schools across designated regions. Includes semestral employment and post-graduation job placement within the SM Group.", "provider_type": "Private", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR|Region III - Central Luzon|Region IV-A - Calabarzon|Region V - Bicol|Region VI - Western Visayas|Region VII - Central Visayas|Region VIII - Eastern Visayas|Region IX - Zamboanga Peninsula|Region X - Northern Mindanao|Region XI - Davao|Region XII - Soccsksargen|Region XIII - Caraga", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Business|Education", "eligible_courses_specific": null, "max_income_threshold": "250000", "min_gwa_normalized": "92", "min_age": null, "max_age": null, "priority_groups": "Underprivileged", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|BIRTH_CERT|ITR|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-02-01", "application_deadline": "2026-02-28", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2026-02-01", "last_close_date": "2026-02-28", "is_active": "false", "source_slug": "sm_foundation_college_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://scholarship.sm-foundation.org/|https://www.sm-foundation.org/what_we_do/college-scholarship-program/", "dedupe_rationale": "SM Foundation freshman pipeline restricted to partner-school regions, not a nationwide open-enrollment grant."}', 'approved', '406af518060aac6cfb417a6863bc06f676c7619931138f046b6e972569e8e358', '2026-06-30 13:50:54.073056', '2026-07-26 09:42:49.911808');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (70, 'MEXT Scholarship - Research Category', 'JICC / Embassy of Japan', 'gemini_research', '{"title": "MEXT Scholarship - Research Category", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for Filipino college graduates pursuing master''s or doctoral degrees in Japan. Requires a feasible research proposal in humanities, social sciences, or natural sciences. Provides tuition, monthly stipend, regional allowance, and roundtrip airfare. Applicants must be under 35 years old.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": "35", "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|BIRTH_CERT|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-04-22", "application_deadline": "2026-05-29", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2026-04-22", "last_close_date": "2026-05-29", "is_active": "false", "source_slug": "mext_research_2027", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html|https://www.ph.emb-japan.go.jp/itpr_en/11_000001_02213.html", "dedupe_rationale": "MEXT graduate research track for master''s and doctoral study in Japan, separate from undergraduate and TVET MEXT categories."}', 'approved', '1fb7461dbe7c0e860edbe8d5a3a7d21782abd423114363c32be331b7d3e6c528', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:12.150326');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (71, 'MEXT Scholarship - Undergraduate Track', 'JICC / Embassy of Japan', 'gemini_research', '{"title": "MEXT Scholarship - Undergraduate Track", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for high school graduates pursuing undergraduate degrees in Japan. Open to applicants under 25 with strong academic records. Covers tuition, monthly stipend, and roundtrip travel for full degree study in Japan.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": "25", "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-04-22", "application_deadline": "2026-05-29", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2026-04-22", "last_close_date": "2026-05-29", "is_active": "false", "source_slug": "mext_undergraduate_2027", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html|https://www.ph.emb-japan.go.jp/itpr_en/11_000001_02213.html", "dedupe_rationale": "MEXT undergraduate degree track for high school graduates, distinct from graduate research and technical training categories."}', 'approved', 'b98ce184251e07e9a4360cf960facb8451cb96c4f81f322288d39861e44e619c', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:13.659046');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (72, 'MEXT Scholarship - Specialized Training Track', 'JICC / Embassy of Japan', 'gemini_research', '{"title": "MEXT Scholarship - Specialized Training Track", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for vocational and specialized training programs in Japan. Targets high school graduates under 25 seeking technical skills development. Provides tuition, stipend, and travel support for designated training courses.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": "25", "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-04-22", "application_deadline": "2026-05-29", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2026-04-22", "last_close_date": "2026-05-29", "is_active": "false", "source_slug": "mext_specialized_training_2027", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html|https://www.ph.emb-japan.go.jp/itpr_en/11_000001_02213.html", "dedupe_rationale": "MEXT TVET and specialized training track, not an undergraduate or graduate research degree pathway."}', 'approved', 'dc045dea30a0609e70822fb1954b2945bd8e7f0a0ab3e3c2251a76bb793e4ce3', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:14.755472');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (73, 'MEXT Scholarship - College of Technology (KOSEN)', 'JICC / Embassy of Japan', 'gemini_research', '{"title": "MEXT Scholarship - College of Technology (KOSEN)", "provider": "JICC / Embassy of Japan", "source": "gemini_research", "link": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html", "description": "Japanese Government MEXT scholarship for the College of Technology (KOSEN) five-year engineering program in Japan. Combines college and TVET-level technical training for high school graduates under 25. Covers tuition, stipend, and roundtrip airfare.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College|TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": "25", "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-04-22", "application_deadline": "2026-05-29", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2026-04-22", "last_close_date": "2026-05-29", "is_active": "false", "source_slug": "mext_kosen_2027", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.ph.emb-japan.go.jp/itpr_en/00_000193.html|https://www.ph.emb-japan.go.jp/itpr_en/11_000001_02213.html", "dedupe_rationale": "MEXT KOSEN five-year engineering technology program, distinct from standard undergraduate and specialized training tracks."}', 'approved', 'dda1cc980df4a923ac0fcefd92be8d8dc68380a4c0ef56f9dfa48776ccdc1ef4', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:15.403457');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (74, 'GSIS Educational Subsidy Program (GESP)', 'Government Service Insurance System', 'gemini_research', '{"title": "GSIS Educational Subsidy Program (GESP)", "provider": "Government Service Insurance System", "source": "gemini_research", "link": "https://www.gsis.gov.ph", "description": "Flat-rate educational grant of 10000 PHP for dependents of active GSIS members and permanent total disability pensioners. Open to all college courses without STEM restriction. Historically offered as a broad welfare benefit before the launch of the STEM-specific GSSP.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "10000", "required_documents": "BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "false", "source_slug": "gsis_gesp_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.gsis.gov.ph/tag/scholarship/", "dedupe_rationale": "Flat-rate GESP grant for all courses, not the new STEM-restricted GSSP with higher academic requirements."}', 'approved', '50ac2af74ada56952b4e3876e13fa8f294e56b2e5a256b23d3d071bb8d4d9b3c', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:16.044481');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (75, 'OWWA Education for Development Scholarship (EDSP)', 'Overseas Workers Welfare Administration', 'gemini_research', '{"title": "OWWA Education for Development Scholarship (EDSP)", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://scholarship.owwa.gov.ph/", "description": "Competitive scholarship for high-performing dependents of active OWWA members. Freshmen must be single, under 21, with SHS GWA of at least 80% and must pass the DOST-SEI qualifying exam. Provides up to 60000 PHP per school year for any four- or five-year baccalaureate course.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": "80", "min_age": null, "max_age": "21", "priority_groups": "OFW Dependent", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "60000", "required_documents": "BIRTH_CERT|FORM_137|TOR|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2025-11-10", "application_deadline": "2025-11-28", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-11-10", "last_close_date": "2025-11-28", "is_active": "false", "source_slug": "owwa_edsp_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://scholarship.owwa.gov.ph/|https://owwascholarship.ph/edsp-education-for-development-scholarship-program/", "dedupe_rationale": "EDSP merit track requiring DOST qualifying exam and 80% GWA, distinct from the need-based ODSP."}', 'approved', 'ddab3d74bb4b8e7805152a81ee949783e8eef86b318a64d3b826b1743894ed0b', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:16.663481');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (76, 'OWWA OFW Dependent Scholarship Program (ODSP)', 'Overseas Workers Welfare Administration', 'gemini_research', '{"title": "OWWA OFW Dependent Scholarship Program (ODSP)", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://scholarship.owwa.gov.ph/", "description": "Need-based scholarship for dependents of active OWWA members whose monthly salary does not exceed USD 600. Provides 20000 PHP per school year for baccalaureate or associate courses. Requires minimum 80% GWA for continuing eligibility.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "OFW Dependent", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "20000", "required_documents": "BIRTH_CERT|FORM_137|ITR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "false", "source_slug": "owwa_odsp_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://scholarship.owwa.gov.ph/|https://scholarshipsfree.com/odsp-owwa-scholarship-2026-2027/", "dedupe_rationale": "ODSP need-based grant for lower-salary OFW families, separate from the competitive EDSP merit track."}', 'approved', 'aa883d1b665b54cb1263b26ac822847559806f2bd44e6e3718138298c70fd548', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:17.867653');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (77, 'OWWA Congressional Migrant Workers Scholarship (CMWSP)', 'Overseas Workers Welfare Administration', 'gemini_research', '{"title": "OWWA Congressional Migrant Workers Scholarship (CMWSP)", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://scholarship.owwa.gov.ph/", "description": "Congressional-funded scholarship for active OWWA members or dependents with combined household income of USD 2400 or less per year. Restricted to prioritized science and technology courses. Provides up to 60000 PHP per academic year with minimum 80% GWA requirement.", "provider_type": "Government", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Medical|Agriculture", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": "80", "min_age": null, "max_age": null, "priority_groups": "OFW Dependent", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "60000", "required_documents": "BIRTH_CERT|FORM_137|TOR|ITR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2025-11-10", "application_deadline": "2025-11-28", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-11-10", "last_close_date": "2025-11-28", "is_active": "false", "source_slug": "owwa_cmwsp_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://scholarship.owwa.gov.ph/|https://owwascholarship.ph/", "dedupe_rationale": "CMWSP STEM-restricted congressional allocation, distinct from EDSP and ODSP OWWA tracks."}', 'approved', 'faae3af9baaf7bd6aa26dd292eede4fe82dd91bfe6ebb30e79105fbe1b4f5eaf', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:18.775150');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (78, 'Quezon City Scholarship Program (QCSP)', 'Quezon City Government', 'gemini_research', '{"title": "Quezon City Scholarship Program (QCSP)", "provider": "Quezon City Government", "source": "gemini_research", "link": "https://qceservices.quezoncity.gov.ph", "description": "City-wide LGU scholarship covering senior high school, vocational, college, and postgraduate students who are Quezon City residents with verified QCitizen ID. Directs 70% of tertiary slots to low-income and marginalized sectors. Supported 9377 active scholars in the most recent cycle.", "provider_type": "LGU", "scholarship_type": "Need", "eligible_levels": "High School|College|TVET|Graduate", "eligible_regions": "NCR", "eligible_cities": "Quezon City", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": "Underprivileged|PWD|4Ps|Listahanan", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR|4PS_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-25", "application_deadline": "2026-06-05", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2026-05-25", "last_close_date": "2026-06-05", "is_active": "false", "source_slug": "quezon_city_qcsp_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://qceservices.quezoncity.gov.ph|https://quezoncity.gov.ph/application-for-qc-scholarship-program-opens/", "dedupe_rationale": "General QCSP city-wide need-based program, separate from the specialized Manuel L. Quezon Filipino language track."}', 'approved', '7d84cc506551d7e1c2e7236ed4839e5873497d0da51320b6adddfec278234d80', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:19.785275');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (79, 'Manuel L. Quezon Filipino Language and Literature Scholarship Program', 'Quezon City Government', 'gemini_research', '{"title": "Manuel L. Quezon Filipino Language and Literature Scholarship Program", "provider": "Quezon City Government", "source": "gemini_research", "link": "https://qceservices.quezoncity.gov.ph", "description": "Specialized Quezon City LGU humanities scholarship for college students, researchers, and educators pursuing Filipino language and literature. Requires QC residency and QCitizen verification. Counterpart to STEM-focused national programs, preserving cultural capital.", "provider_type": "LGU", "scholarship_type": "Merit-based", "eligible_levels": "College|Graduate", "eligible_regions": "NCR", "eligible_cities": "Quezon City", "residency_required": "true", "eligible_school_types": "Public|Private", "eligible_courses_psced": "Arts", "eligible_courses_specific": "Filipino Language and Literature", "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "BARANGAY_CERT|BIRTH_CERT|TOR|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-05-25", "application_deadline": "2026-06-05", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2026-05-25", "last_close_date": "2026-06-05", "is_active": "false", "source_slug": "quezon_city_filipino_language_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://qceservices.quezoncity.gov.ph|https://quezoncity.gov.ph/application-for-qc-scholarship-program-opens/", "dedupe_rationale": "Specialized Filipino language and literature humanities track, not the general QCSP need-based program."}', 'approved', 'b4c4864d2d8a19bb22fd3b89cad298141cfc60cb0a6bbc3935dbfc47e5fc6766', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:21.968915');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (80, 'Australia Awards Scholarships (Philippines)', 'Australian Government', 'gemini_research', '{"title": "Australia Awards Scholarships (Philippines)", "provider": "Australian Government", "source": "gemini_research", "link": "https://www.australiaawardsphilippines.org/scholarships", "description": "Fully funded master''s degrees at Australian universities for Filipino citizens with at least 12 months Philippine residency and two years cumulative work experience. Covers tuition, return air travel, establishment allowance, living expenses, and health insurance. Requires a Re-Entry Action Plan for development work upon return.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": "STEM|Agriculture|IT|Business|Education|Arts", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|ESSAY|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-02-01", "application_deadline": "2026-04-30", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": "2026-02-01", "last_close_date": "2026-04-30", "is_active": "false", "source_slug": "australia_awards_2027", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.australiaawardsphilippines.org/scholarships|https://philippines.embassy.gov.au/mnla/MR100326.html", "dedupe_rationale": "Australian Government bilateral master''s program with REAP return obligation, not a domestic Philippine grant."}', 'approved', '48d82cd1dbd4b4e6781e3f55aa42dbb3c3361ec47210d193eb5666e502f70aab', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:03.647858');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (81, 'Fulbright-PhilSA Graduate Program', 'PAEF / PhilSA', 'gemini_research', '{"title": "Fulbright-PhilSA Graduate Program", "provider": "PAEF / PhilSA", "source": "gemini_research", "link": "https://apply.iie.org/ffsp2027", "description": "Bi-national Fulbright-Philippine Space Agency program financing master''s and doctoral degrees in the United States in space science and technology applications. Fully funded including tuition, travel, maintenance, and health insurance. Requires relevant college degree, two years post-college work experience, and return-to-Philippines service obligation.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": "STEM|Engineering|IT", "eligible_courses_specific": "Space Science and Technology Applications", "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|ESSAY|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": null, "application_deadline": "2026-06-19", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": null, "last_close_date": "2026-06-19", "is_active": "false", "source_slug": "fulbright_philsa_2027", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://apply.iie.org/ffsp2027|https://www.fulbright.org.ph/index.php/services/10-scholarship-programs/296-fulbright-philsa-foreign-student-program|https://philsa.gov.ph/news/fulbright-philippine-space-agency-foreign-student-program-in-space-science-and-technology-applications-ssta-2026-2027-call-for-applications/", "dedupe_rationale": "Fulbright-PhilSA space technology specialization, distinct from general Australia Awards or Chevening programs."}', 'approved', '34ec18f401d2a178c9128f3546c509af797b6a14e12120834b26b0a0eb7a18bd', '2026-06-30 13:50:54.073056', '2026-06-30 13:53:23.945344');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (82, 'Chevening Scholarship', 'FCDO / UK Government', 'gemini_research', '{"title": "Chevening Scholarship", "provider": "FCDO / UK Government", "source": "gemini_research", "link": "https://www.chevening.org/apply", "description": "UK Government fully funded one-year master''s program in the United Kingdom. Highly competitive global selection based on leadership, networking, career plan, and study proposal. Requires at least 2800 hours of post-graduation work experience and two-year return commitment to the Philippines after completion.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|ESSAY|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-08-05", "application_deadline": "2026-10-07", "academic_year_target": "2027-2028", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "chevening_2027", "research_notes": "application_status=opening_soon | confidence=high | link_quality=primary", "source_urls": "https://www.chevening.org/apply|https://www.chevening.org/resource-hub/guidance/eligibility/", "dedupe_rationale": "UK Chevening one-year master''s with leadership essays, separate from Australia Awards and Fulbright-PhilSA tracks."}', 'approved', '120789cadb8a3913a82f123fb705bd5652df92c0f9971b