INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (83, 'Global Korea Scholarship (GKS) Graduate', 'NIIED', 'gemini_research', '{"title": "Global Korea Scholarship (GKS) Graduate", "provider": "NIIED", "source": "gemini_research", "link": "https://www.studyinkorea.go.kr", "description": "South Korean government scholarship for master''s and doctoral degrees including mandatory one-year Korean language training. Provides round-trip airfare, tuition, living allowance, and health insurance. Embassy Track allows applying to up to three universities; applicants must be under 40.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": null, "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": "40", "priority_groups": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|ESSAY|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": "2026-02-12", "application_deadline": "2026-02-25", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2026-02-12", "last_close_date": "2026-02-25", "is_active": "false", "source_slug": "gks_graduate_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.studyinkorea.go.kr|https://www.studyinkorea.go.kr/ko/plan/gksNoticeRead.do?bbsId=BBSMSTR_000000000461&nttId=4420", "dedupe_rationale": "GKS graduate degree track with language training requirement, distinct from the GKS undergraduate program."}', 'approved', '3bc278ebc5f