INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (85, 'CHED-UniFAST Tertiary Education Subsidy (TES)', 'UniFAST / CHED', 'gemini_research', '{"title": "CHED-UniFAST Tertiary Education Subsidy (TES)", "provider": "UniFAST / CHED", "source": "gemini_research", "link": "https://tes.unifast.gov.ph", "description": "National need-based tertiary education subsidy administered through HEIs via the UniFAST portal. Targets underprivileged and 4Ps/Listahanan students enrolled in CHED-recognized programs. Provides allowance for tuition gaps, books, and living expenses based on prioritization guidelines.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": "Underprivileged|4Ps|Listahanan", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "true", "benefit_total_value": null, "required_documents": "TOR|4PS_CERT|BIRTH_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "false", "source_slug": "unifast_tes_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://tes.unifast.gov.ph|https://quezoncity.gov.ph/wp-content/uploads/2024/03/2.-CHED-%E2%80%93-UNIFAST-Tertiary-Education-Subsidy-TES.pdf", "dedupe_rationale": "UniFAST TES need-based allowance via HEI disbursement, not a competitive merit scholarship like CMSP or BPMSP."}', 'approved', '82a6f65124232111056368e46bedf3a7d580bf8c7a7e400d4d6809e4161405f7', '2026-06-30 13:50:54.073056', '2026-06-30 13:52:53.262131');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (86, 'TESDA Private Education Student Financial Assistance', 'TESDA', 'gemini_research', '{"title": "TESDA Private Education Student Financial Assistance", "provider": "TESDA", "source": "gemini_research", "link": "https://www.tesda.gov.ph", "description": "TESDA-administered financial assistance for students in private TVET institutions. Rolling applications processed through regional and provincial TESDA offices. Targets underprivileged learners pursuing technical-vocational education and training programs.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Private", "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": "Underprivileged", "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "BIRTH_CERT|FORM_137|BARANGAY_CERT", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "rolling", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "tesda_pesfa_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://www.tesda.gov.ph/about/tesda/1279", "dedupe_rationale": "TESDA private TVET rolling assistance via regional offices, distinct from BPMSP TVET merit track."}', 'approved', '289e9f49bc958f9cc56f7daa18e02d4a74aeb23244259c060dcc1c9b36037daf', '2026-06-30 13:50:54.073056', '2026-06-30 13:52:54.690699');
