INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (100, 'OWWA Education and Livelihood Assistance Program (ELAP)', 'Overseas Workers Welfare Administration (OWWA)', 'discovery_verification', '{"title": "OWWA Education and Livelihood Assistance Program (ELAP)", "provider": "Overseas Workers Welfare Administration (OWWA)", "source": "discovery_verification", "link": "https://owwa.gov.ph/education-and-livelihood-assistance-program-elap/", "description": "Humanitarian educational and livelihood assistance for dependents of deceased active OWWA members or dependents of OFWs incarcerated/convicted with death penalty abroad.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College|Senior High School", "eligible_regions": null, "eligible_cities": null, "residency_required": null, "eligible_school_types": null, "eligible_courses_psced": null, "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": "OFW Dependents|Survivors", "members_only": "true", "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": "15000", "required_documents": "OWWA membership record|Death certificate or incarceration proof|School records", "has_qualifying_exam": null, "has_interview": null, "has_essay_requirement": null, "has_return_service": "false", "application_open_date": null, "application_deadline": null, "academic_year_target": null, "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "owwa_elap", "research_notes": "verification_confidence=verified | application_status=open | discovery_classification=add_immediately | legal_basis=OWWA benefit program | aliases=ELAP|ELAP Educational Assistance", "source_urls": "https://owwa.gov.ph/education-and-livelihood-assistance-program-elap/|https://owwa.gov.ph/wp-content/uploads/2026/05/OWWA_CC_2026v3.pdf", "dedupe_rationale": "Educational assistance PHP 5,000 elementary PHP 8,000 secondary PHP 10,000 college per school year; livelihood PHP 15,000"}', 'approved', '44835068a1ad2f9d1081af860991d2aab6c5c99b8d721985175862d0703c8c5f', '2026-07-26 09:40:52.568023', '2026-07-26 09:42:57.851798');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (101, 'DOH Medical Scholarship and Return Service Program', 'Department of Health', 'gemini_research', '{"title": "DOH Medical Scholarship and Return Service Program", "provider": "Department of Health", "source": "gemini_research", "link": "https://doh.gov.ph", "description": "The DOH Medical Scholarship and Return Service (MSRS) Program is a major sector-specific government intervention operating under the ''Doktor Para sa Bayan'' Act (RA 11509) in partnership with CHED. It funds full medical education (Doctor of Medicine) for qualified Filipino students across certified state and partner private universities. It covers 100% of tuition, laboratory fees, provides a high monthly living allowance of 15,000 PHP, a specialized book/equipment allowance of 20,000 PHP per semester, and basic board exam review subsidies. Eligible applicants must hold a Bachelor''s degree with a solid GWA, pass the medical school entrance and NMAT, and prioritize low-income roots or origin from underserved rural towns. Return service requires serving as a public health officer in a government hospital or rural health unit (RHU) for 1 year for every year of scholarship.", "provider_type": "Government", "scholarship_type": "Merit-and-Need", "eligible_levels": "Graduate", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "Medical", "eligible_courses_specific": "Doctor of Medicine (MD)", "max_income_threshold": "600000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Rural Public Health", "members_only": null, "benefit_tuition": "true", "benefit_allowance_monthly": "15000", "benefit_books": "true", "benefit_total_value": "250000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL|ITR|ESSAY", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "true", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-15", "last_close_date": "2025-07-05", "is_active": "false", "source_slug": "doh_msrs_doctor_2026", "research_notes": "application_status=closed_reference | confidence=high | link_quality=primary", "source_urls": "https://doh.gov.ph|https://ched.gov.ph", "dedupe_rationale": "National statutory medical track under RA 11509 with comprehensive returns."}', 'approved', 'ad8af4e5d4e5af8416cecfc4c83ab2b9ab44b2bba9923ae242f0ec3560c904f2', '2026-07-26 09:40:55.736854', '2026-07-26 09:42:58.782386');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (102, 'Aboitiz Future Leaders Scholarship Program', 'Aboitiz Foundation', 'gemini_research', '{"title": "Aboitiz Future Leaders Scholarship Program", "provider": "Aboitiz Foundation", "source": "gemini_research", "link": "https://aboitiz.com/aboitiz-foundation/aboitiz-future-leaders-scholarship", "description": "Corporate scholarship for incoming sophomore students enrolled in partner state universities in engineering, data science, communications, and related fields. Covers full tuition, monthly allowance, and academic excellence incentives. Requires cumulative first-year GWA of 2.0 or better on the UP scale with no failing or incomplete grades, plus a mandatory 400-hour internship within Aboitiz Group business units.", "provider_type": "Private", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public", "eligible_courses_psced": "STEM|Engineering|IT|Business|Agriculture|Arts", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": null, "members_only": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|GOOD_MORAL|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": "2026-04-28", "application_deadline": "2026-06-30", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "aboitiz_future_leaders_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://aboitiz.com/aboitiz-foundation/aboitiz-future-leaders-scholarship|https://sikap.upd.edu.ph/posts/scholarships/128/", "dedupe_rationale": "Sophomore-only corporate pipeline restricted to Aboitiz partner SUCs, distinct from freshman merit programs."}', 'approved', '5cf484eb13401735370c1a99d50099875af66010f68c0bc36c471336040eb52a', '2026-07-26 09:40:55.736854', '2026-07-26 09:42:59.779841');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (103, 'OWWA Educational Livelihood Assistance Program College Track', 'Overseas Workers Welfare Administration', 'gemini_research', '{"title": "OWWA Educational Livelihood Assistance Program College Track", "provider": "Overseas Workers Welfare Administration", "source": "gemini_research", "link": "https://owwa.gov.ph", "description": "The OWWA Educational Livelihood Assistance Program (ELAP) College Track is an allocation reserved for the children or dependents of active or deceased Overseas Filipino Workers (OFWs) who faced sudden distress, repatriation, or death while serving abroad. Distinct from the EDSP/ODSP merit lines, ELAP operates primarily as a livelihood-linked equity framework. It guarantees an educational subsidy of 10,000 PHP per year for the designated student dependent enrolled in any undergraduate college or technical track. Academic evaluation relies on basic passing marks (75% GWA) with no explicit ranking requirements. Online processing must clear the OWWA Regional Welfare Offices.", "provider_type": "Government", "scholarship_type": "Need", "eligible_levels": "College|TVET", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Education|Medical|Business|Agriculture|Arts", "eligible_courses_specific": "All accredited lines", "max_income_threshold": "250000", "min_gwa_normalized": "75", "min_age": null, "max_age": null, "priority_groups": "Distressed OFW Dependents", "members_only": null, "benefit_tuition": "false", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "OFW_DOCS|BARANGAY_CERT|BIRTH_CERT|TOR", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-05-01", "application_deadline": "2026-07-15", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": "2025-05-05", "last_close_date": "2025-07-20", "is_active": "true", "source_slug": "owwa_elap_college_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://owwa.gov.ph|https://ro1.owwa.gov.ph", "dedupe_rationale": "OWWA humanitarian track for distressed/repatriated OFW children; low barrier."}', 'approved', '9ccea555637900a7f73841c4a8f85c0c6dc859817a04e77a31e66fd0d20fc29d', '2026-08-01 06:44:07.539874', '2026-08-01 06:44:10.574673');
