INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (105, 'CHED Merit Scholarship Program (CMSP)', 'Commission on Higher Education', 'gemini_research', '{"title": "CHED Merit Scholarship Program (CMSP)", "provider": "Commission on Higher Education", "source": "gemini_research", "link": "https://legacy.ched.gov.ph/merit-scholarship/", "description": "Legacy CHED merit program for incoming college freshmen with minimum 93% GWA and combined annual household income up to 500000 PHP. Covers tuition and fees for scholars in CHED-recognized programs nationwide. Open for AY 2026-2027 applications.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Medical|Business|Education|Agriculture|Arts|Architecture", "eligible_courses_specific": null, "max_income_threshold": "500000", "min_gwa_normalized": "93", "min_age": null, "max_age": null, "priority_groups": "Underprivileged|PWD|IP|Solo Parent Dependent", "members_only": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|TOR|ITR|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "false", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": "2026-06-22", "application_deadline": "2026-07-31", "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "true", "source_slug": "ched_cmsp_2026", "research_notes": "application_status=open | confidence=high | link_quality=primary", "source_urls": "https://legacy.ched.gov.ph/merit-scholarship/", "dedupe_rationale": "Legacy CMSP with 93% GWA and 500K income cap, separate from the newer BPMSP with higher thresholds."}', 'approved', '1d3f4b5c554a0364286d89049633c52a0085a3d94ded82ffb59c47b98e7628d0', '2026-08-01 06:44:07.539874', '2026-08-01 06:44:12.696529');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (106, 'DOST-SEI Junior Level Science Scholarship (JLSS)', 'DOST-SEI', 'gemini_research', '{"title": "DOST-SEI Junior Level Science Scholarship (JLSS)", "provider": "DOST-SEI", "source": "gemini_research", "link": "https://www.science-scholarships.ph/", "description": "Scholarship for incoming third-year college students pursuing science and technology degrees. Requires strong university GWA and completion of the first two years of a four- or five-year STEM program. Provides tuition, monthly living allowance, and learning materials support similar to the undergraduate program.", "provider_type": "Government", "scholarship_type": "Merit-based", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Medical|Agriculture", "eligible_courses_specific": null, "max_income_threshold": null, "min_gwa_normalized": null, "min_age": null, "max_age": null, "priority_groups": null, "members_only": null, "benefit_tuition": "true", "benefit_allowance_monthly": "8000", "benefit_books": "true", "benefit_total_value": "106000", "required_documents": "TOR|BIRTH_CERT|GOOD_MORAL", "has_qualifying_exam": "true", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "true", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "false", "source_slug": "dost_sei_jlss_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.science-scholarships.ph/|https://governmentph.com/dost-jlss-scholarship/", "dedupe_rationale": "JLSS targets incoming third-year STEM students only, not freshmen covered by the main DOST-SEI undergraduate program."}', 'approved', '000076de633aa9d9c7da9c22f957cf4130c666ae325a19a5660c724ba561d96e', '2026-08-01 06:44:07.539874', '2026-08-01 06:44:13.512949');
INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (107, 'SM Foundation College Scholarship Program', 'SM Foundation', 'gemini_research', '{"title": "SM Foundation College Scholarship Program", "provider": "SM Foundation", "source": "gemini_research", "link": "https://scholarship.sm-foundation.org/", "description": "Corporate scholarship for graduating Grade 12 students from public schools or private voucher completers with household income up to 250000 PHP per year and minimum 92% GWA. Covers full tuition and fees plus monthly stipend at partner schools across designated regions. Includes semestral employment and post-graduation job placement within the SM Group.", "provider_type": "Private", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": "NCR|Region III - Central Luzon|Region IV-A - Calabarzon|Region V - Bicol|Region VI - Western Visayas|Region VII - Central Visayas|Region VIII - Eastern Visayas|Region IX - Zamboanga Peninsula|Region X - Northern Mindanao|Region XI - Davao|Region XII - Soccsksargen|Region XIII - Caraga", "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Business|Education", "eligible_courses_specific": null, "max_income_threshold": "250000", "min_gwa_normalized": "92", "min_age": null, "max_age": null, "priority_groups": "Underprivileged", "members_only": null, "benefit_tuition": "true", "benefit_allowance_monthly": null, "benefit_books": "false", "benefit_total_value": null, "required_documents": "FORM_137|BIRTH_CERT|ITR|GOOD_MORAL", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "false", "has_return_service": "false", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active":