INSERT INTO "scholarships_staging" (id, title, provider, source, payload_json, status, dedupe_key, created_at, reviewed_at) VALUES (108, 'Megaworld Foundation College Scholarship', 'Megaworld Foundation', 'gemini_research', '{"title": "Megaworld Foundation College Scholarship", "provider": "Megaworld Foundation", "source": "gemini_research", "link": "https://www.megaworldfoundation.com/scholarship/apply/form", "description": "Corporate college scholarship for underprivileged students in STEM, engineering, IT, business, and architecture. Requires minimum 85% GWA with zero dropped subjects and combined household income not exceeding 400000 PHP. Covers full tuition and institutional fees plus monthly stipend.", "provider_type": "Private", "scholarship_type": "Merit-and-Need", "eligible_levels": "College", "eligible_regions": null, "eligible_cities": null, "residency_required": "false", "eligible_school_types": "Public|Private", "eligible_courses_psced": "STEM|Engineering|IT|Business|Architecture", "eligible_courses_specific": null, "max_income_threshold": "400000", "min_gwa_normalized": "85", "min_age": null, "max_age": null, "priority_groups": "Underprivileged", "members_only": null, "benefit_tuition": "true", "benefit_allowance_monthly": "2500", "benefit_books": "false", "benefit_total_value": null, "required_documents": "TOR|ITR|BIRTH_CERT|GOOD_MORAL|ESSAY", "has_qualifying_exam": "false", "has_interview": "true", "has_essay_requirement": "true", "has_return_service": "false", "application_open_date": null, "application_deadline": null, "academic_year_target": "2026-2027", "cycle_type": "annual", "last_open_date": null, "last_close_date": null, "is_active": "false", "source_slug": "megaworld_college_2026", "research_notes": "application_status=recurring_unopened | confidence=high | link_quality=primary", "source_urls": "https://www.megaworldfoundation.com/scholarship/apply/form|https://www.megaworldfoundation.com", "dedupe_rationale": "Megaworld Foundation undergrad